-- Phase A: additive, backwards compatible with the currently deployed web.
-- Direct guide_entries privileges remain intact until the held Phase B SQL is
-- reviewed and applied after the controlled-reader clients have shipped.
-- Full editorial guidance lives in private storage and is returned only after
-- an independent read entitlement in the new clients.
create schema if not exists private;

create table if not exists private.guide_member_content (
  guide_id uuid primary key references public.guide_entries(id) on delete cascade,
  content_zh jsonb not null,
  content_en jsonb not null
);
revoke all on private.guide_member_content from public, anon, authenticated;

create table if not exists private.guide_member_filters (
  guide_id uuid primary key references public.guide_entries(id) on delete cascade,
  filters jsonb not null
);
revoke all on private.guide_member_filters from public, anon, authenticated;

create or replace function private.can_read_full_guide(p_user_id uuid)
returns boolean language sql stable security definer set search_path = ''
as $$
  select p_user_id is not null and exists (
    select 1 from public.user_memberships as m
    where m.user_id = p_user_id
      and (
        m.plan = 'admin'
        or (m.plan = 'basic' and m.paid_until > now())
        or (m.plan = 'trial' and m.status = 'trialing'
          and (m.trial_ends_at > now() or
            (m.trial_ends_at is null and exists (
              select 1 from public.users as u
              where u.id = m.user_id and u.is_internal_test = true
            ))))
      )
  );
$$;
revoke all on function private.can_read_full_guide(uuid)
  from public, anon, authenticated, service_role;

create or replace function public.get_public_guide_catalog(
  p_id uuid default null,
  p_offset integer default 0,
  p_limit integer default 500
)
returns table (
  id uuid, category text, name text, name_en text, source text,
  section_id uuid, summary text, summary_en text, content_template text,
  content jsonb, sort_order integer, is_active boolean
)
language sql stable security definer set search_path = ''
as $$
  select e.id, e.category, e.name, e.name_en, e.source,
    e.section_id, e.summary, e.summary_en, e.content_template,
    pg_catalog.jsonb_build_object('filters', case
      when private.can_read_full_guide((select auth.uid())) then
        coalesce(f.filters, '{}'::jsonb) || pg_catalog.jsonb_strip_nulls(pg_catalog.jsonb_build_object(
          'light', e.content #> '{filters,light}',
          'temperature', e.content #> '{filters,temperature}',
          'growth_form', e.content #> '{filters,growth_form}',
          'difficulty', e.content #> '{filters,difficulty}',
          'temperature_min_c', e.content #> '{filters,temperature_min_c}',
          'temperature_max_c', e.content #> '{filters,temperature_max_c}'
        ))
      else '{}'::jsonb end),
    e.sort_order, e.is_active
  from public.guide_entries as e
  left join private.guide_member_filters as f on f.guide_id = e.id
  where e.is_active = true and (p_id is null or e.id = p_id)
  order by e.sort_order asc nulls last, e.name asc, e.id asc
  limit least(greatest(p_limit, 0), 500)
  offset least(greatest(p_offset, 0), 100000);
$$;
revoke all on function public.get_public_guide_catalog(uuid, integer, integer)
  from public, anon, authenticated, service_role;
grant execute on function public.get_public_guide_catalog(uuid, integer, integer)
  to anon, authenticated, service_role;

-- Paid Plus is stored as plan=basic with paid_until; a claimed cloud trial is
-- plan=trial. An expired/read-only membership does not acquire guide access.
-- The decision never reads can_create_content or calls a write-access RPC.
create or replace function public.get_member_guide_content(
  p_id uuid, p_language text default 'zh'
)
returns jsonb language sql stable security definer set search_path = ''
as $$
  select case when p_language = 'en' then
      coalesce(c.content_en, pg_catalog.jsonb_build_object(
        'overview', e.summary_en,
        'parameters', '[{"label":"Scope","value":"Confirm for the specific project"},{"label":"Starting principle","value":"Test at small scale, then adjust"},{"label":"Track","value":"Setup, changes, results, and exceptions"}]'::jsonb,
        'cycle', null,
        'sections', '[{"title":"Before starting","items":["Define the setting, goal, and maintainable scale.","Record baseline conditions so later changes can be compared."]},{"title":"Implement and observe","items":["Change only a few important variables at a time.","Record results consistently before expanding or revising the setup."]}]'::jsonb,
        'cautions', '["This is a general framework. Food, animals, structural safety, and local regulations may require stricter professional guidance."]'::jsonb,
        'sources', '[]'::jsonb)) || coalesce(e.content_en, '{}'::jsonb)
    else
      coalesce(c.content_zh, pg_catalog.jsonb_build_object(
        'overview', e.summary,
        'parameters', '[{"label":"适用对象","value":"按具体项目确认"},{"label":"起步原则","value":"先小规模验证，再逐步调整"},{"label":"记录重点","value":"设置、变化、结果与异常"}]'::jsonb,
        'cycle', null,
        'sections', '[{"title":"开始前","items":["明确使用场景、目标与可维护的规模。","记录现有条件，保留可比较的起点。"]},{"title":"实施与观察","items":["一次只改变少量关键变量。","连续记录结果，再决定是否扩大或调整。"]}]'::jsonb,
        'cautions', '["本页是通用框架；涉及食品、动物、结构安全或当地法规时，应采用更严格的专业要求。"]'::jsonb,
        'sources', '[]'::jsonb)) || coalesce(e.content, '{}'::jsonb)
    end
  from public.guide_entries as e
  left join private.guide_member_content as c on c.guide_id = e.id
  where e.id = p_id and e.is_active = true and p_language in ('zh', 'en')
    and private.can_read_full_guide((select auth.uid()));
$$;
revoke all on function public.get_member_guide_content(uuid, text)
  from public, anon, authenticated, service_role;
grant execute on function public.get_member_guide_content(uuid, text)
  to authenticated, service_role;

-- The following rows are frozen outputs of the previous client-side generator
-- for active non-plant guides. New/edited approved guides can still use the
-- stored content/content_en through the member-only RPC.

insert into private.guide_member_content (guide_id, content_zh, content_en)
select e.id, seed.content_zh, seed.content_en
from (values
  ('insect_fish', 'preset', '矮珍珠', '{"overview":"把铺地草分小丛种稳，比整块厚铺更容易检查成活。","parameters":[{"label":"光照","value":"中至强光"},{"label":"参考水温范围","value":"18–26℃","note":"资料所列范围，并非全程最适温度。"},{"label":"生长方式","value":"前景铺地"},{"label":"难度","value":"较难"}],"cycle":null,"sections":[{"title":"开始前与操作","items":["确认购买的准确品种，分小份留空隙定植，轻轻试查是否扎稳。","保留购买标签或学名；清除运输包装，先把种植位置和入缸状态拍下来。"]},{"title":"日常照护与维护","items":["留意空隙是否长出新枝，修剪过厚草毯并捞净剪屑。","每周同角度拍新芽和老叶；修剪后捞净碎叶，记下光照、施肥或换水的单项变化。"]},{"title":"异常先看这里","items":["整片浮起先查是否过厚、底部失根或固定不稳，分区补植。"]},{"title":"检查提醒","items":["刚定植时先检查是否松脱；修剪、移动灯具或换水后，连续观察新叶而不只看旧叶。"]}],"cautions":["俗名可能对应不同物种；不要凭名称套用统一水温。修剪物不要丢进河道或户外水体。","水温参考品种：Hemianthus callitrichoides ''Cuba''，18–26℃。这是资料所列范围，并非整段都是最适温度；同名水草可能不是同一品种，不要据此骤升骤降水温。"],"sources":[{"title":"Tropica · Planting in the aquarium","url":"https://tropica.com/en/guide/get-the-right-start/planting/"},{"title":"Dennerle — Hemianthus callitrichoides ''Cuba''","url":"https://dennerleplants.com/en/plants/plantdetails/Hemianthus-callitrichoides-%27Cuba%27-%28444%29/27872"}]}'::jsonb, '{"overview":"Establish small portions of carpeting plants rather than one thick mat.","parameters":[{"label":"Light","value":"Medium to high"},{"label":"Reference water-temperature range","value":"18–26°C","note":"Published range, not an optimum throughout."},{"label":"Growth form","value":"Carpet"},{"label":"Difficulty","value":"Advanced"}],"cycle":null,"sections":[{"title":"Start here","items":["Confirm the exact trade species, plant small spaced portions, and check anchoring gently.","Keep the label or scientific name, remove transport packaging, and photograph the planting position and arrival condition."]},{"title":"Routine care","items":["Watch new growth fill gaps, thin thick mats, and remove cuttings.","Photograph new and old leaves weekly; remove pruning debris and log individual changes in light, nutrients, or water."]},{"title":"If something changes","items":["For lifting mats, check excess thickness, root loss, and anchoring; replant in sections."]},{"title":"When to check","items":["Check for loose plants after planting; following pruning, light changes, or water changes, track new growth as well as old leaves."]}],"cautions":["Trade names can cover different species; do not assume one temperature from a name. Keep trimmings out of natural waterways.","Temperature reference: Hemianthus callitrichoides ''Cuba'', 18–26°C. This is a published range, not an ideal setpoint or permission for sudden temperature changes; other species sold under this common name may differ."],"sources":[{"title":"Tropica · Planting in the aquarium","url":"https://tropica.com/en/guide/get-the-right-start/planting/"},{"title":"Dennerle — Hemianthus callitrichoides ''Cuba''","url":"https://dennerleplants.com/en/plants/plantdetails/Hemianthus-callitrichoides-%27Cuba%27-%28444%29/27872"}]}'::jsonb),
  ('system', 'preset', '高床', '{"overview":"让人能在通道完成种植，减少踩踏床内土壤。","parameters":[],"cycle":null,"sections":[{"title":"开始前与操作","items":["先在地面放样并试着够到中央，再装边框；保留通道和排水去向。","按产品说明核对满载重量、连接件和固定方式；先空载装好，再分次放入湿土或花盆。"]},{"title":"日常照护与维护","items":["从通道浇水、施肥和采收；观察土层沉降后再补料。","浇水后检查支脚、接缝和地面积水；固定同一角度拍照，便于发现歪斜和下沉。"]},{"title":"异常先看这里","items":["床边冲刷或积水时查坡向和出口，不用加高边框掩盖问题。"]},{"title":"检查提醒","items":["增加花盆、移动位置和大风后重新检查；发现松动先卸载再修复。"]}],"cautions":["阳台、屋顶和悬挂设施的承重不能靠目测确认；不明承重时先让专业人员核实。"],"sources":[{"title":"UMN Extension · Living soil, healthy garden","url":"https://extension.umn.edu/garden-and-home/yard-and-garden/gardening-minnesota/living-soil-healthy-garden"}]}'::jsonb, '{"overview":"Make the bed reachable from paths so soil need not be walked on.","parameters":[],"cycle":null,"sections":[{"title":"Start here","items":["Mark it on the ground and test reach before installing edges; retain paths and drainage routes.","Check the product''s loaded-weight rating, fasteners, and anchoring; assemble empty and add wet soil or pots in stages."]},{"title":"Routine care","items":["Water, feed, and harvest from paths; observe settlement before topping up.","After watering, inspect feet, joints, and standing water; repeat photos from one angle to reveal tilt or settlement."]},{"title":"If something changes","items":["For erosion or pooling, inspect grade and outlets instead of simply raising the sides."]},{"title":"When to check","items":["Recheck after adding pots, moving, or strong wind; unload a loose structure before repair."]}],"cautions":["Balcony, roof, and hanging loads cannot be judged by appearance; obtain a qualified assessment where capacity is unknown."],"sources":[{"title":"UMN Extension · Living soil, healthy garden","url":"https://extension.umn.edu/garden-and-home/yard-and-garden/gardening-minnesota/living-soil-healthy-garden"}]}'::jsonb),
  ('system', 'preset', '鸡舍', '{"overview":"睡觉、产蛋、饮水与清粪应各有方便维护的位置。","parameters":[],"cycle":null,"sections":[{"title":"开始前与操作","items":["设置稳固栖架和安静产蛋处，饮水器避开睡眠区；检查夜间防天敌门锁。","从动物视角检查门缝、尖角、夹脚处和可啃咬电线；人要能方便清洁和紧急开门。"]},{"title":"日常照护与维护","items":["每日收蛋、移走湿垫料，检查栖架是否松动、舍内是否闷臭。","每天检查门锁、饮水处湿垫料和排泄区；先移开动物再维修或使用清洁剂。"]},{"title":"异常先看这里","items":["氨味明显或脚部总是脏湿时先处理粪便、漏水和通风，不只加香味除臭。"]},{"title":"检查提醒","items":["换季、暴雨和增加动物后重查遮阴、通风、干燥及防逃逸。"]}],"cautions":["空间按成年体型和实际数量设计，不把幼体能住当作长期合适；避免仅靠细网防大型天敌。"],"sources":[]}'::jsonb, '{"overview":"Separate practical roosting, nesting, watering, and manure-cleaning areas.","parameters":[],"cycle":null,"sections":[{"title":"Start here","items":["Install stable roosts and quiet nests, keep drinkers away from sleeping areas, and check predator-resistant night latches.","Check gaps, sharp edges, foot traps, and reachable wires from the animal''s level; keep cleaning and emergency access practical."]},{"title":"Routine care","items":["Collect eggs, remove wet bedding, and inspect loose roosts and stale air daily.","Check latches, wet bedding near drinkers, and waste areas daily; move animals away before repairs or cleaners."]},{"title":"If something changes","items":["For strong ammonia or persistently dirty wet feet, address manure, leaks, and airflow rather than masking odor."]},{"title":"When to check","items":["Review shade, airflow, dryness, and escape protection after seasonal changes, rain, or adding animals."]}],"cautions":["Design for adult size and actual numbers; juvenile fit is not lifetime suitability, and fine mesh alone may not stop larger predators."],"sources":[]}'::jsonb),
  ('other', 'preset', '果酱', '{"overview":"先做一小瓶冷藏草莓酱，掌握溶糖、煮制和冷盘检查；这里不把热装瓶等同于常温罐藏。","parameters":[{"label":"草莓：糖（重量）","value":"1：1；去蒂草莓230g＋白砂糖230g"},{"label":"柠檬汁","value":"5mL（1量茶匙）"},{"label":"首次检查","value":"糖溶解后沸煮约5分钟，再用冷盘检查"}],"cycle":null,"sections":[{"title":"称量与准备","items":["草莓洗净沥干、去蒂后称重，压碎但保留少量果粒；另备干净耐热小瓶、厚底锅和预冷小碟。","按上方用量加入糖和柠檬汁；这是草莓示例，不把同一比例直接当作所有水果的通用配方。"]},{"title":"溶糖与煮制","items":["小火搅拌至看不见糖粒，再转大火煮开；用长柄勺沿锅底搅动，防粘锅和热糖浆飞溅。","沸煮约5分钟后离火取样，尚未凝结则再煮1分钟复测，不靠固定总时长硬熬。"]},{"title":"怎样判断合适","items":["滴少量酱在冷碟上，冷藏约30秒，再用勺边推开；能起轻微皱纹、划开的沟不立即合拢即可。","只检查冷却的少量样品，不用手接触锅内热酱；软凝固并不要求像硬糖一样立住勺子。"]},{"title":"装瓶与取用","items":["装入洁净耐热容器，标日期并按冷藏食品管理；每次用干净勺取，少量制作尽快用完。","要常温保存，另按经验证的完整罐藏配方及海拔处理时间执行；出现霉点、鼓盖，不撇掉后继续吃。"]}],"cautions":["本例借用小批量煮酱方法，保存按冷藏管理；不采用“瓶盖吸住就能放几年”的判断。"],"sources":[{"title":"Camilla Hawkins · Small-batch strawberry jam（配料与凝固检查）","url":"https://www.fabfood4all.co.uk/quick-one-punnet-strawberry-jam/"},{"title":"NCHFP · Tested jam processing（常温保存须另按完整工艺）","url":"https://nchfp.uga.edu/how/make-jam-jelly/jams/berry-jams-without-pectin/"}]}'::jsonb, '{"overview":"Start with a small refrigerated strawberry jam and learn dissolving, boiling and cold-plate checks. Hot filling alone is not a canning process.","parameters":[{"label":"Strawberries : sugar by weight","value":"1:1; 230 g hulled strawberries + 230 g granulated sugar"},{"label":"Lemon juice","value":"5 mL (1 measuring teaspoon)"},{"label":"First setting check","value":"Check on a cold plate after about 5 minutes of boiling"}],"cycle":null,"sections":[{"title":"Weigh and prepare","items":["Wash, drain and hull before weighing; crush with some texture. Prepare a clean heat-safe jar, heavy pan and chilled saucer.","Add the measured sugar and lemon juice. These quantities are for strawberries, not a universal fruit formula."]},{"title":"Dissolve and boil","items":["Stir over low heat until sugar dissolves, then bring to a rolling boil. Use a long spoon to prevent sticking and splashes.","After about five minutes, take the pan off heat and test; if unset, boil another minute and repeat."]},{"title":"Check the set","items":["Chill a drop on the saucer for about 30 seconds; push with a spoon. A slight wrinkle and a groove that stays open indicate set.","Test only the cooled sample, never hot jam in the pan. A soft set need not hold a spoon upright."]},{"title":"Pack and use","items":["Use a clean heat-safe container, date it and refrigerate. Serve with clean utensils and use small batches promptly.","Shelf storage requires a complete tested canning recipe with altitude adjustments. Discard moldy or swollen jars, not just the surface."]}],"cautions":["This worked example uses the small-batch cooking method with refrigerated storage, not a multi-year shelf-life claim based on lid suction."],"sources":[{"title":"Camilla Hawkins · Small-batch strawberry jam（配料与凝固检查）","url":"https://www.fabfood4all.co.uk/quick-one-punnet-strawberry-jam/"},{"title":"NCHFP · Tested jam processing（常温保存须另按完整工艺）","url":"https://nchfp.uga.edu/how/make-jam-jelly/jams/berry-jams-without-pectin/"}]}'::jsonb),
  ('other', 'preset', '果汁', '{"overview":"以现榨橙汁为例，先处理果皮和器具，再切开榨汁。现榨、加柠檬或冷藏都不等于杀菌。","parameters":[{"label":"一次用量","value":"只榨当次需要量；不必加糖或额外兑水"},{"label":"冷藏温度","value":"4℃或以下；用冰箱温度计核对"},{"label":"室温放置上限","value":"不超过2小时；环境高于32℃时不超过1小时"}],"cycle":null,"sections":[{"title":"洗果与清洁","items":["丢弃腐烂果，用流动饮用水清洗橙子表面；即使不吃果皮也要洗，避免切刀把污物带入果肉。","洗手，清洁刀、砧板、榨汁头和接汁杯；不要用处理过生肉但尚未清洗的工具。"]},{"title":"榨取与分装","items":["把橙子对半切开后榨汁，滤掉果核，按口感保留果肉；不把掉在台面上的果肉放回杯中。","用洁净杯直接饮用或立即小份冷藏；旧果汁不倒入新榨的一批。"]},{"title":"保存与清洗","items":["容器写上榨汁时间，不为囤放而一次榨很多；常温超时的果汁不要靠闻起来正常继续喝。","使用后拆开榨汁器，清除滤网和缝隙中的果肉，按设备说明清洗并晾干。"]},{"title":"哪些情况要换做法","items":["儿童、孕妇、老人及免疫力较弱者优先选择经巴氏杀菌或其他有效处理的果汁。","需要瓶装长期存放时改用该果汁的验证加工工艺；不能把简单煮热或加糖当作常温保质方案。"]}],"cautions":["以上清洁与冷藏措施降低风险，但不能保证鲜榨果汁无致病菌。"],"sources":[{"title":"FDA · Juice safety","url":"https://www.fda.gov/food/buy-store-serve-safe-food/what-you-need-know-about-juice-safety"},{"title":"FoodSafety.gov · Refrigeration and time limits","url":"https://www.foodsafety.gov/keep-food-safe/4-steps-to-food-safety"}]}'::jsonb, '{"overview":"For fresh orange juice, clean the fruit exterior and equipment before cutting and pressing. Freshness, lemon or refrigeration is not pasteurization.","parameters":[{"label":"Batch size","value":"Press only the amount needed; sugar and water are unnecessary"},{"label":"Refrigeration","value":"4°C or below, checked with an appliance thermometer"},{"label":"Time out of refrigeration","value":"No more than 2 hours, or 1 hour above 32°C"}],"cycle":null,"sections":[{"title":"Clean first","items":["Discard rotten fruit and rinse the outside under running drinking water, even when discarding the peel.","Wash hands and clean the knife, board, press and cup; avoid unwashed raw-meat utensils."]},{"title":"Press and portion","items":["Halve and press oranges, strain seeds and retain pulp as desired; keep countertop scraps out.","Serve in a clean cup or refrigerate portions immediately; never mix old juice into a fresh batch."]},{"title":"Store and clean up","items":["Label pressing time and avoid oversized batches; a normal smell does not rescue juice left out too long.","Disassemble after use, remove pulp from filters and seams, and wash and dry as directed."]},{"title":"When to use treated juice","items":["Children, pregnant people, older adults and immunocompromised people should choose effectively treated juice.","Bottled long-term storage needs a validated juice-specific process, not casual warming or added sugar."]}],"cautions":["Cleaning and chilling reduce risk but cannot guarantee pathogen-free fresh juice."],"sources":[{"title":"FDA · Juice safety","url":"https://www.fda.gov/food/buy-store-serve-safe-food/what-you-need-know-about-juice-safety"},{"title":"FoodSafety.gov · Refrigeration and time limits","url":"https://www.foodsafety.gov/keep-food-safe/4-steps-to-food-safety"}]}'::jsonb),
  ('system', 'preset', '育苗架', '{"overview":"育苗架要同时解决盆盘重量、均匀光照和滴水。","parameters":[],"cycle":null,"sections":[{"title":"开始前与操作","items":["先放空育苗盘检查取放与灯距，装防倾倒固定；灯具按说明避开浇水路径。","按产品说明核对满载重量、连接件和固定方式；先空载装好，再分次放入湿土或花盆。"]},{"title":"日常照护与维护","items":["观察边缘和中央苗是否徒长；轮换盘位时一并检查积水。","浇水后检查支脚、接缝和地面积水；固定同一角度拍照，便于发现歪斜和下沉。"]},{"title":"异常先看这里","items":["苗总向一侧倒先查光照；架体晃动或插座受潮先停用处理。"]},{"title":"检查提醒","items":["增加花盆、移动位置和大风后重新检查；发现松动先卸载再修复。"]}],"cautions":["阳台、屋顶和悬挂设施的承重不能靠目测确认；不明承重时先让专业人员核实。"],"sources":[]}'::jsonb, '{"overview":"Balance tray load, even light, and water management.","parameters":[],"cycle":null,"sections":[{"title":"Start here","items":["Test empty-tray access and lamp clearance, anchor against tipping, and keep lighting clear of watering paths.","Check the product''s loaded-weight rating, fasteners, and anchoring; assemble empty and add wet soil or pots in stages."]},{"title":"Routine care","items":["Compare edge and center seedlings for stretching and check pooling when rotating trays.","After watering, inspect feet, joints, and standing water; repeat photos from one angle to reveal tilt or settlement."]},{"title":"If something changes","items":["Check light for one-sided leaning; stop using a wobbling rack or damp electrical outlet."]},{"title":"When to check","items":["Recheck after adding pots, moving, or strong wind; unload a loose structure before repair."]}],"cautions":["Balcony, roof, and hanging loads cannot be judged by appearance; obtain a qualified assessment where capacity is unknown."],"sources":[]}'::jsonb),
  ('other', 'preset', '腌渍', '{"overview":"先用卷心菜乳酸发酵作完整示例；它不同于加醋速腌，不能把蔬菜、盐和水的比例任意互换。","parameters":[{"label":"卷心菜与盐","value":"净菜约2.27kg＋腌渍盐3平量汤匙（每匙15mL）"},{"label":"发酵环境","value":"约21–24℃，避直晒"},{"label":"参考时长","value":"约3–4周；较凉的16–18℃可能需5–6周"}],"cycle":null,"sections":[{"title":"称量、切丝、拌盐","items":["去掉坏叶，洗净沥水、去芯切细丝，再称净重；用标准量匙，不用家里的大小饭勺估盐。","按上方用量拌盐，用干净双手揉拌，压实入食品用发酵容器，使菜汁析出。"]},{"title":"压料与补液","items":["用适合食品接触的压重保持菜丝在液面下，容器留出约10–13cm上部空间；盖洁净布或配套排气盖。","汁液不足时，另用约946mL水加1.5平量汤匙腌渍盐，煮沸放凉后补到覆盖；不直接加无盐水稀释。"]},{"title":"每周检查什么","items":["每周检查2–3次温度、液面和异常表面生长，记录日期；不要每天翻拌把空气带进去。","参考时长到了也要核对发酵已完成、持续产气停止及工艺记录，不能只凭尝着酸就结束。"]},{"title":"结束与保存","items":["正常完成后分装冷藏、用洁净工具取食；需常温罐藏时另遵循完整的容器规格与海拔处理流程。","出现霉毛、黏滑、腐败气味或盐量无法确认时停止食用；不要撇掉或再加盐来补救。"]}],"cautions":["本例只适用于卷心菜；腌渍盐的量匙体积不能直接当成克数，也不适用于肉、鱼、豆腐或所有泡菜。"],"sources":[{"title":"NCHFP / USDA · Sauerkraut quantities and fermentation method","url":"https://nchfp.uga.edu/how/ferment/recipes/sauerkraut/"}]}'::jsonb, '{"overview":"Use cabbage fermentation as a worked example. It differs from quick vinegar pickling; vegetable, salt and water proportions are not interchangeable.","parameters":[{"label":"Cabbage and salt","value":"About 2.27 kg cabbage + 3 level 15 mL measuring tablespoons of pickling salt"},{"label":"Fermentation environment","value":"Approximately 21–24°C, away from direct sun"},{"label":"Reference duration","value":"About 3–4 weeks; around 16–18°C may take 5–6 weeks"}],"cycle":null,"sections":[{"title":"Weigh, shred and salt","items":["Trim, wash, drain, core and finely shred before weighing. Use measuring spoons rather than assorted cutlery.","Mix the specified salt through with clean hands, then pack firmly into a food-safe fermenter to draw out juice."]},{"title":"Submerge and cover","items":["Keep shreds submerged with a food-safe weight; leave roughly 10–13 cm headspace and use a clean cloth or appropriate vented cover.","If needed, boil and cool 946 mL water with 1.5 level measuring tablespoons of pickling salt before topping up; do not dilute with plain water."]},{"title":"Check during fermentation","items":["Check temperature, submersion and abnormal surface growth two or three times weekly and log dates; avoid daily stirring.","Verify completion, cessation of continuing fermentation bubbles and process records, not just elapsed time or sour taste."]},{"title":"Finish and store","items":["Refrigerate after normal completion and use clean serving utensils; shelf storage needs the complete jar-size and altitude-specific canning process.","Stop food use for fuzzy mold, slime, putrid odor or uncertain salt quantities; skimming or adding salt cannot validate the batch."]}],"cautions":["This example is for cabbage. Salt spoon-volume is not its weight in grams and the method does not cover meat, fish, tofu or every pickle."],"sources":[{"title":"NCHFP / USDA · Sauerkraut quantities and fermentation method","url":"https://nchfp.uga.edu/how/ferment/recipes/sauerkraut/"}]}'::jsonb),
  ('insect_fish', 'preset', '狐尾藻', '{"overview":"先确认具体狐尾藻，再选择沉水或挺水的管理方式。","parameters":[{"label":"光照","value":"中光"},{"label":"参考水温范围","value":"23–25℃","note":"资料所列范围，并非全程最适温度。"},{"label":"生长方式","value":"茎生／漂浮"},{"label":"难度","value":"容易"}],"cycle":null,"sections":[{"title":"开始前与操作","items":["按来源标签确认物种与生长形态，分茎安置，不让枝叶堵住设备。","保留购买标签或学名；清除运输包装，先把种植位置和入缸状态拍下来。"]},{"title":"日常照护与维护","items":["及时修剪伸出计划范围的枝条，剪屑集中清理而不随排水流走。","每周同角度拍新芽和老叶；修剪后捞净碎叶，记下光照、施肥或换水的单项变化。"]},{"title":"异常先看这里","items":["下部稀疏先查上层遮阴；不将水族种植株移入自然池塘。"]},{"title":"检查提醒","items":["刚定植时先检查是否松脱；修剪、移动灯具或换水后，连续观察新叶而不只看旧叶。"]}],"cautions":["俗名可能对应不同物种；不要凭名称套用统一水温。修剪物不要丢进河道或户外水体。","水温参考品种：Myriophyllum mattogrossense，23–25℃。这是资料所列范围，并非整段都是最适温度；同名水草可能不是同一品种，不要据此骤升骤降水温。"],"sources":[{"title":"Tropica · Planting in the aquarium","url":"https://tropica.com/en/guide/get-the-right-start/planting/"},{"title":"Dennerle — Myriophyllum mattogrossense","url":"https://dennerleplants.co.uk/products/myriophyllum-mattogrossense"}]}'::jsonb, '{"overview":"Identify the particular water-milfoil before choosing submerged or emergent care.","parameters":[{"label":"Light","value":"Medium light"},{"label":"Reference water-temperature range","value":"23–25°C","note":"Published range, not an optimum throughout."},{"label":"Growth form","value":"Stem / floating"},{"label":"Difficulty","value":"Easy"}],"cycle":null,"sections":[{"title":"Start here","items":["Use the source label to confirm species and growth form; keep separated stems clear of equipment.","Keep the label or scientific name, remove transport packaging, and photograph the planting position and arrival condition."]},{"title":"Routine care","items":["Trim growth beyond the intended area and collect cuttings instead of flushing them away.","Photograph new and old leaves weekly; remove pruning debris and log individual changes in light, nutrients, or water."]},{"title":"If something changes","items":["For sparse bases, check upper shading; do not transfer aquarium plants to natural ponds."]},{"title":"When to check","items":["Check for loose plants after planting; following pruning, light changes, or water changes, track new growth as well as old leaves."]}],"cautions":["Trade names can cover different species; do not assume one temperature from a name. Keep trimmings out of natural waterways.","Temperature reference: Myriophyllum mattogrossense, 23–25°C. This is a published range, not an ideal setpoint or permission for sudden temperature changes; other species sold under this common name may differ."],"sources":[{"title":"Tropica · Planting in the aquarium","url":"https://tropica.com/en/guide/get-the-right-start/planting/"},{"title":"Dennerle — Myriophyllum mattogrossense","url":"https://dennerleplants.co.uk/products/myriophyllum-mattogrossense"}]}'::jsonb),
  ('insect_fish', 'preset', '孔雀鱼', '{"overview":"在稳定水体中管理群体与繁殖数量，避免越养越挤。","parameters":[],"cycle":null,"sections":[{"title":"开始前与操作","items":["入缸前确定现有数量和后续安置，确认雄雌组合及同伴兼容性。","入鱼前用检测确认过滤系统能处理氨和亚硝酸盐，不以水清或开机天数代替检测。"]},{"title":"日常照护与维护","items":["观察追逐和弱鱼是否能吃到，统计幼鱼出现后重新评估负荷。","每天先观察呼吸、游姿和摄食再投喂；记下剩饵和换水量，换水时匹配新水条件。"]},{"title":"异常先看这里","items":["鱼鳍受损或持续躲角落时先排查追咬、拥挤与水质。"]},{"title":"检查提醒","items":["新入鱼、过滤维护或停电后增加水质检查；离家前确认有人能查看设备和动物。"]}],"cautions":["异常先查水质和设备；持续呼吸困难、损伤或不进食应联系水生动物兽医，不混用药物试错。"],"sources":[{"title":"OATA · Freshwater aquarium care","url":"https://ornamentalfish.org/what-we-do/advice-information/care-sheets/caresheets-tropical-freshwater-fish/how-to-set-up-and-look-after-a-freshwater-tank-aquarium/"}]}'::jsonb, '{"overview":"Manage population and breeding in a stable aquarium to avoid crowding.","parameters":[],"cycle":null,"sections":[{"title":"Start here","items":["Plan stocking and future homes and check sex mix and companion compatibility.","Before stocking, use tests to confirm the filter handles ammonia and nitrite; clear water or elapsed days are not proof."]},{"title":"Routine care","items":["Watch chasing and feeding access; review system load when fry appear.","Observe breathing, swimming, and appetite before feeding; log leftovers and water changes and match replacement-water conditions."]},{"title":"If something changes","items":["For damaged fins or persistent hiding, inspect aggression, crowding, and water."]},{"title":"When to check","items":["Increase water checks after additions, filter work, or power loss; arrange equipment and animal checks before travel."]}],"cautions":["Check water and equipment first; persistent breathing difficulty, injury, or refusal to feed needs aquatic-veterinary advice, not mixed treatments."],"sources":[{"title":"OATA · Freshwater aquarium care","url":"https://ornamentalfish.org/what-we-do/advice-information/care-sheets/caresheets-tropical-freshwater-fish/how-to-set-up-and-look-after-a-freshwater-tank-aquarium/"}]}'::jsonb),
  ('insect_fish', 'preset', '鹭', '{"overview":"池塘周边观察涉水捕食，注意人与鸟都能安全离开。","parameters":[],"cycle":null,"sections":[{"title":"开始前与操作","items":["在岸上固定点观察，不涉水追近，不用鱼饵把鸟引到危险处。","在原处选固定观察点，不抓捕、不搬巢，也不为了照片驱赶动物。"]},{"title":"日常照护与维护","items":["记录水位、捕食和停留，鱼池防护避免使用会缠脚缠翅的松网。","记录时间、天气、数量与行为；保持观察距离，减少夜灯、噪声和宠物追逐。"]},{"title":"异常先看这里","items":["发现缠线或受伤个体先保持距离联系救助，长喙动物不要徒手抓。"]},{"title":"检查提醒","items":["繁殖或育幼期减少靠近；受伤个体先联系当地野生动物救助机构。"]}],"cautions":["不要把暂时停留或幼鸟离巢当作被遗弃；不强行喂水、喂奶或饲喂人类饭菜。"],"sources":[{"title":"RHS · Wildlife in gardens","url":"https://www.rhs.org.uk/wildlife/in-gardens"},{"title":"Cornell Lab · Window collisions and injured birds","url":"https://www.allaboutbirds.org/news/why-birds-hit-windows-and-how-you-can-help-prevent-it/"}]}'::jsonb, '{"overview":"Observe wading and feeding while leaving safe retreat routes for people and birds.","parameters":[],"cycle":null,"sections":[{"title":"Start here","items":["Stay at a shore observation point and do not chase into water or bait dangerous locations.","Choose a fixed observation point in place; do not capture, move nests, or drive animals for a photo."]},{"title":"Routine care","items":["Log water level and visits; pond protection must not entangle feet or wings.","Log time, weather, number, and behavior; keep distance and reduce night lighting, noise, and pet chasing."]},{"title":"If something changes","items":["For line entanglement or injury, keep distance and contact help; do not grab a long-billed bird."]},{"title":"When to check","items":["Increase distance during nesting or rearing; contact a local wildlife rehabilitator for injured animals."]}],"cautions":["Resting or fledging is not automatically abandonment; do not force water, milk, or human meals."],"sources":[{"title":"RHS · Wildlife in gardens","url":"https://www.rhs.org.uk/wildlife/in-gardens"},{"title":"Cornell Lab · Window collisions and injured birds","url":"https://www.allaboutbirds.org/news/why-birds-hit-windows-and-how-you-can-help-prevent-it/"}]}'::jsonb),
  ('system', 'preset', '防虫网棚', '{"overview":"网棚靠完整封闭防虫，同时要兼顾通风和授粉。","parameters":[],"cycle":null,"sections":[{"title":"开始前与操作","items":["按要防的害虫选网，入棚苗先检查叶背；封好地面、门边和管线缝。","在植物高度放温湿度计，记录晴天午后和夜间读数；留出可操作的通风口。"]},{"title":"日常照护与维护","items":["每次出入关门，巡查破洞和网内害虫，开花时核对作物授粉需求。","把开关棚、通风、遮阳的时间与读数一起记下，先试小范围调整。"]},{"title":"异常先看这里","items":["网内仍有虫时查带入苗和破口，不以更细网直接解决所有问题。"]},{"title":"检查提醒","items":["晴天升温前查通风；寒潮、大风前核对固定件和覆盖层，天气过后复查。"]}],"cautions":["密闭保温可能同时积热、积湿；用电加温遵守设备的防水、间距及防火要求。"],"sources":[{"title":"RHS · Greenhouse ventilation and shading","url":"https://www.rhs.org.uk/garden-features/ventilation-and-shading-greenhouses"}]}'::jsonb, '{"overview":"Exclusion needs intact coverage while allowing airflow and pollination.","parameters":[],"cycle":null,"sections":[{"title":"Start here","items":["Choose mesh for the target pest, inspect incoming plants, and seal ground, door, and pipe gaps.","Place a thermometer/hygrometer at plant height; record sunny-afternoon and nighttime readings and keep vents accessible."]},{"title":"Routine care","items":["Close after entry, check tears and insects inside, and review pollination at flowering.","Log venting, covering, and shading alongside readings; try changes on a small area first."]},{"title":"If something changes","items":["If insects remain, inspect incoming stock and gaps rather than assuming finer mesh fixes everything."]},{"title":"When to check","items":["Check ventilation before sunny-day heating; inspect fixings and covers before and after cold or windy weather."]}],"cautions":["A closed cover can trap heat and moisture; electric heating must follow equipment requirements for water protection, clearance, and fire safety."],"sources":[{"title":"RHS · Greenhouse ventilation and shading","url":"https://www.rhs.org.uk/garden-features/ventilation-and-shading-greenhouses"}]}'::jsonb),
  ('insect_fish', 'preset', '鹦鹉', '{"overview":"以合适食物、可活动空间和每日互动为主，不只靠一碗种子和笼子。","parameters":[],"cycle":null,"sections":[{"title":"开始前与操作","items":["核对品种食谱，准备安全栖架、可啃咬玩具和防逃活动区域。","确认品种、成年体型和原来的食物；安排安静观察区及可安全活动的空间。"]},{"title":"日常照护与维护","items":["轮换安全玩具，记录实际采食与体重，不突然撤走熟悉食物逼换粮。","每天清洗饮水器，查看食量、粪便和站姿；清洁时检查栖架、门扣和可误食小件。"]},{"title":"异常先看这里","items":["啄羽、持续尖叫或食欲下降时先排查环境与健康，再寻求鸟类兽医或行为指导。"]},{"title":"检查提醒","items":["换食物逐步进行并称量摄食；持续蓬羽、呼吸困难或突然不进食应尽快联系鸟类兽医。"]}],"cautions":["不要靠抓握或限制饮食纠正行为；避免厨房烟气、开放窗户和宠物接触风险。"],"sources":[{"title":"RSPCA · Caring for exotic pets","url":"https://www.rspca.org.uk/adviceandwelfare/pets/other"}]}'::jsonb, '{"overview":"Provide suitable diet, activity, and daily interaction, not just seeds and a cage.","parameters":[],"cycle":null,"sections":[{"title":"Start here","items":["Confirm the species diet and prepare safe perches, chew items, and escape-proof activity space.","Confirm species, adult size, and previous diet; prepare a quiet observation area and safe activity space."]},{"title":"Routine care","items":["Rotate safe enrichment and track intake/weight; do not force diet changes by abruptly removing familiar food.","Clean drinkers and check intake, droppings, and posture daily; inspect perches, latches, and swallowable parts."]},{"title":"If something changes","items":["For feather damage, persistent screaming, or reduced appetite, review health/environment and seek avian or behavioral advice."]},{"title":"When to check","items":["Change diet gradually while measuring intake; persistent fluffed posture, breathing difficulty, or sudden appetite loss needs prompt avian-vet advice."]}],"cautions":["Do not use force or food deprivation to correct behavior; avoid kitchen fumes, open-window escapes, and unsafe pet contact."],"sources":[{"title":"RSPCA · Caring for exotic pets","url":"https://www.rspca.org.uk/adviceandwelfare/pets/other"}]}'::jsonb),
  ('system', 'preset', '沤肥', '{"overview":"沤制与好氧堆肥不同。这里仅提供聚合草植物浸液的小批量例子，不套用于粪污、饼肥或混合厨余。","parameters":[{"label":"本例原料","value":"已确认身份的聚合草叶＋水"},{"label":"本例稀释","value":"原液∶水约1∶10，不通用于其他沤肥"}],"cycle":null,"sections":[{"title":"植物浸液示例","items":["戴手套剪取聚合草叶，放进专用桶，加水浸没并压住浮叶；标明原料、加水量和日期，放在儿童和宠物碰不到的位置。","RHS示例约浸3周后使用；稀释后先少量浇试验区土壤并尽快用完。这个时间不是所有原料的腐熟标准。"]},{"title":"观察与边界","items":["浸液会有明显气味；颜色、气味或不再冒泡都不能证明无病原。若异味影响邻居，停止该方法，改用合适的好氧堆肥。","防雨、防虫但不密封加压；不用于生食叶菜，用后洗手；不倒入雨水口或鱼池，剩余液体按当地废弃物要求处理。"]}],"cautions":["不制作家庭粪污沤肥，不进入沤肥池；浸液不能饮用，也不能凭固定倍数保证对所有植物安全。"],"sources":[{"title":"RHS · Comfrey liquid feed","url":"https://www.rhs.org.uk/advice/grow-your-own/features/making-comfrey-feed"},{"title":"Garden Organic · Comfrey use and hygiene","url":"https://www.gardenorganic.org.uk/expert-advice/all-about-comfrey/comfrey"}]}'::jsonb, '{"overview":"Wet decomposition differs from aerobic composting. This small-batch comfrey-feed example does not apply to manure, oilseed meal, or mixed kitchen waste.","parameters":[{"label":"This example","value":"Correctly identified comfrey leaves and water"},{"label":"Example dilution","value":"About 1 part liquid to 10 parts water; not a general recipe"}],"cycle":null,"sections":[{"title":"Plant-feed example","items":["Wear gloves to cut comfrey leaves. Submerge them in a dedicated bucket and weigh them down. Label ingredients, water volume, and date; keep away from children and pets.","The RHS example steeps for about three weeks. Dilute, trial on soil, and use promptly. This timing does not establish maturity for other ingredients."]},{"title":"Checks and limits","items":["Expect odor. Color, smell, or a lack of bubbles does not prove pathogen safety. If odor affects neighbors, stop and choose a suitable aerobic method.","Exclude rain and insects without sealing a pressurized vessel. Keep off salad crops and wash hands after use. Do not discharge into drains or ponds; follow local waste guidance."]}],"cautions":["Do not make manure slurry at home or enter slurry pits. Never drink the liquid; one dilution cannot guarantee safety for every plant."],"sources":[{"title":"RHS · Comfrey liquid feed","url":"https://www.rhs.org.uk/advice/grow-your-own/features/making-comfrey-feed"},{"title":"Garden Organic · Comfrey use and hygiene","url":"https://www.gardenorganic.org.uk/expert-advice/all-about-comfrey/comfrey"}]}'::jsonb),
  ('system', 'preset', '鱼缸鱼池', '{"overview":"先完成承重、防跌入、漏水与循环测试，再考虑放入生物。","parameters":[],"cycle":null,"sections":[{"title":"开始前与操作","items":["空缸池检查接缝后分次加水，标记水位；测试溢流及停泵时回流水位。","画出水源、阀门、过滤、出水和溢流的简图，标出能关闭和清洗的位置。"]},{"title":"日常照护与维护","items":["留出清洁过滤和捞取杂物的通道；记录设备状态与异常水位。","先用清水试运行，沿途查看漏水、堵塞和回流；记下正常水位或流量作为对照。"]},{"title":"异常先看这里","items":["漏水、电器受潮或停泵回流接近溢出时先停用相应设备并处理。"]},{"title":"检查提醒","items":["启用、清洗和长时间停用后都试运行；大雨、冰冻、停电后检查溢流和连接。"]}],"cautions":["储水不是饮用水处理；水电作业先断电，水箱和池面需防儿童及动物跌入。"],"sources":[{"title":"RHS · Collecting and storing water","url":"https://www.rhs.org.uk/garden-jobs/water-collecting-storing-and-using"},{"title":"OATA · Freshwater aquarium care","url":"https://ornamentalfish.org/what-we-do/advice-information/care-sheets/caresheets-tropical-freshwater-fish/how-to-set-up-and-look-after-a-freshwater-tank-aquarium/"}]}'::jsonb, '{"overview":"Test support, fall protection, leaks, and circulation before adding animals.","parameters":[],"cycle":null,"sections":[{"title":"Start here","items":["Inspect joints, fill in stages, mark the level, and test overflow and pump-stop backflow.","Sketch the supply, valves, filters, outlets, and overflow; mark accessible shutoffs and cleaning points."]},{"title":"Routine care","items":["Keep filter-cleaning and debris-removal access and log equipment and unusual levels.","Test with clean water, check leaks, blockages, and backflow, and record normal level or flow for comparison."]},{"title":"If something changes","items":["For leakage, wet electrics, or near-overflow backflow, isolate the affected equipment and resolve the cause."]},{"title":"When to check","items":["Test after commissioning, cleaning, and long shutdowns; check overflow and connections after rain, frost, or power loss."]}],"cautions":["Storage is not drinking-water treatment; isolate power for wet maintenance and protect tanks/ponds from falls by children and animals."],"sources":[{"title":"RHS · Collecting and storing water","url":"https://www.rhs.org.uk/garden-jobs/water-collecting-storing-and-using"},{"title":"OATA · Freshwater aquarium care","url":"https://ornamentalfish.org/what-we-do/advice-information/care-sheets/caresheets-tropical-freshwater-fish/how-to-set-up-and-look-after-a-freshwater-tank-aquarium/"}]}'::jsonb),
  ('system', 'preset', '排水改良', '{"overview":"先确认水从哪里来、能流到哪里；堆加肥土或挖一个没有出口的坑，可能让根区更湿。","parameters":[{"label":"观察时机","value":"降雨中、雨停后、第二天"},{"label":"先查","value":"落水管、堵塞出口、坡向和土层"}],"cycle":null,"sections":[{"title":"查水路","items":["用照片标出进水、低洼与出水位置，记录多久退水；先清理已有可安全触及的排水口，排除漏水或过量灌溉。","土壤仍饱和时避免踩踏与翻挖。若是长期地下水高或无合适出口，考虑适宜高床、抬高种植或耐湿植物。"]},{"title":"实施与复查","items":["新沟槽或排水管要先核对地下管线、建筑基础和排水去向；需要工程处理时交给专业人员，不把水转排到邻居地块。","下一场雨后按原位置复拍，比较退水时间和根系恢复；土仍湿而叶萎蔫时先查根，不立刻补水施肥。"]}],"cautions":["污水或来源不明的洪水淹过食用作物时，另做卫生风险处理；本指引不能证明作物可食。"],"sources":[{"title":"RHS · Waterlogging and flooding","url":"https://www.rhs.org.uk/soil-composts-mulches/waterlogging-flooding"},{"title":"RHS · Gardening on wet soils","url":"https://www.rhs.org.uk/soil-composts-mulches/gardening-on-wet-soils"}]}'::jsonb, '{"overview":"Identify incoming water and a viable outlet first. Adding soil or digging an outlet-free pit can leave roots wetter.","parameters":[{"label":"When to observe","value":"During rain, after rain, and the next day"},{"label":"First checks","value":"Downpipes, blocked outlets, grade, soil layers"}],"cycle":null,"sections":[{"title":"Trace the water","items":["Photograph incoming water, low spots, and outlets; log drainage time. Clear safely accessible existing outlets and check leaks or excess irrigation.","Avoid traffic or digging while saturated. For persistently high groundwater or no suitable outlet, consider raised growing areas or wet-tolerant plants."]},{"title":"Implement and review","items":["Before new drains, check utilities, foundations, and a permitted destination. Use professional help for engineering work and do not divert water onto neighboring land.","Rephotograph the same spots after the next rain and compare drainage and root recovery. Wilting in wet soil calls for a root check, not immediate watering or feeding."]}],"cautions":["Assess food-safety risks separately after sewage or unknown floodwater contacts edible crops. This guide does not establish that they are safe to eat."],"sources":[{"title":"RHS · Waterlogging and flooding","url":"https://www.rhs.org.uk/soil-composts-mulches/waterlogging-flooding"},{"title":"RHS · Gardening on wet soils","url":"https://www.rhs.org.uk/soil-composts-mulches/gardening-on-wet-soils"}]}'::jsonb),
  ('insect_fish', 'preset', '鸭', '{"overview":"饮水清洁和休息区干燥要同时做到，不让舍内整天湿滑。","parameters":[],"cycle":null,"sections":[{"title":"开始前与操作","items":["按年龄准备适合鸭的饲料、饮水和防滑地面，幼鸭用水深度需另核对。","按年龄选择完整饲料，设置每只都能到达的饮水和进食位置；新来个体先单独观察。"]},{"title":"日常照护与维护","items":["查看鼻孔、眼部、足底和行动，清走湿料与湿垫料。","每天查水和采食，移走湿垫料；黄昏清点并关好舍门，记录产蛋和异常粪便。"]},{"title":"异常先看这里","items":["跛行、胸腹持续脏湿或饮水异常时先查地面、排水与水器并就医评估。"]},{"title":"检查提醒","items":["高温、换羽、转群和饲料变更时增加巡查；准备离家期间的照护交接。"]}],"cautions":["呼吸困难、多只同时发病或突然死亡应及时联系兽医；不凭网上配方给整群用药。"],"sources":[{"title":"UMN Extension · Raising chickens","url":"https://extension.umn.edu/agriculture/animals-and-livestock/poultry/raising-chickens-for-eggs"}]}'::jsonb, '{"overview":"Keep drinking water clean while retaining dry, non-slip resting space.","parameters":[],"cycle":null,"sections":[{"title":"Start here","items":["Use age-appropriate duck feed/water and flooring; review duckling water depth separately.","Use a complete age-appropriate feed, accessible feeding/watering points, and separate observation for newcomers."]},{"title":"Routine care","items":["Check nostrils, eyes, feet, and movement and remove wet feed/bedding.","Check water and feed daily, remove wet bedding, count and secure birds at dusk, and log eggs and unusual droppings."]},{"title":"If something changes","items":["For lameness, persistently dirty wet plumage, or drinking changes, inspect flooring/drainage and seek veterinary assessment."]},{"title":"When to check","items":["Increase checks during heat, molting, flock moves, and feed changes; arrange care before travel."]}],"cautions":["Breathing difficulty, multiple sick birds, or sudden deaths need veterinary help; do not medicate a flock from an unverified recipe."],"sources":[{"title":"UMN Extension · Raising chickens","url":"https://extension.umn.edu/agriculture/animals-and-livestock/poultry/raising-chickens-for-eggs"}]}'::jsonb),
  ('other', 'preset', '梅子蜜', '{"overview":"用冷冻青梅做冷藏糖浆：先按重量配好梅和糖，再观察糖液析出。这里的“蜜”指糖浆，不是蜂蜜，也不是要发酵成酒。","parameters":[{"label":"梅：糖（重量）","value":"1：1；小批量青梅300g＋冰糖300g"},{"label":"处理与环境","value":"洗净擦干后冷冻一夜；加糖后冷藏"},{"label":"观察起点","value":"约6天起检查，按溶糖和出汁判断"}],"cycle":null,"sections":[{"title":"准备与配比","items":["称青梅300g、冰糖300g；不额外加水，不把冰糖直接换成同重量蜂蜜或大幅减糖。准备食品用冷冻袋或干净容器。","剔除霉烂、破损果，洗净、去果柄并彻底擦干；整果冷冻一夜，不砸碎梅核。"]},{"title":"加糖与每日操作","items":["将冷冻梅与糖装入容器，封好放冰箱冷藏室；用托盘承接可能渗出的汁液。高温天气不搬到阳台晒着催汁。","每天轻轻翻动，使析出的糖液接触所有梅子；手和取用工具保持清洁，不伸手反复抓取。"]},{"title":"完成判断与饮用","items":["冷冻梅的小批量配方约6天起可检查：糖基本溶解、梅子皱缩、糖液析出后取出果实；梅的大小和冰箱温度会改变所需天数。","过滤到洁净容器，继续冷藏；饮用时只取当天需要的量再兑饮用水或苏打水，不把稀释液倒回原瓶。"]},{"title":"保存与异常提醒","items":["标记制作和过滤日期，做小批量尽快用；短期用不完就分装冷冻。冷藏不是无限保质，不自行标注常温一年可放。","出现霉点、黏滑、异常酒味或容器持续鼓气时停止食用，不试喝，不靠撇霉或煮沸把异常批次救回来。"]}],"cautions":["梅糖1：1是这个冷藏糖浆示例的配比，不是所有水果、蜂蜜浸渍或常温罐藏的通用安全比例。"],"sources":[{"title":"Nichirei Foods · 冷冻梅冷藏糖浆（300g梅＋300g冰糖）","url":"https://www.nichireifoods.co.jp/media/8769/"}]}'::jsonb, '{"overview":"Make a refrigerated syrup from frozen ume: weigh fruit and sugar, then monitor extraction. This is sugar syrup, not honey or an alcoholic fermentation.","parameters":[{"label":"Ume : sugar by weight","value":"1:1; a small batch uses 300 g ume + 300 g rock sugar"},{"label":"Preparation and storage","value":"Wash, dry and freeze overnight; refrigerate after adding sugar"},{"label":"When to check","value":"Begin checking around day 6; judge sugar dissolution and extraction"}],"cycle":null,"sections":[{"title":"Prepare and weigh","items":["Weigh 300 g ume and 300 g rock sugar. Add no water; do not swap in honey or substantially reduce sugar. Use a food-safe freezer bag or clean container.","Discard moldy or damaged fruit, wash, remove stalks and dry thoroughly. Freeze whole overnight without cracking the stones."]},{"title":"Add sugar and check daily","items":["Combine frozen fruit and sugar, close and refrigerate on a tray that can catch leaks. Do not accelerate extraction in sun or summer heat.","Gently turn the container daily so extracted syrup wets the fruit. Keep hands and utensils clean rather than repeatedly handling the fruit."]},{"title":"Finish and serve","items":["For this small frozen-fruit batch, inspect from about day 6: remove fruit after sugar mostly dissolves and the fruit shrivels. Fruit size and refrigerator temperature affect timing.","Strain into a clean container and keep refrigerated. Dilute only the day''s serving with drinking or soda water; never return diluted syrup to the original batch."]},{"title":"Storage and warning signs","items":["Label preparation and straining dates, make small batches and use promptly; freeze portions that will not be used soon. Refrigeration does not establish an indefinite shelf life.","Stop using a batch with mold, slime, unexpected alcoholic odor or persistent gas pressure. Do not taste it or try to rescue it by skimming mold or boiling."]}],"cautions":["The 1:1 ratio belongs to this refrigerated syrup example, not every fruit, honey infusion or shelf-stable canning method."],"sources":[{"title":"Nichirei Foods · 冷冻梅冷藏糖浆（300g梅＋300g冰糖）","url":"https://www.nichireifoods.co.jp/media/8769/"}]}'::jsonb),
  ('insect_fish', 'preset', '蜜蜂', '{"overview":"庭院首先提供连续花源与低干扰环境；蜂群管理需要专门经验。","parameters":[],"cycle":null,"sections":[{"title":"开始前与操作","items":["从远处确认蜜蜂还是其他蜂类，避开巢口和飞行通道。","拍下成体或幼体特征、发现植物和日期，先确认对象及生活阶段。"]},{"title":"日常照护与维护","items":["记录访花时间、植物与数量，开花期避免在访花植物上喷杀虫剂。","用短时观察代替频繁翻动，记录取食、蜕变和所处植物；及时清除饲养容器中的腐败物。"]},{"title":"异常先看这里","items":["发现蜂群聚集或筑巢影响通行，隔离人宠并联系有经验人员，不自行封巢或点火。"]},{"title":"检查提醒","items":["蜕皮、化蛹或羽化前后减少触碰；变化当天拍照记录，而非按固定天数催促。"]}],"cautions":["不能可靠识别、有毒或有蜇伤风险的种类以远距离观察为主；不跨地区释放饲养个体。"],"sources":[{"title":"RHS · Wildlife in gardens","url":"https://www.rhs.org.uk/wildlife/in-gardens"}]}'::jsonb, '{"overview":"Support flowers and low disturbance; colony management requires trained experience.","parameters":[],"cycle":null,"sections":[{"title":"Start here","items":["Identify bees from a distance and stay out of nest entrances and flight paths.","Photograph identifying features, host plant, and date; establish the organism and life stage first."]},{"title":"Routine care","items":["Log flower visits, plants, and numbers and avoid insecticides on visited blooms.","Use brief observation instead of repeated disturbance; log feeding, molts, and host plants and remove decaying material from kept enclosures."]},{"title":"If something changes","items":["For swarms/nests obstructing access, keep people and pets clear and contact experienced help; do not seal or burn nests."]},{"title":"When to check","items":["Minimize handling around molts, pupation, and emergence; record the actual change rather than forcing a calendar."]}],"cautions":["Observe unidentified, venomous, or stinging organisms from a distance; do not release captive individuals in other regions."],"sources":[{"title":"RHS · Wildlife in gardens","url":"https://www.rhs.org.uk/wildlife/in-gardens"}]}'::jsonb),
  ('system', 'preset', '围栏', '{"overview":"按要留住的动物和要挡住的天敌分别查薄弱点。","parameters":[],"cycle":null,"sections":[{"title":"开始前与操作","items":["沿地面、转角、门扣和搭接处逐段检查，排除能卡头或夹脚的孔隙。","从动物视角检查门缝、尖角、夹脚处和可啃咬电线；人要能方便清洁和紧急开门。"]},{"title":"日常照护与维护","items":["巡查掘洞、翘边和松动立柱；草木遮住下沿时及时整理检查。","每天检查门锁、饮水处湿垫料和排泄区；先移开动物再维修或使用清洁剂。"]},{"title":"异常先看这里","items":["发现动物尝试钻逃先隔离该段并修复，不能只把它赶回去。"]},{"title":"检查提醒","items":["换季、暴雨和增加动物后重查遮阴、通风、干燥及防逃逸。"]}],"cautions":["空间按成年体型和实际数量设计，不把幼体能住当作长期合适；避免仅靠细网防大型天敌。"],"sources":[]}'::jsonb, '{"overview":"Inspect separately for escape by residents and entry by predators.","parameters":[],"cycle":null,"sections":[{"title":"Start here","items":["Check ground edges, corners, latches, and joins for head or foot traps.","Check gaps, sharp edges, foot traps, and reachable wires from the animal''s level; keep cleaning and emergency access practical."]},{"title":"Routine care","items":["Look for digging, lifted edges, and loose posts; clear vegetation obscuring the base.","Check latches, wet bedding near drinkers, and waste areas daily; move animals away before repairs or cleaners."]},{"title":"If something changes","items":["If an animal attempts escape, isolate and repair that section rather than merely chasing it back."]},{"title":"When to check","items":["Review shade, airflow, dryness, and escape protection after seasonal changes, rain, or adding animals."]}],"cautions":["Design for adult size and actual numbers; juvenile fit is not lifetime suitability, and fine mesh alone may not stop larger predators."],"sources":[]}'::jsonb),
  ('insect_fish', 'preset', '鹌鹑', '{"overview":"地面清洁、躲藏和防惊跳比高栖架更适合作为照护重点。","parameters":[],"cycle":null,"sections":[{"title":"开始前与操作","items":["核对种类与年龄需求，提供防滑地面、隐蔽处和不易受惊撞伤的空间。","按年龄选择完整饲料，设置每只都能到达的饮水和进食位置；新来个体先单独观察。"]},{"title":"日常照护与维护","items":["查看足底、羽毛和取食，安静收蛋并清除潮湿垫料。","每天查水和采食，移走湿垫料；黄昏清点并关好舍门，记录产蛋和异常粪便。"]},{"title":"异常先看这里","items":["头顶撞伤、啄伤或持续躲藏时先减少惊扰、检查空间并隔离受伤个体就医。"]},{"title":"检查提醒","items":["高温、换羽、转群和饲料变更时增加巡查；准备离家期间的照护交接。"]}],"cautions":["呼吸困难、多只同时发病或突然死亡应及时联系兽医；不凭网上配方给整群用药。"],"sources":[{"title":"UMN Extension · Raising chickens","url":"https://extension.umn.edu/agriculture/animals-and-livestock/poultry/raising-chickens-for-eggs"}]}'::jsonb, '{"overview":"Focus on clean ground, cover, and protection from startled jumps rather than high roosts.","parameters":[],"cycle":null,"sections":[{"title":"Start here","items":["Confirm species/age needs and provide non-slip ground, cover, and space that limits collision injury.","Use a complete age-appropriate feed, accessible feeding/watering points, and separate observation for newcomers."]},{"title":"Routine care","items":["Inspect feet, feathers, and feeding, collect eggs quietly, and clear wet bedding.","Check water and feed daily, remove wet bedding, count and secure birds at dusk, and log eggs and unusual droppings."]},{"title":"If something changes","items":["For head collisions, peck injuries, or hiding, reduce disturbance, inspect space, and seek care for injured birds."]},{"title":"When to check","items":["Increase checks during heat, molting, flock moves, and feed changes; arrange care before travel."]}],"cautions":["Breathing difficulty, multiple sick birds, or sudden deaths need veterinary help; do not medicate a flock from an unverified recipe."],"sources":[{"title":"UMN Extension · Raising chickens","url":"https://extension.umn.edu/agriculture/animals-and-livestock/poultry/raising-chickens-for-eggs"}]}'::jsonb),
  ('insect_fish', 'preset', '红绿灯鱼', '{"overview":"以适合的群体、稳定水质和可躲藏植物减轻紧张。","parameters":[],"cycle":null,"sections":[{"title":"开始前与操作","items":["先确认群养与同伴需求，留游动区并用水草提供遮蔽。","入鱼前用检测确认过滤系统能处理氨和亚硝酸盐，不以水清或开机天数代替检测。"]},{"title":"日常照护与维护","items":["观察群体是否正常活动和所有个体是否摄食，不只盯着最活跃的鱼。","每天先观察呼吸、游姿和摄食再投喂；记下剩饵和换水量，换水时匹配新水条件。"]},{"title":"异常先看这里","items":["持续离群、褪色或呼吸急促时测水并查看是否被追逐。"]},{"title":"检查提醒","items":["新入鱼、过滤维护或停电后增加水质检查；离家前确认有人能查看设备和动物。"]}],"cautions":["异常先查水质和设备；持续呼吸困难、损伤或不进食应联系水生动物兽医，不混用药物试错。"],"sources":[{"title":"OATA · Freshwater aquarium care","url":"https://ornamentalfish.org/what-we-do/advice-information/care-sheets/caresheets-tropical-freshwater-fish/how-to-set-up-and-look-after-a-freshwater-tank-aquarium/"}]}'::jsonb, '{"overview":"Support suitable group living, stable water, and planted shelter.","parameters":[],"cycle":null,"sections":[{"title":"Start here","items":["Confirm shoaling and companion needs and combine swimming room with plant cover.","Before stocking, use tests to confirm the filter handles ammonia and nitrite; clear water or elapsed days are not proof."]},{"title":"Routine care","items":["Check activity and feeding across the group, not only the most active fish.","Observe breathing, swimming, and appetite before feeding; log leftovers and water changes and match replacement-water conditions."]},{"title":"If something changes","items":["For persistent isolation, fading, or rapid breathing, test water and inspect harassment."]},{"title":"When to check","items":["Increase water checks after additions, filter work, or power loss; arrange equipment and animal checks before travel."]}],"cautions":["Check water and equipment first; persistent breathing difficulty, injury, or refusal to feed needs aquatic-veterinary advice, not mixed treatments."],"sources":[{"title":"OATA · Freshwater aquarium care","url":"https://ornamentalfish.org/what-we-do/advice-information/care-sheets/caresheets-tropical-freshwater-fish/how-to-set-up-and-look-after-a-freshwater-tank-aquarium/"}]}'::jsonb),
  ('system', 'preset', '鸭舍', '{"overview":"重点把饮水带来的湿区与干燥休息区分开。","parameters":[],"cycle":null,"sections":[{"title":"开始前与操作","items":["饮水点放在可排水、易清洗的位置，通往休息区的地面防滑。","从动物视角检查门缝、尖角、夹脚处和可啃咬电线；人要能方便清洁和紧急开门。"]},{"title":"日常照护与维护","items":["每天清理泼出的水和湿垫料，检查出入口及夜间门锁。","每天检查门锁、饮水处湿垫料和排泄区；先移开动物再维修或使用清洁剂。"]},{"title":"异常先看这里","items":["胸腹羽毛长期脏湿时先查卧处和排水；不要靠频繁冲洗动物代替清舍。"]},{"title":"检查提醒","items":["换季、暴雨和增加动物后重查遮阴、通风、干燥及防逃逸。"]}],"cautions":["空间按成年体型和实际数量设计，不把幼体能住当作长期合适；避免仅靠细网防大型天敌。"],"sources":[]}'::jsonb, '{"overview":"Separate the splash-prone drinking area from dry resting space.","parameters":[],"cycle":null,"sections":[{"title":"Start here","items":["Place drinkers where drainage and cleaning are easy and keep the route to shelter non-slip.","Check gaps, sharp edges, foot traps, and reachable wires from the animal''s level; keep cleaning and emergency access practical."]},{"title":"Routine care","items":["Clear spills and wet bedding daily and check entrances and night latches.","Check latches, wet bedding near drinkers, and waste areas daily; move animals away before repairs or cleaners."]},{"title":"If something changes","items":["For persistently dirty wet breast/belly feathers, inspect bedding and drainage rather than repeatedly washing birds."]},{"title":"When to check","items":["Review shade, airflow, dryness, and escape protection after seasonal changes, rain, or adding animals."]}],"cautions":["Design for adult size and actual numbers; juvenile fit is not lifetime suitability, and fine mesh alone may not stop larger predators."],"sources":[]}'::jsonb),
  ('system', 'preset', '花架', '{"overview":"按浇水后的花盆重量安排层位，重盆尽量放低。","parameters":[],"cycle":null,"sections":[{"title":"开始前与操作","items":["把最重花盆的湿重与架体额定值核对，留好接水和擦拭空间。","按产品说明核对满载重量、连接件和固定方式；先空载装好，再分次放入湿土或花盆。"]},{"title":"日常照护与维护","items":["取放花盆时检查脚垫和固定点，不拖拉带盆高架。","浇水后检查支脚、接缝和地面积水；固定同一角度拍照，便于发现歪斜和下沉。"]},{"title":"异常先看这里","items":["出现锈蚀、裂纹或连接孔扩大时先卸盆，再判断维修或更换。"]},{"title":"检查提醒","items":["增加花盆、移动位置和大风后重新检查；发现松动先卸载再修复。"]}],"cautions":["阳台、屋顶和悬挂设施的承重不能靠目测确认；不明承重时先让专业人员核实。"],"sources":[]}'::jsonb, '{"overview":"Arrange shelves for wet-pot weight, keeping heavier pots low.","parameters":[],"cycle":null,"sections":[{"title":"Start here","items":["Compare the heaviest wet pot with the stand rating and leave drainage and cleaning access.","Check the product''s loaded-weight rating, fasteners, and anchoring; assemble empty and add wet soil or pots in stages."]},{"title":"Routine care","items":["Check feet and fixings during pot changes; do not drag a tall loaded stand.","After watering, inspect feet, joints, and standing water; repeat photos from one angle to reveal tilt or settlement."]},{"title":"If something changes","items":["Unload pots before assessing rust, cracks, or enlarged fixing holes."]},{"title":"When to check","items":["Recheck after adding pots, moving, or strong wind; unload a loose structure before repair."]}],"cautions":["Balcony, roof, and hanging loads cannot be judged by appearance; obtain a qualified assessment where capacity is unknown."],"sources":[]}'::jsonb),
  ('system', 'preset', '滴灌', '{"overview":"先验证每个滴头实际出水，再设定浇水时间。","parameters":[],"cycle":null,"sections":[{"title":"开始前与操作","items":["装好过滤器并冲洗管路，在首尾滴头下放相同容器，同时间接水比较。","画出水源、阀门、过滤、出水和溢流的简图，标出能关闭和清洗的位置。"]},{"title":"日常照护与维护","items":["检查最远端与高处是否缺水，用土壤实际湿润深度调整时长。","先用清水试运行，沿途查看漏水、堵塞和回流；记下正常水位或流量作为对照。"]},{"title":"异常先看这里","items":["末端少水先查折管、过滤器和压力；局部堵头单独清理，不先延长全区浇水。"]},{"title":"检查提醒","items":["启用、清洗和长时间停用后都试运行；大雨、冰冻、停电后检查溢流和连接。"]}],"cautions":["储水不是饮用水处理；水电作业先断电，水箱和池面需防儿童及动物跌入。"],"sources":[{"title":"RHS · Collecting and storing water","url":"https://www.rhs.org.uk/garden-jobs/water-collecting-storing-and-using"}]}'::jsonb, '{"overview":"Check actual emitter output before setting watering duration.","parameters":[],"cycle":null,"sections":[{"title":"Start here","items":["Fit filtration, flush lines, and compare equal-time collection at the first and last emitters.","Sketch the supply, valves, filters, outlets, and overflow; mark accessible shutoffs and cleaning points."]},{"title":"Routine care","items":["Check distant/high points and adjust duration to the soil''s actual wetting depth.","Test with clean water, check leaks, blockages, and backflow, and record normal level or flow for comparison."]},{"title":"If something changes","items":["For weak tail-end output, inspect kinks, filters, and pressure; clean local clogs instead of lengthening every zone."]},{"title":"When to check","items":["Test after commissioning, cleaning, and long shutdowns; check overflow and connections after rain, frost, or power loss."]}],"cautions":["Storage is not drinking-water treatment; isolate power for wet maintenance and protect tanks/ponds from falls by children and animals."],"sources":[{"title":"RHS · Collecting and storing water","url":"https://www.rhs.org.uk/garden-jobs/water-collecting-storing-and-using"}]}'::jsonb),
  ('insect_fish', 'preset', '蜘蛛', '{"overview":"多数庭院蜘蛛适合原处观察网、躲藏和捕食，不需要搬入盒中。","parameters":[],"cycle":null,"sections":[{"title":"开始前与操作","items":["拍下体形、网形和栖息点，在可靠辨种前不徒手触碰。","拍下成体或幼体特征、发现植物和日期，先确认对象及生活阶段。"]},{"title":"日常照护与维护","items":["避开网和卵囊，记录网的位置与捕食，清扫前先看是否能留一个安静角落。","用短时观察代替频繁翻动，记录取食、蜕变和所处植物；及时清除饲养容器中的腐败物。"]},{"title":"异常先看这里","items":["进入室内且无法辨认时隔离人宠，请有经验者处理，别冒险手抓。"]},{"title":"检查提醒","items":["蜕皮、化蛹或羽化前后减少触碰；变化当天拍照记录，而非按固定天数催促。"]}],"cautions":["不能可靠识别、有毒或有蜇伤风险的种类以远距离观察为主；不跨地区释放饲养个体。"],"sources":[{"title":"RHS · Wildlife in gardens","url":"https://www.rhs.org.uk/wildlife/in-gardens"}]}'::jsonb, '{"overview":"Observe garden spiders'' webs and hunting in place rather than boxing them.","parameters":[],"cycle":null,"sections":[{"title":"Start here","items":["Photograph body, web, and site and do not handle before reliable identification.","Photograph identifying features, host plant, and date; establish the organism and life stage first."]},{"title":"Routine care","items":["Avoid webs and egg sacs and consider retaining a quiet corner before cleaning.","Use brief observation instead of repeated disturbance; log feeding, molts, and host plants and remove decaying material from kept enclosures."]},{"title":"If something changes","items":["For unidentified indoor spiders, keep people/pets clear and seek experienced help instead of grabbing."]},{"title":"When to check","items":["Minimize handling around molts, pupation, and emergence; record the actual change rather than forcing a calendar."]}],"cautions":["Observe unidentified, venomous, or stinging organisms from a distance; do not release captive individuals in other regions."],"sources":[{"title":"RHS · Wildlife in gardens","url":"https://www.rhs.org.uk/wildlife/in-gardens"}]}'::jsonb),
  ('system', 'preset', '兔舍', '{"overview":"提供干燥、不伤脚的休息面和可躲藏活动的空间。","parameters":[],"cycle":null,"sections":[{"title":"开始前与操作","items":["检查底面、门缝与可咬到的电线；备干草区、清水和安静躲藏处。","从动物视角检查门缝、尖角、夹脚处和可啃咬电线；人要能方便清洁和紧急开门。"]},{"title":"日常照护与维护","items":["每天清理厕所和湿垫料，检查足底接触面是否粗糙或潮湿。","每天检查门锁、饮水处湿垫料和排泄区；先移开动物再维修或使用清洁剂。"]},{"title":"异常先看这里","items":["兔子总趴湿处、喘气或不吃时立即查温度与状态，异常及时联系兽医。"]},{"title":"检查提醒","items":["换季、暴雨和增加动物后重查遮阴、通风、干燥及防逃逸。"]}],"cautions":["空间按成年体型和实际数量设计，不把幼体能住当作长期合适；避免仅靠细网防大型天敌。"],"sources":[]}'::jsonb, '{"overview":"Provide dry, foot-friendly resting surfaces plus hiding and activity space.","parameters":[],"cycle":null,"sections":[{"title":"Start here","items":["Check flooring, door gaps, and reachable wires; prepare hay, water, and a quiet hide.","Check gaps, sharp edges, foot traps, and reachable wires from the animal''s level; keep cleaning and emergency access practical."]},{"title":"Routine care","items":["Clean litter and wet bedding daily and inspect surfaces for roughness and dampness.","Check latches, wet bedding near drinkers, and waste areas daily; move animals away before repairs or cleaners."]},{"title":"If something changes","items":["Lying in wet areas, panting, or not eating needs immediate condition/temperature checks and veterinary advice if abnormal."]},{"title":"When to check","items":["Review shade, airflow, dryness, and escape protection after seasonal changes, rain, or adding animals."]}],"cautions":["Design for adult size and actual numbers; juvenile fit is not lifetime suitability, and fine mesh alone may not stop larger predators."],"sources":[]}'::jsonb),
  ('system', 'preset', '温室', '{"overview":"保温之外，更要防晴天积热和持续结露。","parameters":[],"cycle":null,"sections":[{"title":"开始前与操作","items":["确认门、侧窗和顶窗能开启，温度计避开直晒，并记录棚内冷热位置。","在植物高度放温湿度计，记录晴天午后和夜间读数；留出可操作的通风口。"]},{"title":"日常照护与维护","items":["晴天提早通风，结合植物萎蔫和实测温度调整遮阳；傍晚查看结露。","把开关棚、通风、遮阳的时间与读数一起记下，先试小范围调整。"]},{"title":"异常先看这里","items":["土仍湿却萎蔫先看棚温和根部，不立刻追加大量水。"]},{"title":"检查提醒","items":["晴天升温前查通风；寒潮、大风前核对固定件和覆盖层，天气过后复查。"]}],"cautions":["密闭保温可能同时积热、积湿；用电加温遵守设备的防水、间距及防火要求。"],"sources":[{"title":"RHS · Greenhouse ventilation and shading","url":"https://www.rhs.org.uk/garden-features/ventilation-and-shading-greenhouses"}]}'::jsonb, '{"overview":"Prevent sunny-day overheating and persistent condensation as well as retaining heat.","parameters":[],"cycle":null,"sections":[{"title":"Start here","items":["Check doors and vents open, shade the sensor from direct sun, and map hot/cool spots.","Place a thermometer/hygrometer at plant height; record sunny-afternoon and nighttime readings and keep vents accessible."]},{"title":"Routine care","items":["Vent early on sunny days and adjust shade using plant response and measured temperatures; check evening condensation.","Log venting, covering, and shading alongside readings; try changes on a small area first."]},{"title":"If something changes","items":["When plants wilt in wet soil, check heat and roots before adding much more water."]},{"title":"When to check","items":["Check ventilation before sunny-day heating; inspect fixings and covers before and after cold or windy weather."]}],"cautions":["A closed cover can trap heat and moisture; electric heating must follow equipment requirements for water protection, clearance, and fire safety."],"sources":[{"title":"RHS · Greenhouse ventilation and shading","url":"https://www.rhs.org.uk/garden-features/ventilation-and-shading-greenhouses"}]}'::jsonb),
  ('insect_fish', 'preset', '田螺', '{"overview":"先辨明具体螺类，检查底部摄食和水体清洁。","parameters":[],"cycle":null,"sections":[{"title":"开始前与操作","items":["确认淡水适应与食性，底面留可观察区域，避免只见壳不见活动。","购买前确认准确种名、淡水或海水及是否需要陆地区；准备可独立观察的空间。"]},{"title":"日常照护与维护","items":["查看足部活动、摄食和剩食，发现死亡个体及时确认并移除。","观察活动、摄食和躲藏点，清走剩食；更换水或添加药剂前先核对对该物种是否适用。"]},{"title":"异常先看这里","items":["连续上爬或闭壳不动时检测水质，不能只按吃藻不足来加饵。"]},{"title":"检查提醒","items":["新入缸、蜕壳或同伴数量变化后增加巡查，记录日期和所做调整。"]}],"cautions":["不要把清洁缸壁或吃残渣理解为不需要喂养，也不要放生或倾倒活体到自然水体。"],"sources":[{"title":"OATA · Freshwater aquarium care","url":"https://ornamentalfish.org/what-we-do/advice-information/care-sheets/caresheets-tropical-freshwater-fish/how-to-set-up-and-look-after-a-freshwater-tank-aquarium/"}]}'::jsonb, '{"overview":"Identify the snail and observe feeding at the bottom and water condition.","parameters":[],"cycle":null,"sections":[{"title":"Start here","items":["Confirm freshwater and dietary needs and retain a visible bottom area.","Confirm the species, freshwater/marine requirements, and any land area before purchase; prepare a separate observation space."]},{"title":"Routine care","items":["Check foot movement, feeding, and leftovers; confirm and remove deaths promptly.","Check activity, feeding, and hiding places and remove leftovers; verify species suitability before water additives or medication."]},{"title":"If something changes","items":["Persistent climbing or closure warrants water tests rather than simply adding food."]},{"title":"When to check","items":["Increase checks after introduction, molts, or changes in companions; record dates and adjustments."]}],"cautions":["Grazing algae or scraps does not mean no feeding is needed; never release animals into natural water."],"sources":[{"title":"OATA · Freshwater aquarium care","url":"https://ornamentalfish.org/what-we-do/advice-information/care-sheets/caresheets-tropical-freshwater-fish/how-to-set-up-and-look-after-a-freshwater-tank-aquarium/"}]}'::jsonb),
  ('insect_fish', 'preset', '蝗虫', '{"overview":"以辨种、寄主与数量变化记录为主，避免无计划繁殖逃逸。","parameters":[],"cycle":null,"sections":[{"title":"开始前与操作","items":["在原处记录叶片啃食与个体，若观察饲养须确认合法来源和严密防逃。","拍下成体或幼体特征、发现植物和日期，先确认对象及生活阶段。"]},{"title":"日常照护与维护","items":["检查食物是否新鲜、容器是否拥挤，定期清理粪便。","用短时观察代替频繁翻动，记录取食、蜕变和所处植物；及时清除饲养容器中的腐败物。"]},{"title":"异常先看这里","items":["出现集中啃食先记录范围并辨种，再考虑防护，不把观察个体带往异地释放。"]},{"title":"检查提醒","items":["蜕皮、化蛹或羽化前后减少触碰；变化当天拍照记录，而非按固定天数催促。"]}],"cautions":["不能可靠识别、有毒或有蜇伤风险的种类以远距离观察为主；不跨地区释放饲养个体。"],"sources":[{"title":"RHS · Wildlife in gardens","url":"https://www.rhs.org.uk/wildlife/in-gardens"}]}'::jsonb, '{"overview":"Track identity, host, and population without uncontrolled breeding or escapes.","parameters":[],"cycle":null,"sections":[{"title":"Start here","items":["Record feeding in place; captive observation needs lawful sourcing and secure containment.","Photograph identifying features, host plant, and date; establish the organism and life stage first."]},{"title":"Routine care","items":["Check food freshness and crowding and clear droppings regularly.","Use brief observation instead of repeated disturbance; log feeding, molts, and host plants and remove decaying material from kept enclosures."]},{"title":"If something changes","items":["Map concentrated feeding and identify before protection measures; never transport specimens for release elsewhere."]},{"title":"When to check","items":["Minimize handling around molts, pupation, and emergence; record the actual change rather than forcing a calendar."]}],"cautions":["Observe unidentified, venomous, or stinging organisms from a distance; do not release captive individuals in other regions."],"sources":[{"title":"RHS · Wildlife in gardens","url":"https://www.rhs.org.uk/wildlife/in-gardens"}]}'::jsonb),
  ('insect_fish', 'preset', '斗鱼', '{"overview":"提供有过滤、合适水温与休息点的环境，不以小杯长期饲养。","parameters":[],"cycle":null,"sections":[{"title":"开始前与操作","items":["雄鱼不直接同缸，检查装饰无锐边，留水面呼吸通道和防跳盖。","入鱼前用检测确认过滤系统能处理氨和亚硝酸盐，不以水清或开机天数代替检测。"]},{"title":"日常照护与维护","items":["观察食欲和鳍缘，调整过强直冲水流，给安静休息的位置。","每天先观察呼吸、游姿和摄食再投喂；记下剩饵和换水量，换水时匹配新水条件。"]},{"title":"异常先看这里","items":["长期夹鳍或躲避先查水温、水质和水流；不反复照镜刺激。"]},{"title":"检查提醒","items":["新入鱼、过滤维护或停电后增加水质检查；离家前确认有人能查看设备和动物。"]}],"cautions":["异常先查水质和设备；持续呼吸困难、损伤或不进食应联系水生动物兽医，不混用药物试错。"],"sources":[{"title":"OATA · Freshwater aquarium care","url":"https://ornamentalfish.org/what-we-do/advice-information/care-sheets/caresheets-tropical-freshwater-fish/how-to-set-up-and-look-after-a-freshwater-tank-aquarium/"}]}'::jsonb, '{"overview":"Provide suitable temperature, filtration, and resting places, not permanent cup housing.","parameters":[],"cycle":null,"sections":[{"title":"Start here","items":["Do not house males together; remove sharp decor and retain surface access and a jump-resistant lid.","Before stocking, use tests to confirm the filter handles ammonia and nitrite; clear water or elapsed days are not proof."]},{"title":"Routine care","items":["Observe appetite and fin edges, reduce excessive direct flow, and provide quiet rests.","Observe breathing, swimming, and appetite before feeding; log leftovers and water changes and match replacement-water conditions."]},{"title":"If something changes","items":["For persistent clamping or hiding, check temperature, water, and flow rather than repeated mirror stimulation."]},{"title":"When to check","items":["Increase water checks after additions, filter work, or power loss; arrange equipment and animal checks before travel."]}],"cautions":["Check water and equipment first; persistent breathing difficulty, injury, or refusal to feed needs aquatic-veterinary advice, not mixed treatments."],"sources":[{"title":"OATA · Freshwater aquarium care","url":"https://ornamentalfish.org/what-we-do/advice-information/care-sheets/caresheets-tropical-freshwater-fish/how-to-set-up-and-look-after-a-freshwater-tank-aquarium/"}]}'::jsonb),
  ('insect_fish', 'preset', '锦鲤', '{"overview":"锦鲤的长期照护以池体容量、过滤和日常巡池为基础。","parameters":[],"cycle":null,"sections":[{"title":"开始前与操作","items":["核对成鱼体型、池深与安全围护，先测试循环、排污和断电预案。","入鱼前用检测确认过滤系统能处理氨和亚硝酸盐，不以水清或开机天数代替检测。"]},{"title":"日常照护与维护","items":["投喂时逐条看体表和摄食，高温及闷热天气重点查看呼吸。","每天先观察呼吸、游姿和摄食再投喂；记下剩饵和换水量，换水时匹配新水条件。"]},{"title":"异常先看这里","items":["集体浮头或集中进水口时先查氧气和设备，暂停继续投饵并及时求助。"]},{"title":"检查提醒","items":["新入鱼、过滤维护或停电后增加水质检查；离家前确认有人能查看设备和动物。"]}],"cautions":["异常先查水质和设备；持续呼吸困难、损伤或不进食应联系水生动物兽医，不混用药物试错。"],"sources":[{"title":"OATA · Freshwater aquarium care","url":"https://ornamentalfish.org/what-we-do/advice-information/care-sheets/caresheets-tropical-freshwater-fish/how-to-set-up-and-look-after-a-freshwater-tank-aquarium/"}]}'::jsonb, '{"overview":"Long-term koi care depends on pond capacity, filtration, and routine checks.","parameters":[],"cycle":null,"sections":[{"title":"Start here","items":["Review adult size, depth, guarding, circulation, waste removal, and power-loss plans.","Before stocking, use tests to confirm the filter handles ammonia and nitrite; clear water or elapsed days are not proof."]},{"title":"Routine care","items":["Inspect each fish while feeding and pay extra attention to breathing in hot, still weather.","Observe breathing, swimming, and appetite before feeding; log leftovers and water changes and match replacement-water conditions."]},{"title":"If something changes","items":["For group gasping or clustering at the inlet, check oxygen and equipment, pause feeding, and seek prompt help."]},{"title":"When to check","items":["Increase water checks after additions, filter work, or power loss; arrange equipment and animal checks before travel."]}],"cautions":["Check water and equipment first; persistent breathing difficulty, injury, or refusal to feed needs aquatic-veterinary advice, not mixed treatments."],"sources":[{"title":"OATA · Freshwater aquarium care","url":"https://ornamentalfish.org/what-we-do/advice-information/care-sheets/caresheets-tropical-freshwater-fish/how-to-set-up-and-look-after-a-freshwater-tank-aquarium/"}]}'::jsonb),
  ('system', 'preset', '保温棚', '{"overview":"用覆盖减缓夜间失温，白天仍要能揭开散热。","parameters":[],"cycle":null,"sections":[{"title":"开始前与操作","items":["覆盖前检查支撑与压边，避免薄膜压伤嫩梢；留可快速开启的一侧。","在植物高度放温湿度计，记录晴天午后和夜间读数；留出可操作的通风口。"]},{"title":"日常照护与维护","items":["比较棚内外最低温；暖天及时通风，潮湿覆盖物晾干再收纳。","把开关棚、通风、遮阳的时间与读数一起记下，先试小范围调整。"]},{"title":"异常先看这里","items":["叶片接触膜处受损或棚内滴水多，先调整间距和通风。"]},{"title":"检查提醒","items":["晴天升温前查通风；寒潮、大风前核对固定件和覆盖层，天气过后复查。"]}],"cautions":["密闭保温可能同时积热、积湿；用电加温遵守设备的防水、间距及防火要求。"],"sources":[{"title":"RHS · Greenhouse ventilation and shading","url":"https://www.rhs.org.uk/garden-features/ventilation-and-shading-greenhouses"}]}'::jsonb, '{"overview":"Use covers to slow nighttime heat loss while retaining daytime ventilation.","parameters":[],"cycle":null,"sections":[{"title":"Start here","items":["Check supports and secured edges, prevent film pressing on shoots, and keep one side easy to open.","Place a thermometer/hygrometer at plant height; record sunny-afternoon and nighttime readings and keep vents accessible."]},{"title":"Routine care","items":["Compare indoor/outdoor minima; vent warm days and dry covers before storage.","Log venting, covering, and shading alongside readings; try changes on a small area first."]},{"title":"If something changes","items":["For contact damage or heavy dripping, adjust clearance and airflow first."]},{"title":"When to check","items":["Check ventilation before sunny-day heating; inspect fixings and covers before and after cold or windy weather."]}],"cautions":["A closed cover can trap heat and moisture; electric heating must follow equipment requirements for water protection, clearance, and fire safety."],"sources":[{"title":"RHS · Greenhouse ventilation and shading","url":"https://www.rhs.org.uk/garden-features/ventilation-and-shading-greenhouses"}]}'::jsonb),
  ('insect_fish', 'preset', '马', '{"overview":"稳定的草料、饮水、运动和蹄部检查构成每日基础。","parameters":[],"cycle":null,"sections":[{"title":"开始前与操作","items":["核对围栏、草料来源及安全饮水，日粮调整逐步进行并由专业人员评估。","按年龄、体况和繁殖阶段向当地兽医或饲养顾问确认日粮；新个体设独立观察区。"]},{"title":"日常照护与维护","items":["查看食欲、粪便、行走与蹄部，按实际活动安排照护交接。","每天实际检查饮水是否流出、食槽余量、粪便和行走；不要只记录已投了多少料。"]},{"title":"异常先看这里","items":["反复回看腹部、翻滚、出汗且不进食等异常应及时联系兽医，不自行喂药或强迫运动。"]},{"title":"检查提醒","items":["高温、转栏、换料和临近生产时增加巡查；疫苗、驱虫及用药计划交由当地兽医制定。"]}],"cautions":["倒地、明显腹胀、呼吸困难或持续不采食应及时求助；大型动物操作需有安全退路。"],"sources":[{"title":"Merck Veterinary Manual · Colic signs in horses","url":"https://www.merckvetmanual.com/horse-owners/digestive-disorders-of-horses/colic-in-horses"}]}'::jsonb, '{"overview":"Daily basics are consistent forage, water, exercise, and foot checks.","parameters":[],"cycle":null,"sections":[{"title":"Start here","items":["Review fencing, forage source, and water; adjust rations gradually with professional input.","Confirm the ration for age, condition, and reproductive stage with a local vet or nutrition adviser; separate newcomers for observation."]},{"title":"Routine care","items":["Observe appetite, manure, gait, and feet and arrange care around actual activity.","Check that water actually flows, inspect feed leftovers, manure, and gait daily, rather than recording only feed offered."]},{"title":"If something changes","items":["Repeated flank watching, rolling, sweating, or not eating needs prompt veterinary advice, not improvised medicine or forced exercise."]},{"title":"When to check","items":["Increase checks during heat, moves, ration changes, and near birth; let a local vet set vaccination, parasite, and medicine plans."]}],"cautions":["Collapse, marked bloating, breathing difficulty, or persistent appetite loss needs prompt help; keep an escape route when handling large animals."],"sources":[{"title":"Merck Veterinary Manual · Colic signs in horses","url":"https://www.merckvetmanual.com/horse-owners/digestive-disorders-of-horses/colic-in-horses"}]}'::jsonb),
  ('insect_fish', 'preset', '毛毛虫', '{"overview":"先认虫与寄主；幼虫并不能随便换一把菜叶喂。","parameters":[],"cycle":null,"sections":[{"title":"开始前与操作","items":["拍下头部、体侧与原取食植物，在确认寄主前不要更换食物。","拍下成体或幼体特征、发现植物和日期，先确认对象及生活阶段。"]},{"title":"日常照护与维护","items":["若合法观察饲养，保持通风，换新鲜寄主叶并清理粪便，不拥挤。","用短时观察代替频繁翻动，记录取食、蜕变和所处植物；及时清除饲养容器中的腐败物。"]},{"title":"异常先看这里","items":["停食并固定身体可能接近化蛹，先观察，不拉扯、不催食；不触碰未知毛刺种。"]},{"title":"检查提醒","items":["蜕皮、化蛹或羽化前后减少触碰；变化当天拍照记录，而非按固定天数催促。"]}],"cautions":["不能可靠识别、有毒或有蜇伤风险的种类以远距离观察为主；不跨地区释放饲养个体。"],"sources":[{"title":"RHS · Wildlife in gardens","url":"https://www.rhs.org.uk/wildlife/in-gardens"},{"title":"RHS · Butterflies in the garden","url":"https://www.rhs.org.uk/wildlife/butterflies-in-your-garden"}]}'::jsonb, '{"overview":"Identify the caterpillar and host; arbitrary leaves are not a substitute.","parameters":[],"cycle":null,"sections":[{"title":"Start here","items":["Photograph head, side, and original food plant before changing food.","Photograph identifying features, host plant, and date; establish the organism and life stage first."]},{"title":"Routine care","items":["For lawful captive observation, ventilate, refresh confirmed host leaves, remove waste, and avoid crowding.","Use brief observation instead of repeated disturbance; log feeding, molts, and host plants and remove decaying material from kept enclosures."]},{"title":"If something changes","items":["Stopping feeding and anchoring may precede pupation; observe rather than pull or force-feed, and do not handle unknown hairy species."]},{"title":"When to check","items":["Minimize handling around molts, pupation, and emergence; record the actual change rather than forcing a calendar."]}],"cautions":["Observe unidentified, venomous, or stinging organisms from a distance; do not release captive individuals in other regions."],"sources":[{"title":"RHS · Wildlife in gardens","url":"https://www.rhs.org.uk/wildlife/in-gardens"},{"title":"RHS · Butterflies in the garden","url":"https://www.rhs.org.uk/wildlife/butterflies-in-your-garden"}]}'::jsonb),
  ('insect_fish', 'preset', '蜻蜓', '{"overview":"幼体在水中、成体在空中，池边挺水植物是关键观察点。","parameters":[],"cycle":null,"sections":[{"title":"开始前与操作","items":["在安全池边保留出水茎秆，观察时不要挖捞或跨池搬运幼虫。","拍下成体或幼体特征、发现植物和日期，先确认对象及生活阶段。"]},{"title":"日常照护与维护","items":["检查羽化壳与成体停栖，清池前先查看植株上是否有正在羽化个体。","用短时观察代替频繁翻动，记录取食、蜕变和所处植物；及时清除饲养容器中的腐败物。"]},{"title":"异常先看这里","items":["羽化时掉落或被干扰不要反复抓取；保持安静并保留可攀附位置。"]},{"title":"检查提醒","items":["蜕皮、化蛹或羽化前后减少触碰；变化当天拍照记录，而非按固定天数催促。"]}],"cautions":["不能可靠识别、有毒或有蜇伤风险的种类以远距离观察为主；不跨地区释放饲养个体。"],"sources":[{"title":"RHS · Wildlife in gardens","url":"https://www.rhs.org.uk/wildlife/in-gardens"}]}'::jsonb, '{"overview":"Aquatic larvae and flying adults make emergent stems useful observation points.","parameters":[],"cycle":null,"sections":[{"title":"Start here","items":["Retain stems at a safe pond edge; do not dig up larvae or move them between ponds.","Photograph identifying features, host plant, and date; establish the organism and life stage first."]},{"title":"Routine care","items":["Look for cases and resting adults and inspect stems before pond maintenance.","Use brief observation instead of repeated disturbance; log feeding, molts, and host plants and remove decaying material from kept enclosures."]},{"title":"If something changes","items":["Avoid repeated handling after disturbance during emergence; retain quiet climbing surfaces."]},{"title":"When to check","items":["Minimize handling around molts, pupation, and emergence; record the actual change rather than forcing a calendar."]}],"cautions":["Observe unidentified, venomous, or stinging organisms from a distance; do not release captive individuals in other regions."],"sources":[{"title":"RHS · Wildlife in gardens","url":"https://www.rhs.org.uk/wildlife/in-gardens"}]}'::jsonb),
  ('insect_fish', 'preset', '螃蟹', '{"overview":"先确定是淡水、汽水还是海水蟹，以及需要多少陆地。","parameters":[],"cycle":null,"sections":[{"title":"开始前与操作","items":["向来源方核对准确物种；需要陆栖区的，先测试能轻松出水和防逃逸。","购买前确认准确种名、淡水或海水及是否需要陆地区；准备可独立观察的空间。"]},{"title":"日常照护与维护","items":["从外部观察上岸、进食与蜕壳，清走陆区残饵，保持必要通风。","观察活动、摄食和躲藏点，清走剩食；更换水或添加药剂前先核对对该物种是否适用。"]},{"title":"异常先看这里","items":["不断攀爬或持续泡在不合适区域时先复核水陆设置，不能按所有蟹通用参数处理。"]},{"title":"检查提醒","items":["新入缸、蜕壳或同伴数量变化后增加巡查，记录日期和所做调整。"]}],"cautions":["不要把清洁缸壁或吃残渣理解为不需要喂养，也不要放生或倾倒活体到自然水体。"],"sources":[{"title":"OATA · Freshwater aquarium care","url":"https://ornamentalfish.org/what-we-do/advice-information/care-sheets/caresheets-tropical-freshwater-fish/how-to-set-up-and-look-after-a-freshwater-tank-aquarium/"}]}'::jsonb, '{"overview":"Identify freshwater, brackish, or marine needs and the required land area.","parameters":[],"cycle":null,"sections":[{"title":"Start here","items":["Confirm the species; where land is needed, test easy water exits and escape protection.","Confirm the species, freshwater/marine requirements, and any land area before purchase; prepare a separate observation space."]},{"title":"Routine care","items":["Observe land use, feeding, and molts; remove land-area leftovers and retain ventilation.","Check activity, feeding, and hiding places and remove leftovers; verify species suitability before water additives or medication."]},{"title":"If something changes","items":["For persistent climbing or unsuitable water/land use, review habitat rather than using universal crab settings."]},{"title":"When to check","items":["Increase checks after introduction, molts, or changes in companions; record dates and adjustments."]}],"cautions":["Grazing algae or scraps does not mean no feeding is needed; never release animals into natural water."],"sources":[{"title":"OATA · Freshwater aquarium care","url":"https://ornamentalfish.org/what-we-do/advice-information/care-sheets/caresheets-tropical-freshwater-fish/how-to-set-up-and-look-after-a-freshwater-tank-aquarium/"}]}'::jsonb),
  ('insect_fish', 'preset', '蟾蜍', '{"overview":"以地面躲藏、适当湿度与清洁出水条件为重点。","parameters":[],"cycle":null,"sections":[{"title":"开始前与操作","items":["先辨种，准备可躲藏地面和易进出的水区，避免粗糙锐利材料。","先确认生活阶段和物种；分别检查水区、陆区与出水坡道，不能只按“蛙类”设置。"]},{"title":"日常照护与维护","items":["从外部观察皮肤和活动，清除残饵并检查基质是否积水。","少接触皮肤，清走残饵；每天从外部观察姿态、体表和水区状态。"]},{"title":"异常先看这里","items":["不断泡水、异常消瘦或皮肤变化时核对环境，不把所有分泌物都当病变处理。"]},{"title":"检查提醒","items":["变态、季节变化和拒食时复核栖息条件；异常记录照片供专业人员判断。"]}],"cautions":["不抓野生个体回家混养；持续失衡、皮肤病变或明显消瘦应咨询异宠兽医。"],"sources":[{"title":"RSPCA · Caring for exotic pets","url":"https://www.rspca.org.uk/adviceandwelfare/pets/other"}]}'::jsonb, '{"overview":"Focus on terrestrial shelter, suitable moisture, and safe water access.","parameters":[],"cycle":null,"sections":[{"title":"Start here","items":["Identify the species and provide ground hides and easy water entry/exit without sharp materials.","Identify species and life stage; check water, land, and exit routes rather than using a single frog setup."]},{"title":"Routine care","items":["Observe skin/activity externally and remove leftovers and waterlogged substrate.","Minimize skin contact and remove leftovers; observe posture, skin, and water conditions from outside each day."]},{"title":"If something changes","items":["Persistent soaking, weight loss, or skin changes need environment review; not every secretion indicates disease."]},{"title":"When to check","items":["Review conditions at metamorphosis, seasonal changes, or appetite loss; photograph abnormalities for professional advice."]}],"cautions":["Do not collect wild animals for mixed housing; persistent imbalance, skin lesions, or weight loss needs an exotics vet."],"sources":[{"title":"RSPCA · Caring for exotic pets","url":"https://www.rspca.org.uk/adviceandwelfare/pets/other"}]}'::jsonb),
  ('insect_fish', 'preset', '麻雀', '{"overview":"以观察群体取食、洗浴和季节变化为主，不捉幼鸟饲养。","parameters":[],"cycle":null,"sections":[{"title":"开始前与操作","items":["选择远离猫狗干扰的观察点，保留安全草籽和灌丛环境。","在原处选固定观察点，不抓捕、不搬巢，也不为了照片驱赶动物。"]},{"title":"日常照护与维护","items":["记录群体数量与停留时段，若提供水盆则经常清洁并保持浅水。","记录时间、天气、数量与行为；保持观察距离，减少夜灯、噪声和宠物追逐。"]},{"title":"异常先看这里","items":["看到刚离巢幼鸟先远距离观察亲鸟，不立即带走。"]},{"title":"检查提醒","items":["繁殖或育幼期减少靠近；受伤个体先联系当地野生动物救助机构。"]}],"cautions":["不要把暂时停留或幼鸟离巢当作被遗弃；不强行喂水、喂奶或饲喂人类饭菜。"],"sources":[{"title":"RHS · Wildlife in gardens","url":"https://www.rhs.org.uk/wildlife/in-gardens"},{"title":"Cornell Lab · Window collisions and injured birds","url":"https://www.allaboutbirds.org/news/why-birds-hit-windows-and-how-you-can-help-prevent-it/"}]}'::jsonb, '{"overview":"Observe flock feeding, bathing, and seasons rather than taking young sparrows.","parameters":[],"cycle":null,"sections":[{"title":"Start here","items":["Choose a spot away from pets and retain safe seed-bearing plants and shrubs.","Choose a fixed observation point in place; do not capture, move nests, or drive animals for a photo."]},{"title":"Routine care","items":["Log flock size and timing; if providing water, keep it shallow and clean.","Log time, weather, number, and behavior; keep distance and reduce night lighting, noise, and pet chasing."]},{"title":"If something changes","items":["For a fledgling, watch for parents from a distance before assuming it needs removal."]},{"title":"When to check","items":["Increase distance during nesting or rearing; contact a local wildlife rehabilitator for injured animals."]}],"cautions":["Resting or fledging is not automatically abandonment; do not force water, milk, or human meals."],"sources":[{"title":"RHS · Wildlife in gardens","url":"https://www.rhs.org.uk/wildlife/in-gardens"},{"title":"Cornell Lab · Window collisions and injured birds","url":"https://www.allaboutbirds.org/news/why-birds-hit-windows-and-how-you-can-help-prevent-it/"}]}'::jsonb),
  ('insect_fish', 'preset', '螨', '{"overview":"螨既有害螨也有捕食螨，先识别损伤和对象，不能一律清除。","parameters":[],"cycle":null,"sections":[{"title":"开始前与操作","items":["用放大镜检查叶背、网丝和斑点，拍照并记录受影响植物。","拍下成体或幼体特征、发现植物和日期，先确认对象及生活阶段。"]},{"title":"日常照护与维护","items":["有疑似受害盆栽先分开放，检查新梢与邻盆，工具使用后清洁。","用短时观察代替频繁翻动，记录取食、蜕变和所处植物；及时清除饲养容器中的腐败物。"]},{"title":"异常先看这里","items":["扩散或辨识不清时请专业人员确认；不自行混配杀螨剂或把用于动物的药喷植物。"]},{"title":"检查提醒","items":["蜕皮、化蛹或羽化前后减少触碰；变化当天拍照记录，而非按固定天数催促。"]}],"cautions":["不能可靠识别、有毒或有蜇伤风险的种类以远距离观察为主；不跨地区释放饲养个体。"],"sources":[{"title":"RHS · Wildlife in gardens","url":"https://www.rhs.org.uk/wildlife/in-gardens"}]}'::jsonb, '{"overview":"Mites include pests and predators; identify damage and the organism before acting.","parameters":[],"cycle":null,"sections":[{"title":"Start here","items":["Use magnification on leaf undersides, webbing, and speckles and record affected plants.","Photograph identifying features, host plant, and date; establish the organism and life stage first."]},{"title":"Routine care","items":["Separate suspect potted plants, inspect new growth/neighbors, and clean tools after use.","Use brief observation instead of repeated disturbance; log feeding, molts, and host plants and remove decaying material from kept enclosures."]},{"title":"If something changes","items":["For spread or uncertainty, seek identification; do not mix miticides or apply animal medicines to plants."]},{"title":"When to check","items":["Minimize handling around molts, pupation, and emergence; record the actual change rather than forcing a calendar."]}],"cautions":["Observe unidentified, venomous, or stinging organisms from a distance; do not release captive individuals in other regions."],"sources":[{"title":"RHS · Wildlife in gardens","url":"https://www.rhs.org.uk/wildlife/in-gardens"}]}'::jsonb),
  ('other', 'preset', '腐乳', '{"overview":"要分清受控接种与自然长霉，白色外观不能证明菌种安全。","parameters":[],"cycle":null,"sections":[{"title":"开始前与操作","items":["只能采用明确的食品用菌种和配套验证工艺；缺少控温、卫生和成熟条件时优先选可靠成品。","开始前要有适用于该食品的明确菌种和经过验证的完整工艺；记录盐量、温度与容器，不凭口味减盐。"]},{"title":"日常照护与维护","items":["把原料、菌种批号、温度及盐量逐项记录，避免其他食物与容器交叉接触。","每次检查先清洁工具；按原工艺管理液面、通气和温度，不边做边更换配方。"]},{"title":"异常先看这里","items":["菌种不明、颜色异常或过程失控时不要试吃，不用刮掉表面继续腌制。"]},{"title":"检查提醒","items":["关键温度、时间或配比失控就停止作为可食用成品使用；不要把补盐、再煮或挑掉霉点当作补救。"]}],"cautions":["此页用于操作前核查和过程记录，不构成家庭自然发酵配方；缺少可靠工艺时选择有资质来源的成品。"],"sources":[{"title":"NCHFP · Fermentation controls","url":"https://nchfp.uga.edu/how/ferment/general-information-on-fermenting/"},{"title":"Centre for Food Safety · Safe bean-curd preparation","url":"https://www.cfs.gov.hk/english/multimedia/multimedia_pub/multimedia_pub_fsf_239_02.html"}]}'::jsonb, '{"overview":"Controlled inoculation is different from spontaneous mold; white growth does not identify a safe culture.","parameters":[],"cycle":null,"sections":[{"title":"Start here","items":["Use only a defined food culture with a validated process; choose a reputable finished product if temperature/hygiene/maturation cannot be controlled.","Start only with an identified culture and a validated process for that food; record salt, temperature, and vessel, and do not reduce salt by taste."]},{"title":"Routine care","items":["Record raw ingredients, culture lot, temperature, and salt and prevent cross-contact with other foods/vessels.","Clean tools before checks and manage liquid level, aeration, and temperature according to the original method rather than changing recipes mid-process."]},{"title":"If something changes","items":["Unknown cultures, abnormal colors, or failed controls mean no tasting or scraping off the surface to continue."]},{"title":"When to check","items":["If critical time, temperature, or proportions fail, stop treating the batch as edible; extra salt, reheating, or removing mold is not a validated rescue."]}],"cautions":["This is a preparation and process-check guide, not a spontaneous-fermentation recipe; choose a reputable finished product if a reliable process is unavailable."],"sources":[{"title":"NCHFP · Fermentation controls","url":"https://nchfp.uga.edu/how/ferment/general-information-on-fermenting/"},{"title":"Centre for Food Safety · Safe bean-curd preparation","url":"https://www.cfs.gov.hk/english/multimedia/multimedia_pub/multimedia_pub_fsf_239_02.html"}]}'::jsonb),
  ('other', 'preset', '米酒', '{"overview":"这里做甜酒酿：先蒸熟糯米、降温拌曲，再受控保温。酒曲浓度不同，先核对包装，不套用同一个克数。","parameters":[{"label":"糯米与酒曲示例","value":"干糯米500g；若酒曲标注8g配2kg米，则用2g"},{"label":"拌曲／保温","value":"米饭降至约35℃拌曲；约30℃保温"},{"label":"观察时间","value":"约24–36小时开始检查，按该酒曲说明结束"}],"cycle":null,"sections":[{"title":"泡米与蒸饭","items":["洗净糯米，按酒曲配套做法浸泡至米粒能碾碎，再沥水蒸熟；抽查中间米粒，不能留硬白芯。","备电子秤、探针温度计和洁净发酵盒；容器与工具不沾生水、油污或其他生食物。"]},{"title":"降温与拌曲","items":["把熟米摊开，实测降至酒曲要求的温度再拌入，不只摸表面觉得不烫就判断内部也降温了。","按包装配套用水要求，用放凉的已煮沸饮用水帮助拌匀；不要另加一大瓶水把甜酒酿变成果酒配方。"]},{"title":"保温与观察","items":["装盒后留排气条件，在约30℃的稳定环境保温，记录入盒时间和米层温度；不用密封玻璃瓶承压。","按时查看正常出汁和气味变化，不反复用吃过的勺试味；长异常毛、黑点或发红发黄时整批停止食用。"]},{"title":"及时结束与冷藏","items":["达到酒曲规定的完成状态后及时结束保温；按生产商建议煮熟，分小份快速降温后冷藏，不一直放在温暖处继续养。","记录制作和冷藏日期，短期用不完就分装冷冻；变质批次不能靠煮熟补救，甜酒酿也可能含酒精。"]}],"cautions":["2g酒曲只适用于上述标注浓度，不是所有散曲、酒药或不同品牌的通用剂量；缺少可靠说明时不猜测配比。"],"sources":[{"title":"安琪 · 甜酒曲8g（接种温度与24–36小时示例）","url":"https://dimsum.angelyeast.com/contents/4297/73341.html"},{"title":"安琪 · 自制米酒六个关键（用量与异常处理）","url":"https://dimsum.angelyeast.com/contents/4135/82079.html"},{"title":"FoodSafety.gov · Cooling and refrigeration","url":"https://www.foodsafety.gov/keep-food-safe/4-steps-to-food-safety"}]}'::jsonb, '{"overview":"This example makes sweet fermented rice: steam, cool, inoculate and incubate under control. Starter strengths differ, so check the package first.","parameters":[{"label":"Rice and starter example","value":"500 g dry glutinous rice; use 2 g only when the starter specifies 8 g per 2 kg rice"},{"label":"Inoculation / incubation","value":"Cool rice to about 35°C to inoculate; incubate around 30°C"},{"label":"Check time","value":"Begin checks around 24–36 hours; finish according to that starter''s directions"}],"cycle":null,"sections":[{"title":"Soak and steam","items":["Wash and soak rice as the starter directs until crushable, drain and steam; check central grains for uncooked hard cores.","Prepare scales, a probe thermometer and a clean fermenter; avoid untreated water, grease and raw-food contamination."]},{"title":"Cool and inoculate","items":["Spread cooked rice and measure its temperature before adding starter; a cool surface does not establish a cool center.","Use cooled boiled drinking water in the amount specified by the starter to mix evenly; do not improvise a large extra-water addition."]},{"title":"Incubate and observe","items":["Allow venting, incubate steadily around 30°C, and record start time and rice temperature; do not pressurize sealed glass.","Monitor expected liquid and aroma without reused tasting spoons; stop food use for unexpected growth, dark spots or red/yellow discoloration."]},{"title":"Finish and refrigerate","items":["End incubation at the starter''s specified completion point; cook as the manufacturer directs, cool small portions promptly and refrigerate.","Date preparation and refrigeration; freeze portions not needed soon. Cooking does not rescue spoiled batches, and sweet rice wine may contain alcohol."]}],"cautions":["The 2 g dose applies only to the specified labeled strength, not every loose or branded starter. Do not guess without reliable directions."],"sources":[{"title":"安琪 · 甜酒曲8g（接种温度与24–36小时示例）","url":"https://dimsum.angelyeast.com/contents/4297/73341.html"},{"title":"安琪 · 自制米酒六个关键（用量与异常处理）","url":"https://dimsum.angelyeast.com/contents/4135/82079.html"},{"title":"FoodSafety.gov · Cooling and refrigeration","url":"https://www.foodsafety.gov/keep-food-safe/4-steps-to-food-safety"}]}'::jsonb),
  ('system', 'preset', '板结改良', '{"overview":"先减少踩踏和湿土作业，再处理硬层；反复深翻或随意掺沙并不是通用解法。","parameters":[{"label":"先分清","value":"表面结壳、踩踏压实、天然黏重"},{"label":"动土条件","value":"土可松散碎开，不黏工具、不积水"}],"cycle":null,"sections":[{"title":"定位与处理","items":["在无主要根系和管线的小处检查阻力深度，比较通道与种植床；先划出固定通道，浇水和采收不再踩进床内。","等土不黏工具时，小区用园叉轻提松动，不反复粉碎；已有树根处不强行翻动，可改用适宜有机覆盖。"]},{"title":"保持与复查","items":["按土壤状态补充腐熟有机物并保留覆盖；不要凭手感给黏土统一配一个沙土比例。","记录松动范围与深度，下次雨后比较渗水；若很快恢复积水，转查排水出口或更深土层，不继续加大翻动。"]}],"cautions":["土湿时踩踏、推车或旋耕会加重压实；靠近管线、挡土墙和大树根系时先请专业人员判断。"],"sources":[{"title":"UMN Extension · Soil compaction","url":"https://extension.umn.edu/soil-compaction"},{"title":"RHS · Clay soils","url":"https://www.rhs.org.uk/soil-composts-mulches/clay-soils"}]}'::jsonb, '{"overview":"Reduce traffic and wet-soil working before addressing hard layers. Repeated deep digging or adding sand is not a universal remedy.","parameters":[{"label":"Distinguish","value":"Surface crust, traffic compaction, natural clay"},{"label":"Workability","value":"Soil crumbles rather than sticking or smearing"}],"cycle":null,"sections":[{"title":"Locate and treat","items":["In a safe spot clear of major roots and utilities, compare hard-layer depth in paths and beds. Establish permanent paths for watering and harvest.","When soil is workable, gently lift a trial patch with a garden fork rather than pulverizing it. Avoid disturbing established tree roots; consider suitable mulch."]},{"title":"Maintain and review","items":["Use mature organic matter and cover where appropriate. Do not prescribe a universal sand ratio from soil feel alone.","Log treated area and depth, then compare infiltration after rain. If pooling returns, investigate drainage or deeper layers instead of escalating cultivation."]}],"cautions":["Traffic and cultivation on wet soil can worsen compaction. Get professional advice near utilities, retaining structures, or major tree roots."],"sources":[{"title":"UMN Extension · Soil compaction","url":"https://extension.umn.edu/soil-compaction"},{"title":"RHS · Clay soils","url":"https://www.rhs.org.uk/soil-composts-mulches/clay-soils"}]}'::jsonb),
  ('other', 'preset', '醋', '{"overview":"苹果醋分两步：先把果汁发酵成苹果酒，再让醋酸菌在有氧条件下转成醋。两阶段容器、通气和观察方式不同。","parameters":[{"label":"示例用量","value":"苹果汁3L；第二阶段加约625mL活性醋种"},{"label":"果酒阶段","value":"约16–27℃；至少约2周并核对发酵状态"},{"label":"成醋阶段","value":"约27–29℃有利于转化；通常需数周至数月"}],"cycle":null,"sections":[{"title":"备料与容器","items":["用不含抑菌防腐剂的苹果汁3L；食品用酿造酵母按该菌种包装剂量，另备来源可靠的活性醋种约625mL。不要用腐烂苹果或自来路不明的菌膜。","清洗消毒食品用玻璃或不锈钢容器，留出起泡空间；准备温度计、气锁和比重计，不使用会被酸腐蚀的金属。"]},{"title":"第一步：先做苹果酒","items":["按酵母要求接种，装气锁排气，在约16–27℃且适合该酵母的稳定环境发酵。记录起始比重，每隔几天复测。","约两周后开始核对是否结束：依所选方法确认比重稳定，不仅凭不冒泡判断；仍产气时不能密闭装瓶。"]},{"title":"第二步：接醋种、通气","items":["把完成发酵的酒液转离沉淀，再加入醋种。换成宽口容器，液体约占容器2/3，口部用洁净透气布固定并防果蝇；不能继续用密闭方式缺氧养醋。","以约27–29℃作为这一阶段的温度参考，避直晒；每周用洁净工具取少量检查并记录。需数周至数月，菌种、酒精度和通气会改变速度。"]},{"title":"结束、保存与用途","items":["按所选醋种工艺确认转化结束后过滤、装洁净容器并冷藏；有霉毛、异常颜色或腐败气味时整批停止食用，不把它混入下一批。","酸味与家用pH试纸不能得出醋酸百分比。自酿醋酸度未验证时，只按短期冷藏调味用途管理，不能替代安全腌渍或罐藏配方要求的5%标准商品醋。"]}],"cautions":["这里给出的是苹果汁发酵示例，不是“苹果碎＋糖水”任意配比的保质承诺。时间到、变酸或长出菌膜都不能单独证明食品安全。"],"sources":[{"title":"Revolution Fermentation · Apple-cider vinegar（原料与分阶段操作示例）","url":"https://revolutionfermentation.com/en/blogs/fermented-beverages/apple-cider-vinegar-recipe/"},{"title":"NC State Extension · Vinegar making（通气与温度）","url":"https://content.ces.ncsu.edu/vinegar-making"},{"title":"Penn State Extension · Making cider vinegar at home","url":"https://extension.psu.edu/making-cider-vinegar-at-home/"},{"title":"NCHFP · Pickling acidity requirements","url":"https://nchfp.uga.edu/how/pickle/general-information-pickling/general-information-on-pickling/"}]}'::jsonb, '{"overview":"Apple-cider vinegar has two stages: yeast turns juice into cider, then acetic-acid bacteria work with oxygen. Venting and monitoring differ between stages.","parameters":[{"label":"Example quantities","value":"3 L apple juice; about 625 mL active vinegar starter in stage two"},{"label":"Cider stage","value":"About 16–27°C; roughly two weeks or more, with fermentation checks"},{"label":"Vinegar stage","value":"About 27–29°C favors conversion; allow weeks to months"}],"cycle":null,"sections":[{"title":"Ingredients and equipment","items":["Use 3 L apple juice without fermentation-inhibiting preservatives, food-grade brewing yeast at its labeled dose, and about 625 mL traceable active vinegar starter. Exclude rotten fruit or unidentified cultures.","Clean and sanitize food-safe glass or stainless equipment, leaving foaming space. Prepare a thermometer, airlock and hydrometer; avoid acid-reactive metals."]},{"title":"Stage one: make cider","items":["Pitch as directed, fit an airlock and keep within the yeast''s specified range, approximately 16–27°C. Record starting gravity and recheck during fermentation.","Begin checking completion after roughly two weeks. Confirm stable gravity under the chosen method rather than relying only on bubbles; never bottle under pressure during active fermentation."]},{"title":"Stage two: inoculate and aerate","items":["Transfer finished cider off sediment and add starter. Use a wide-mouth vessel roughly two-thirds full, secured with clean breathable cloth against fruit flies; acetic fermentation needs air.","Use approximately 27–29°C as a stage-two reference and avoid direct sun. Sample cleanly and log progress weekly; culture, alcohol and aeration can make this take weeks or months."]},{"title":"Finish, store and use","items":["Confirm completion using the starter''s process, then strain into clean containers and refrigerate. Discard food use of fuzzy mold, abnormal colors or putrid batches; do not seed the next batch with them.","Taste and home pH strips do not measure percent acetic acid. Without verified acidity, treat this as a refrigerated condiment, not a substitute for the standardized 5% vinegar in a tested preservation recipe."]}],"cautions":["This is a juice-based worked example, not a shelf-life promise for arbitrary apple-scrap and sugar-water mixtures. Elapsed time, sourness or a surface culture alone cannot establish safety."],"sources":[{"title":"Revolution Fermentation · Apple-cider vinegar（原料与分阶段操作示例）","url":"https://revolutionfermentation.com/en/blogs/fermented-beverages/apple-cider-vinegar-recipe/"},{"title":"NC State Extension · Vinegar making（通气与温度）","url":"https://content.ces.ncsu.edu/vinegar-making"},{"title":"Penn State Extension · Making cider vinegar at home","url":"https://extension.psu.edu/making-cider-vinegar-at-home/"},{"title":"NCHFP · Pickling acidity requirements","url":"https://nchfp.uga.edu/how/pickle/general-information-pickling/general-information-on-pickling/"}]}'::jsonb),
  ('insect_fish', 'preset', '蛾', '{"overview":"多在夜间活动，可用固定位置观察，不长时间强光追照。","parameters":[],"cycle":null,"sections":[{"title":"开始前与操作","items":["记录发现植物和停栖位置，先拍翅形与姿态辨种。","拍下成体或幼体特征、发现植物和日期，先确认对象及生活阶段。"]},{"title":"日常照护与维护","items":["保留幼虫寄主和安静角落，夜间用短时低干扰观察记录。","用短时观察代替频繁翻动，记录取食、蜕变和所处植物；及时清除饲养容器中的腐败物。"]},{"title":"异常先看这里","items":["室内大量出现时先核对是否储粮害虫，别把室内治理和庭院观察混为一谈。"]},{"title":"检查提醒","items":["蜕皮、化蛹或羽化前后减少触碰；变化当天拍照记录，而非按固定天数催促。"]}],"cautions":["不能可靠识别、有毒或有蜇伤风险的种类以远距离观察为主；不跨地区释放饲养个体。"],"sources":[{"title":"RHS · Wildlife in gardens","url":"https://www.rhs.org.uk/wildlife/in-gardens"}]}'::jsonb, '{"overview":"Observe moths from a fixed spot without prolonged bright-light pursuit.","parameters":[],"cycle":null,"sections":[{"title":"Start here","items":["Record the plant and resting site and photograph wing shape and posture for identification.","Photograph identifying features, host plant, and date; establish the organism and life stage first."]},{"title":"Routine care","items":["Retain host plants and quiet corners and use brief, low-disturbance nighttime checks.","Use brief observation instead of repeated disturbance; log feeding, molts, and host plants and remove decaying material from kept enclosures."]},{"title":"If something changes","items":["Many indoors warrant checking stored-food pests; indoor control and garden observation are different tasks."]},{"title":"When to check","items":["Minimize handling around molts, pupation, and emergence; record the actual change rather than forcing a calendar."]}],"cautions":["Observe unidentified, venomous, or stinging organisms from a distance; do not release captive individuals in other regions."],"sources":[{"title":"RHS · Wildlife in gardens","url":"https://www.rhs.org.uk/wildlife/in-gardens"}]}'::jsonb),
  ('insect_fish', 'preset', '螯虾', '{"overview":"提前安排防逃和蜕壳避让，不默认能与鱼虾混养。","parameters":[],"cycle":null,"sections":[{"title":"开始前与操作","items":["核对成年大小，盖好可攀出的管线缝，准备各自可退入的躲藏处。","购买前确认准确种名、淡水或海水及是否需要陆地区；准备可独立观察的空间。"]},{"title":"日常照护与维护","items":["投喂后查看是否互相争抢，蜕壳时减少干扰并观察同伴接近。","观察活动、摄食和躲藏点，清走剩食；更换水或添加药剂前先核对对该物种是否适用。"]},{"title":"异常先看这里","items":["伤肢或反复追咬时先分开风险个体并调整空间，不靠多投食解决一切。"]},{"title":"检查提醒","items":["新入缸、蜕壳或同伴数量变化后增加巡查，记录日期和所做调整。"]}],"cautions":["不要把清洁缸壁或吃残渣理解为不需要喂养，也不要放生或倾倒活体到自然水体。"],"sources":[{"title":"OATA · Freshwater aquarium care","url":"https://ornamentalfish.org/what-we-do/advice-information/care-sheets/caresheets-tropical-freshwater-fish/how-to-set-up-and-look-after-a-freshwater-tank-aquarium/"}]}'::jsonb, '{"overview":"Plan escape protection and molt refuges; do not assume fish/shrimp compatibility.","parameters":[],"cycle":null,"sections":[{"title":"Start here","items":["Confirm adult size, secure gaps around climbable pipes, and provide separate refuges.","Confirm the species, freshwater/marine requirements, and any land area before purchase; prepare a separate observation space."]},{"title":"Routine care","items":["Check food competition and limit disturbance around molts and approaching companions.","Check activity, feeding, and hiding places and remove leftovers; verify species suitability before water additives or medication."]},{"title":"If something changes","items":["For injuries or repeated attacks, separate at-risk animals and review space rather than just feeding more."]},{"title":"When to check","items":["Increase checks after introduction, molts, or changes in companions; record dates and adjustments."]}],"cautions":["Grazing algae or scraps does not mean no feeding is needed; never release animals into natural water."],"sources":[{"title":"OATA · Freshwater aquarium care","url":"https://ornamentalfish.org/what-we-do/advice-information/care-sheets/caresheets-tropical-freshwater-fish/how-to-set-up-and-look-after-a-freshwater-tank-aquarium/"}]}'::jsonb),
  ('insect_fish', 'preset', '燕子', '{"overview":"保护飞行通道和巢周边安静，观察筑巢与育雏即可。","parameters":[],"cycle":null,"sections":[{"title":"开始前与操作","items":["从不挡出入口的位置观察，不改动使用中的巢或巢下结构。","在原处选固定观察点，不抓捕、不搬巢，也不为了照片驱赶动物。"]},{"title":"日常照护与维护","items":["用固定距离记录进出频次，清理环境时避开繁殖活动。","记录时间、天气、数量与行为；保持观察距离，减少夜灯、噪声和宠物追逐。"]},{"title":"异常先看这里","items":["幼鸟落地或巢损坏时先联系救助人员，不用米饭、牛奶强喂。"]},{"title":"检查提醒","items":["繁殖或育幼期减少靠近；受伤个体先联系当地野生动物救助机构。"]}],"cautions":["不要把暂时停留或幼鸟离巢当作被遗弃；不强行喂水、喂奶或饲喂人类饭菜。"],"sources":[{"title":"RHS · Wildlife in gardens","url":"https://www.rhs.org.uk/wildlife/in-gardens"},{"title":"Cornell Lab · Window collisions and injured birds","url":"https://www.allaboutbirds.org/news/why-birds-hit-windows-and-how-you-can-help-prevent-it/"}]}'::jsonb, '{"overview":"Keep flight paths and nests undisturbed and observe nesting/rearing.","parameters":[],"cycle":null,"sections":[{"title":"Start here","items":["Observe without blocking entrances or altering occupied nests or supporting structures.","Choose a fixed observation point in place; do not capture, move nests, or drive animals for a photo."]},{"title":"Routine care","items":["Record visits from a fixed distance and avoid disturbing breeding during cleaning.","Log time, weather, number, and behavior; keep distance and reduce night lighting, noise, and pet chasing."]},{"title":"If something changes","items":["For fallen chicks or damaged nests, contact rehabilitation help rather than force-feeding rice or milk."]},{"title":"When to check","items":["Increase distance during nesting or rearing; contact a local wildlife rehabilitator for injured animals."]}],"cautions":["Resting or fledging is not automatically abandonment; do not force water, milk, or human meals."],"sources":[{"title":"RHS · Wildlife in gardens","url":"https://www.rhs.org.uk/wildlife/in-gardens"},{"title":"Cornell Lab · Window collisions and injured birds","url":"https://www.allaboutbirds.org/news/why-birds-hit-windows-and-how-you-can-help-prevent-it/"}]}'::jsonb),
  ('insect_fish', 'preset', '青蛙', '{"overview":"从蝌蚪到成蛙需求不同，观察阶段变化比固定天数更重要。","parameters":[],"cycle":null,"sections":[{"title":"开始前与操作","items":["确认是水栖或半水栖种，转为陆栖的阶段提前准备容易爬出的缓坡。","先确认生活阶段和物种；分别检查水区、陆区与出水坡道，不能只按“蛙类”设置。"]},{"title":"日常照护与维护","items":["查看能否正常上岸、皮肤和取食，水陆区域分别清理。","少接触皮肤，清走残饵；每天从外部观察姿态、体表和水区状态。"]},{"title":"异常先看这里","items":["开始长肢或尾部缩短时重新核对出水条件，不让幼体困在深水中。"]},{"title":"检查提醒","items":["变态、季节变化和拒食时复核栖息条件；异常记录照片供专业人员判断。"]}],"cautions":["不抓野生个体回家混养；持续失衡、皮肤病变或明显消瘦应咨询异宠兽医。"],"sources":[{"title":"RSPCA · Caring for exotic pets","url":"https://www.rspca.org.uk/adviceandwelfare/pets/other"}]}'::jsonb, '{"overview":"Tadpoles and adults differ; follow the actual life stage, not a fixed day count.","parameters":[],"cycle":null,"sections":[{"title":"Start here","items":["Identify aquatic or semi-aquatic needs and prepare easy exits before a land-going stage.","Identify species and life stage; check water, land, and exit routes rather than using a single frog setup."]},{"title":"Routine care","items":["Check water exits, skin, and feeding and clean land/water areas separately.","Minimize skin contact and remove leftovers; observe posture, skin, and water conditions from outside each day."]},{"title":"If something changes","items":["When limbs develop or the tail shortens, review exit access so transitioning animals are not trapped."]},{"title":"When to check","items":["Review conditions at metamorphosis, seasonal changes, or appetite loss; photograph abnormalities for professional advice."]}],"cautions":["Do not collect wild animals for mixed housing; persistent imbalance, skin lesions, or weight loss needs an exotics vet."],"sources":[{"title":"RSPCA · Caring for exotic pets","url":"https://www.rspca.org.uk/adviceandwelfare/pets/other"}]}'::jsonb),
  ('insect_fish', 'preset', '兔', '{"overview":"每天看吃进去多少、排出来多少，比只看食盆是否满更有用。","parameters":[],"cycle":null,"sections":[{"title":"开始前与操作","items":["稳定原来食物后逐步调整，提供干草、清水和安全啃咬活动，不仅限小笼。","准备可持续取食的合适干草、清水、躲藏和活动区；食物更换分步进行。"]},{"title":"日常照护与维护","items":["记录便粒数量与大小、食欲和活动，清理臀部周围不洁并检查足底。","每天确认实际进食和排便，检查臀部、足底及饮水器是否正常出水。"]},{"title":"异常先看这里","items":["突然不吃、便量骤减、腹部明显不适应尽快就医，不等几天观察。"]},{"title":"检查提醒","items":["每天同一时段观察；不吃或便量明显减少不要等到下一次例行检查，应尽快联系兽医。"]}],"cautions":["不要把兔子当小型家禽喂养；不自行用人药或强迫灌食不明原因拒食的个体。"],"sources":[{"title":"RSPCA · Rabbit health checks","url":"https://www.rspca.org.uk/adviceandwelfare/pets/rabbits/health"}]}'::jsonb, '{"overview":"Actual intake and droppings matter more than a full food bowl.","parameters":[],"cycle":null,"sections":[{"title":"Start here","items":["Stabilize the previous diet before gradual changes; provide hay, water, safe chewing, and exercise beyond a small cage.","Provide suitable hay, fresh water, hiding places, and exercise space; change foods gradually."]},{"title":"Routine care","items":["Track dropping size/number, appetite, and activity and inspect rear cleanliness and feet.","Confirm eating and droppings each day and check the rear, feet, and functioning drinker."]},{"title":"If something changes","items":["Sudden appetite loss, sharply reduced droppings, or abdominal discomfort needs prompt veterinary care."]},{"title":"When to check","items":["Observe at the same time daily; not eating or a marked drop in droppings needs prompt veterinary advice, not the next routine check."]}],"cautions":["Rabbits are not small poultry; do not use human medicines or force-feed unexplained appetite loss without veterinary direction."],"sources":[{"title":"RSPCA · Rabbit health checks","url":"https://www.rspca.org.uk/adviceandwelfare/pets/rabbits/health"}]}'::jsonb),
  ('insect_fish', 'preset', '蚯蚓', '{"overview":"先分清土栖观察与堆肥蚯蚓，不把所有蚯蚓放进同一个厨余桶。","parameters":[],"cycle":null,"sections":[{"title":"开始前与操作","items":["确认用于堆肥的种类，准备疏松湿润垫料和遮阴通风位置。","拍下成体或幼体特征、发现植物和日期，先确认对象及生活阶段。"]},{"title":"日常照护与维护","items":["少量分区投食，查看旧料消耗与湿度，避免翻动过度或让垫料积水。","用短时观察代替频繁翻动，记录取食、蜕变和所处植物；及时清除饲养容器中的腐败物。"]},{"title":"异常先看这里","items":["大量向外爬先查过热、积水和过量投料，暂停加料再调整。"]},{"title":"检查提醒","items":["蜕皮、化蛹或羽化前后减少触碰；变化当天拍照记录，而非按固定天数催促。"]}],"cautions":["不能可靠识别、有毒或有蜇伤风险的种类以远距离观察为主；不跨地区释放饲养个体。"],"sources":[{"title":"RHS · Wildlife in gardens","url":"https://www.rhs.org.uk/wildlife/in-gardens"}]}'::jsonb, '{"overview":"Distinguish soil observation from composting species rather than using any worm in a scraps bin.","parameters":[],"cycle":null,"sections":[{"title":"Start here","items":["Confirm composting species and prepare loose moist bedding in a shaded ventilated site.","Photograph identifying features, host plant, and date; establish the organism and life stage first."]},{"title":"Routine care","items":["Feed small zones based on previous consumption; avoid overhandling and waterlogging.","Use brief observation instead of repeated disturbance; log feeding, molts, and host plants and remove decaying material from kept enclosures."]},{"title":"If something changes","items":["For mass escape, check heat, flooding, and overfeeding and pause additions before adjustment."]},{"title":"When to check","items":["Minimize handling around molts, pupation, and emergence; record the actual change rather than forcing a calendar."]}],"cautions":["Observe unidentified, venomous, or stinging organisms from a distance; do not release captive individuals in other regions."],"sources":[{"title":"RHS · Wildlife in gardens","url":"https://www.rhs.org.uk/wildlife/in-gardens"}]}'::jsonb),
  ('insect_fish', 'preset', '米虾', '{"overview":"重视水体稳定、躲藏与少量投喂，不只把它当清藻工具。","parameters":[],"cycle":null,"sections":[{"title":"开始前与操作","items":["确认具体虾种，准备遮蔽物并保护过滤进水口，避免幼虾卷入。","购买前确认准确种名、淡水或海水及是否需要陆地区；准备可独立观察的空间。"]},{"title":"日常照护与维护","items":["用投喂点观察残饵与活动，蜕壳后减少翻动躲藏物。","观察活动、摄食和躲藏点，清走剩食；更换水或添加药剂前先核对对该物种是否适用。"]},{"title":"异常先看这里","items":["多只同时乱游或不动时先查水质、近期换水与添加物，不先补不明矿物。"]},{"title":"检查提醒","items":["新入缸、蜕壳或同伴数量变化后增加巡查，记录日期和所做调整。"]}],"cautions":["不要把清洁缸壁或吃残渣理解为不需要喂养，也不要放生或倾倒活体到自然水体。"],"sources":[{"title":"OATA · Freshwater aquarium care","url":"https://ornamentalfish.org/what-we-do/advice-information/care-sheets/caresheets-tropical-freshwater-fish/how-to-set-up-and-look-after-a-freshwater-tank-aquarium/"}]}'::jsonb, '{"overview":"Prioritize stable water, cover, and measured feeding, not just algae cleaning.","parameters":[],"cycle":null,"sections":[{"title":"Start here","items":["Identify the shrimp and protect filter intakes so juveniles are not drawn in.","Confirm the species, freshwater/marine requirements, and any land area before purchase; prepare a separate observation space."]},{"title":"Routine care","items":["Use a feeding spot to monitor leftovers and avoid moving hides after molts.","Check activity, feeding, and hiding places and remove leftovers; verify species suitability before water additives or medication."]},{"title":"If something changes","items":["For several erratic or inactive shrimp, check water, recent changes, and additives before adding minerals."]},{"title":"When to check","items":["Increase checks after introduction, molts, or changes in companions; record dates and adjustments."]}],"cautions":["Grazing algae or scraps does not mean no feeding is needed; never release animals into natural water."],"sources":[{"title":"OATA · Freshwater aquarium care","url":"https://ornamentalfish.org/what-we-do/advice-information/care-sheets/caresheets-tropical-freshwater-fish/how-to-set-up-and-look-after-a-freshwater-tank-aquarium/"}]}'::jsonb),
  ('insect_fish', 'preset', '斑鸠', '{"overview":"在原地观察停栖、饮水和育雏，尽量少改变巢附近环境。","parameters":[],"cycle":null,"sections":[{"title":"开始前与操作","items":["选择遮蔽观察位置，留开地面取食区与巢的通道。","在原处选固定观察点，不抓捕、不搬巢，也不为了照片驱赶动物。"]},{"title":"日常照护与维护","items":["记录配对与往返行为，控制宠物接近，避免频繁走到巢边。","记录时间、天气、数量与行为；保持观察距离，减少夜灯、噪声和宠物追逐。"]},{"title":"异常先看这里","items":["亲鸟短时离巢并不证明弃巢，先拉开距离观察。"]},{"title":"检查提醒","items":["繁殖或育幼期减少靠近；受伤个体先联系当地野生动物救助机构。"]}],"cautions":["不要把暂时停留或幼鸟离巢当作被遗弃；不强行喂水、喂奶或饲喂人类饭菜。"],"sources":[{"title":"RHS · Wildlife in gardens","url":"https://www.rhs.org.uk/wildlife/in-gardens"},{"title":"Cornell Lab · Window collisions and injured birds","url":"https://www.allaboutbirds.org/news/why-birds-hit-windows-and-how-you-can-help-prevent-it/"}]}'::jsonb, '{"overview":"Observe perching, water use, and rearing in place with minimal nest-area changes.","parameters":[],"cycle":null,"sections":[{"title":"Start here","items":["Use a screened observation position and keep ground-feeding and nest routes clear.","Choose a fixed observation point in place; do not capture, move nests, or drive animals for a photo."]},{"title":"Routine care","items":["Log pairing and visits while keeping pets away and avoiding repeated nest approaches.","Log time, weather, number, and behavior; keep distance and reduce night lighting, noise, and pet chasing."]},{"title":"If something changes","items":["A short parental absence is not proof of abandonment; back away and observe."]},{"title":"When to check","items":["Increase distance during nesting or rearing; contact a local wildlife rehabilitator for injured animals."]}],"cautions":["Resting or fledging is not automatically abandonment; do not force water, milk, or human meals."],"sources":[{"title":"RHS · Wildlife in gardens","url":"https://www.rhs.org.uk/wildlife/in-gardens"},{"title":"Cornell Lab · Window collisions and injured birds","url":"https://www.allaboutbirds.org/news/why-birds-hit-windows-and-how-you-can-help-prevent-it/"}]}'::jsonb),
  ('system', 'preset', '土壤改良', '{"overview":"先诊断，再选择改良方法。堆肥、沤肥、绿肥和排水处理解决的问题不同，不必全部做。","parameters":[{"label":"先看","value":"积水、板结、酸碱度、养分"},{"label":"记录单位","value":"一小块处理区＋一块对照区"}],"cycle":null,"sections":[{"title":"先判断问题","items":["雨后标出积水位置和退水时间；土稍干后查看表面结壳、硬层与根系。不同土质或处理历史的区域分开取样，按检测机构要求送检。","板结看“板结改良”，长期积水看“排水改良”，pH异常看“土壤酸碱调整”；不要把黄叶一律当缺肥。"]},{"title":"选择与复查","items":["有机物补充可选堆肥、腐叶土、蚯蚓堆肥、绿肥种植与还田或覆盖；沤肥浸液不能替代排水和土壤结构改良。","先在试验区只改一个因素，记下材料、用量、面积和日期；下一次大雨及一轮作物生长后与对照区比较。"]}],"cautions":["疑似污染土、建筑回填土先检测；不要反复叠加肥料或来历不明的土。"],"sources":[{"title":"UMN Extension · Soil testing","url":"https://extension.umn.edu/garden-and-home/yard-and-garden/gardening-in-minnesota/soil-testing-for-lawns-and-gardens"},{"title":"UMN Extension · Soil sampling","url":"https://extension.umn.edu/about/our-stories/news/step-step-lawn-garden-soil-sampling-guide"}]}'::jsonb, '{"overview":"Diagnose first, then choose a method. Compost, steeped feeds, green manure, and drainage solve different problems.","parameters":[{"label":"First checks","value":"Waterlogging, compaction, pH, nutrients"},{"label":"Trial unit","value":"A treated patch and an untreated comparison"}],"cycle":null,"sections":[{"title":"Diagnose","items":["Map pooling and how long it lasts. When soil is workable, inspect crusts, hard layers, and roots. Sample areas with different soil or treatment histories separately, following the lab''s instructions.","Use the compaction, drainage, or pH guide for the diagnosed problem. Yellow leaves alone do not establish a nutrient shortage."]},{"title":"Choose and review","items":["For organic matter, consider compost, leafmould, worm compost, green manure, or mulch. A liquid feed cannot replace drainage or structural improvement.","Change one factor in the trial patch. Log material, amount, area, and date; compare after the next heavy rain and a crop cycle."]}],"cautions":["Test suspect or construction-fill soil before use. Avoid repeated additions of fertilizer or unknown soil."],"sources":[{"title":"UMN Extension · Soil testing","url":"https://extension.umn.edu/garden-and-home/yard-and-garden/gardening-in-minnesota/soil-testing-for-lawns-and-gardens"},{"title":"UMN Extension · Soil sampling","url":"https://extension.umn.edu/about/our-stories/news/step-step-lawn-garden-soil-sampling-guide"}]}'::jsonb),
  ('insect_fish', 'preset', '蝉', '{"overview":"适合记录羽化与鸣叫，不适合按短周期盒养催生。","parameters":[],"cycle":null,"sections":[{"title":"开始前与操作","items":["观察树干与附近地面，保留羽化时可攀附的垂直表面。","拍下成体或幼体特征、发现植物和日期，先确认对象及生活阶段。"]},{"title":"日常照护与维护","items":["发现羽化中的个体不移动，远距离拍摄并记录天气和时间。","用短时观察代替频繁翻动，记录取食、蜕变和所处植物；及时清除饲养容器中的腐败物。"]},{"title":"异常先看这里","items":["翅未展开时避免碰触；不通过剥壳或拉翅帮助羽化。"]},{"title":"检查提醒","items":["蜕皮、化蛹或羽化前后减少触碰；变化当天拍照记录，而非按固定天数催促。"]}],"cautions":["不能可靠识别、有毒或有蜇伤风险的种类以远距离观察为主；不跨地区释放饲养个体。"],"sources":[{"title":"RHS · Wildlife in gardens","url":"https://www.rhs.org.uk/wildlife/in-gardens"}]}'::jsonb, '{"overview":"Record emergence and calls instead of trying to force a short box-rearing cycle.","parameters":[],"cycle":null,"sections":[{"title":"Start here","items":["Observe trunks and nearby ground and retain vertical emergence surfaces.","Photograph identifying features, host plant, and date; establish the organism and life stage first."]},{"title":"Routine care","items":["Do not move emerging individuals; photograph from a distance and log weather/time.","Use brief observation instead of repeated disturbance; log feeding, molts, and host plants and remove decaying material from kept enclosures."]},{"title":"If something changes","items":["Avoid touching unexpanded wings and never peel cases or pull wings to assist emergence."]},{"title":"When to check","items":["Minimize handling around molts, pupation, and emergence; record the actual change rather than forcing a calendar."]}],"cautions":["Observe unidentified, venomous, or stinging organisms from a distance; do not release captive individuals in other regions."],"sources":[{"title":"RHS · Wildlife in gardens","url":"https://www.rhs.org.uk/wildlife/in-gardens"}]}'::jsonb),
  ('other', 'preset', '果酒', '{"overview":"原料、酵母、温度与排气要同时管理，不把密封水果糖罐当酿酒设备。","parameters":[],"cycle":null,"sections":[{"title":"开始前与操作","items":["用无霉变水果与明确酵母，准备适合发酵的食品容器、气锁和检测工具。","使用来源明确的发酵剂和配套工艺，称量糖或淀粉原料；气体排放装置按容器说明安装。"]},{"title":"日常照护与维护","items":["记录糖量、发酵温度及比重趋势，按工艺管理果帽和转移，减少开盖污染。","记录温度、投料和检测读数；有产气时不使用不耐压的密闭瓶，不凭气泡停止就认定可装瓶。"]},{"title":"异常先看这里","items":["持续产气时勿密闭装瓶；容器异常鼓胀、霉变或原料不明时停止操作并安全处置。"]},{"title":"检查提醒","items":["装瓶前按工艺确认发酵终点；标注含酒精、日期和储存条件，不以口尝估计酒精度。"]}],"cautions":["不提供蒸馏、增压或不明菌种试酿方法；不向未成年人提供酒类，生产与分享前核对当地要求。"],"sources":[{"title":"NCHFP · Fermentation controls","url":"https://nchfp.uga.edu/how/ferment/general-information-on-fermenting/"}]}'::jsonb, '{"overview":"Manage fruit, yeast, temperature, and venting; a sealed fruit/sugar jar is not brewing equipment.","parameters":[],"cycle":null,"sections":[{"title":"Start here","items":["Use sound fruit, defined yeast, a food-safe fermenter, airlock, and testing tools.","Use an identified starter with its validated method, weigh sugar/starch ingredients, and fit venting according to the vessel instructions."]},{"title":"Routine care","items":["Log sugar, temperature, and gravity trends and follow cap/transfer management with minimal contamination.","Log temperature, additions, and readings; never seal active fermentation in a non-pressure-rated bottle or infer bottling readiness from bubbles alone."]},{"title":"If something changes","items":["Do not seal bottles during active gas production; stop for unusual pressure, mold, or unknown ingredients."]},{"title":"When to check","items":["Confirm the method''s fermentation endpoint before bottling; label alcohol, date, and storage, and do not estimate alcohol by taste."]}],"cautions":["No distillation, pressurization, or unknown-culture methods are provided; do not supply alcohol to minors and check local requirements before production or sharing."],"sources":[{"title":"NCHFP · Fermentation controls","url":"https://nchfp.uga.edu/how/ferment/general-information-on-fermenting/"}]}'::jsonb),
  ('other', 'preset', '豆豉', '{"overview":"制曲、盐渍和成熟各有控制点，不应只凭豆子变色判断成功。","parameters":[],"cycle":null,"sections":[{"title":"开始前与操作","items":["选定有明确食品菌种与操作条件的工艺，先备称量和温度记录，再处理豆料。","开始前要有适用于该食品的明确菌种和经过验证的完整工艺；记录盐量、温度与容器，不凭口味减盐。"]},{"title":"日常照护与维护","items":["分别记下制曲与后处理时间，按原方法处理通气和盐分，不随意混入老批次。","每次检查先清洁工具；按原工艺管理液面、通气和温度，不边做边更换配方。"]},{"title":"异常先看这里","items":["非预期霉斑、污染或温度失控时停止用于食物；不把深色自动当作成熟。"]},{"title":"检查提醒","items":["关键温度、时间或配比失控就停止作为可食用成品使用；不要把补盐、再煮或挑掉霉点当作补救。"]}],"cautions":["此页用于操作前核查和过程记录，不构成家庭自然发酵配方；缺少可靠工艺时选择有资质来源的成品。"],"sources":[{"title":"NCHFP · Fermentation controls","url":"https://nchfp.uga.edu/how/ferment/general-information-on-fermenting/"},{"title":"Centre for Food Safety · Safe bean-curd preparation","url":"https://www.cfs.gov.hk/english/multimedia/multimedia_pub/multimedia_pub_fsf_239_02.html"}]}'::jsonb, '{"overview":"Culture growth, salting, and maturation have separate controls; color alone is not success.","parameters":[],"cycle":null,"sections":[{"title":"Start here","items":["Choose a process with a defined food culture and conditions and prepare weighing/temperature records before the beans.","Start only with an identified culture and a validated process for that food; record salt, temperature, and vessel, and do not reduce salt by taste."]},{"title":"Routine care","items":["Log culture and finishing stages separately and follow aeration/salt controls without mixing old batches.","Clean tools before checks and manage liquid level, aeration, and temperature according to the original method rather than changing recipes mid-process."]},{"title":"If something changes","items":["Unexpected mold, contamination, or lost temperature control means stop food use; dark color alone does not prove maturity."]},{"title":"When to check","items":["If critical time, temperature, or proportions fail, stop treating the batch as edible; extra salt, reheating, or removing mold is not a validated rescue."]}],"cautions":["This is a preparation and process-check guide, not a spontaneous-fermentation recipe; choose a reputable finished product if a reliable process is unavailable."],"sources":[{"title":"NCHFP · Fermentation controls","url":"https://nchfp.uga.edu/how/ferment/general-information-on-fermenting/"},{"title":"Centre for Food Safety · Safe bean-curd preparation","url":"https://www.cfs.gov.hk/english/multimedia/multimedia_pub/multimedia_pub_fsf_239_02.html"}]}'::jsonb),
  ('system', 'preset', '堆肥箱', '{"overview":"让投料、翻拌和取熟料都做得到，而不是只有一个封闭桶。","parameters":[],"cycle":null,"sections":[{"title":"开始前与操作","items":["选择可清理、通风又不积水的位置，试着用工具伸到箱底；备一处熟化空间。","把干叶、碎纸板等干料与果蔬残渣分开放；家庭冷堆先不放肉、油脂、宠物粪便和病株。"]},{"title":"日常照护与维护","items":["投料口和边角盖好干料，检查通气孔有无堵塞和小动物进入。","翻看内部而不只看表面：湿润但不滴水，结块就打散；新增厨余后盖干料。"]},{"title":"异常先看这里","items":["底部积液、箱内发臭时先减湿料、疏通并翻松；不把渗出液当作可直接浇叶的肥水。"]},{"title":"检查提醒","items":["每次投料查湿度和气味；停止投料后另留熟化期，土腥味、疏松、原料难辨时再检查是否可用。"]}],"cautions":["不升温不等于失败；未经验证的家庭堆肥不能保证杀死病原或杂草种子。"],"sources":[{"title":"EPA · Composting at home","url":"https://www.epa.gov/recycle/composting-home"}]}'::jsonb, '{"overview":"Allow loading, mixing, and finished-compost access, not just a sealed container.","parameters":[],"cycle":null,"sections":[{"title":"Start here","items":["Choose a cleanable, ventilated, non-waterlogged site and test tool access to the base; reserve curing space.","Keep dry leaves/cardboard and fruit/vegetable scraps separately; leave meat, fats, pet waste, and diseased plants out of a simple home pile."]},{"title":"Routine care","items":["Cover scraps at openings/edges and check ventilation blockage and animal entry.","Check the center, not just the surface: keep it moist but not dripping, break clumps, and cover new scraps with dry material."]},{"title":"If something changes","items":["For pooled liquid and odor, reduce wet additions, clear and loosen; do not assume leachate is safe foliar fertilizer."]},{"title":"When to check","items":["Check moisture and odor at each addition; allow a separate curing period and inspect texture, earthy smell, and remaining scraps before use."]}],"cautions":["A cool pile is not automatically a failure; an unverified home process cannot guarantee destruction of pathogens or weed seeds."],"sources":[{"title":"EPA · Composting at home","url":"https://www.epa.gov/recycle/composting-home"}]}'::jsonb),
  ('insect_fish', 'preset', '鹅', '{"overview":"规划放牧活动、补饲和安全回舍，别只依赖草地自给。","parameters":[],"cycle":null,"sections":[{"title":"开始前与操作","items":["确认草地无危险杂物或有毒植物，设置清水、遮阴和夜间舍。","按年龄选择完整饲料，设置每只都能到达的饮水和进食位置；新来个体先单独观察。"]},{"title":"日常照护与维护","items":["观察食草与补饲情况，查看脚部和群体追赶，保持行走通道安全。","每天查水和采食，移走湿垫料；黄昏清点并关好舍门，记录产蛋和异常粪便。"]},{"title":"异常先看这里","items":["生长慢、体况下降或持续争斗时重新核对日粮、空间与健康状态。"]},{"title":"检查提醒","items":["高温、换羽、转群和饲料变更时增加巡查；准备离家期间的照护交接。"]}],"cautions":["呼吸困难、多只同时发病或突然死亡应及时联系兽医；不凭网上配方给整群用药。"],"sources":[{"title":"UMN Extension · Raising chickens","url":"https://extension.umn.edu/agriculture/animals-and-livestock/poultry/raising-chickens-for-eggs"}]}'::jsonb, '{"overview":"Plan grazing, supplementary feed, and safe housing rather than relying on grass alone.","parameters":[],"cycle":null,"sections":[{"title":"Start here","items":["Check pasture for hazards/toxic plants and provide water, shade, and night shelter.","Use a complete age-appropriate feed, accessible feeding/watering points, and separate observation for newcomers."]},{"title":"Routine care","items":["Observe grazing/feed intake, feet, and chasing and keep walking routes safe.","Check water and feed daily, remove wet bedding, count and secure birds at dusk, and log eggs and unusual droppings."]},{"title":"If something changes","items":["For poor growth, condition loss, or conflict, review ration, space, and health."]},{"title":"When to check","items":["Increase checks during heat, molting, flock moves, and feed changes; arrange care before travel."]}],"cautions":["Breathing difficulty, multiple sick birds, or sudden deaths need veterinary help; do not medicate a flock from an unverified recipe."],"sources":[{"title":"UMN Extension · Raising chickens","url":"https://extension.umn.edu/agriculture/animals-and-livestock/poultry/raising-chickens-for-eggs"}]}'::jsonb),
  ('insect_fish', 'preset', '甲虫', '{"overview":"甲虫与幼虫食性可能不同，先确认种类和阶段。","parameters":[],"cycle":null,"sections":[{"title":"开始前与操作","items":["记录发现的植物、木材或土壤，辨种后再决定寄主、基质和空间。","拍下成体或幼体特征、发现植物和日期，先确认对象及生活阶段。"]},{"title":"日常照护与维护","items":["观察取食与钻藏，保留适合的原观察环境，不频繁挖开幼虫。","用短时观察代替频繁翻动，记录取食、蜕变和所处植物；及时清除饲养容器中的腐败物。"]},{"title":"异常先看这里","items":["蛀孔或叶片损伤先拍照辨别对象，不能看见甲虫就一概喷药。"]},{"title":"检查提醒","items":["蜕皮、化蛹或羽化前后减少触碰；变化当天拍照记录，而非按固定天数催促。"]}],"cautions":["不能可靠识别、有毒或有蜇伤风险的种类以远距离观察为主；不跨地区释放饲养个体。"],"sources":[{"title":"RHS · Wildlife in gardens","url":"https://www.rhs.org.uk/wildlife/in-gardens"}]}'::jsonb, '{"overview":"Adult beetles and larvae may have different diets; identify species and stage.","parameters":[],"cycle":null,"sections":[{"title":"Start here","items":["Record the plant, wood, or soil and confirm host, substrate, and space after identification.","Photograph identifying features, host plant, and date; establish the organism and life stage first."]},{"title":"Routine care","items":["Observe feeding and hiding without repeatedly excavating larvae.","Use brief observation instead of repeated disturbance; log feeding, molts, and host plants and remove decaying material from kept enclosures."]},{"title":"If something changes","items":["Photograph and identify holes or leaf damage before treating all beetles as pests."]},{"title":"When to check","items":["Minimize handling around molts, pupation, and emergence; record the actual change rather than forcing a calendar."]}],"cautions":["Observe unidentified, venomous, or stinging organisms from a distance; do not release captive individuals in other regions."],"sources":[{"title":"RHS · Wildlife in gardens","url":"https://www.rhs.org.uk/wildlife/in-gardens"}]}'::jsonb),
  ('insect_fish', 'preset', '宫廷草', '{"overview":"茎草要分枝种植，修剪后用健康顶芽更新稀疏处。","parameters":[{"label":"光照","value":"中至强光"},{"label":"参考水温范围","value":"18–28℃","note":"资料所列范围，并非全程最适温度。"},{"label":"生长方式","value":"茎草"},{"label":"难度","value":"中等"}],"cycle":null,"sections":[{"title":"开始前与操作","items":["除去要埋入底床处的叶片，茎之间留间隙，避免整束插入。","保留购买标签或学名；清除运输包装，先把种植位置和入缸状态拍下来。"]},{"title":"日常照护与维护","items":["逐次剪高、补低，保留侧芽，防止上层把下层完全遮住。","每周同角度拍新芽和老叶；修剪后捞净碎叶，记下光照、施肥或换水的单项变化。"]},{"title":"异常先看这里","items":["底部掉叶先查遮光和过密，重新分株比不断加高灯强更可控。"]},{"title":"检查提醒","items":["刚定植时先检查是否松脱；修剪、移动灯具或换水后，连续观察新叶而不只看旧叶。"]}],"cautions":["俗名可能对应不同物种；不要凭名称套用统一水温。修剪物不要丢进河道或户外水体。","水温参考品种：Rotala rotundifolia，18–28℃。这是资料所列范围，并非整段都是最适温度；同名水草可能不是同一品种，不要据此骤升骤降水温。"],"sources":[{"title":"Tropica · Planting in the aquarium","url":"https://tropica.com/en/guide/get-the-right-start/planting/"},{"title":"Dennerle — Rotala rotundifolia","url":"https://dennerleplants.com/en/plants/plantdetails/Rotalarotundifolia(915)/30724"}]}'::jsonb, '{"overview":"Space stems and use healthy tops to renew sparse growth.","parameters":[{"label":"Light","value":"Medium to high"},{"label":"Reference water-temperature range","value":"18–28°C","note":"Published range, not an optimum throughout."},{"label":"Growth form","value":"Stem plant"},{"label":"Difficulty","value":"Moderate"}],"cycle":null,"sections":[{"title":"Start here","items":["Remove leaves on the buried portion and plant stems with gaps rather than as a bundle.","Keep the label or scientific name, remove transport packaging, and photograph the planting position and arrival condition."]},{"title":"Routine care","items":["Trim tall stems gradually and retain side shoots so the top does not shade the entire base.","Photograph new and old leaves weekly; remove pruning debris and log individual changes in light, nutrients, or water."]},{"title":"If something changes","items":["For lower-leaf loss, check shading and crowding before simply increasing light."]},{"title":"When to check","items":["Check for loose plants after planting; following pruning, light changes, or water changes, track new growth as well as old leaves."]}],"cautions":["Trade names can cover different species; do not assume one temperature from a name. Keep trimmings out of natural waterways.","Temperature reference: Rotala rotundifolia, 18–28°C. This is a published range, not an ideal setpoint or permission for sudden temperature changes; other species sold under this common name may differ."],"sources":[{"title":"Tropica · Planting in the aquarium","url":"https://tropica.com/en/guide/get-the-right-start/planting/"},{"title":"Dennerle — Rotala rotundifolia","url":"https://dennerleplants.com/en/plants/plantdetails/Rotalarotundifolia(915)/30724"}]}'::jsonb),
  ('insect_fish', 'preset', '洋葱螺', '{"overview":"保留可刮食的表面，但不要以长藻代替整体水质管理。","parameters":[],"cycle":null,"sections":[{"title":"开始前与操作","items":["确认准确品种，在稳定水体中安置，避免与会咬螺的同伴混养。","购买前确认准确种名、淡水或海水及是否需要陆地区；准备可独立观察的空间。"]},{"title":"日常照护与维护","items":["清洁时保留部分适合刮食的表面，记录活动和壳体变化。","观察活动、摄食和躲藏点，清走剩食；更换水或添加药剂前先核对对该物种是否适用。"]},{"title":"异常先看这里","items":["频繁爬出或附着乏力时先查水质与添加剂记录。"]},{"title":"检查提醒","items":["新入缸、蜕壳或同伴数量变化后增加巡查，记录日期和所做调整。"]}],"cautions":["不要把清洁缸壁或吃残渣理解为不需要喂养，也不要放生或倾倒活体到自然水体。"],"sources":[{"title":"OATA · Freshwater aquarium care","url":"https://ornamentalfish.org/what-we-do/advice-information/care-sheets/caresheets-tropical-freshwater-fish/how-to-set-up-and-look-after-a-freshwater-tank-aquarium/"}]}'::jsonb, '{"overview":"Retain grazing surfaces without using algae as a substitute for water management.","parameters":[],"cycle":null,"sections":[{"title":"Start here","items":["Identify the species and avoid companions that bite snails.","Confirm the species, freshwater/marine requirements, and any land area before purchase; prepare a separate observation space."]},{"title":"Routine care","items":["Retain some suitable grazing surfaces during cleaning and track activity/shell condition.","Check activity, feeding, and hiding places and remove leftovers; verify species suitability before water additives or medication."]},{"title":"If something changes","items":["For repeated exits or weak attachment, check water and additive history first."]},{"title":"When to check","items":["Increase checks after introduction, molts, or changes in companions; record dates and adjustments."]}],"cautions":["Grazing algae or scraps does not mean no feeding is needed; never release animals into natural water."],"sources":[{"title":"OATA · Freshwater aquarium care","url":"https://ornamentalfish.org/what-we-do/advice-information/care-sheets/caresheets-tropical-freshwater-fish/how-to-set-up-and-look-after-a-freshwater-tank-aquarium/"}]}'::jsonb),
  ('other', 'preset', '干制', '{"overview":"以下分开做果干、肉干、熟鱼干和熟虾干。烘干机空气温度不等于食物中心温度，气候潮湿时优先用可控温、持续排湿的设备。","parameters":[{"label":"果片烘干空气温度","value":"约57–60℃；苹果片通常6–12小时"},{"label":"肉干烘干空气温度","value":"约63–68℃；先完成肉类加热步骤"},{"label":"熟鱼／熟虾示例","value":"约63℃；鱼碎4–6小时、虾粒约6小时起检查"}],"cycle":null,"sections":[{"title":"果干：以苹果片为例","items":["洗净、去核并切成均匀薄片，单层铺开不叠压。有表面水分时可先约63℃烘1小时，再调至57–60℃；总时长通常6–12小时，厚片和潮湿天气更久。","抽取最厚片冷却后对折：内部无可见湿点、无汁液挤出。冷却再包装；先少量装透明容器观察回潮，出现冷凝水应重新干燥，长霉则丢弃。"]},{"title":"肉干：先加热，再干燥","items":["以瘦牛肉条为例，去明显脂肪、切不超过约6mm厚；调味腌制放冷藏，不在室温过夜。按可靠肉干工艺先把中心加热至至少71.1℃，禽肉至少74℃，用温度计确认。","随后立即转入已预热的烘干设备，空气温度约63–68℃，单层排开持续通风；按工艺检查到内部干透。柔软或变硬都不能替代前面的安全加热步骤。"]},{"title":"鱼干：熟鱼碎示例","items":["选新鲜、较低脂的鱼，冷藏解冻、去骨；先煮熟或烤熟并确认中心至少63℃。把熟鱼分成小碎片单层摊开，约63℃烘4–6小时起检查，干后应易掰碎。","这是熟鱼碎的烘干示例，不适用于整条生鱼、低温风干或熏鱼。盐腌不能代替杀菌或杀寄生虫；冷却分装后冷冻保存更稳妥。"]},{"title":"虾干：熟虾粒示例","items":["使用正规熟制、去壳冻虾，冷藏解冻并沥水；每只中等虾切4–5小段，单层铺开，约63℃烘干，约6小时起检查。最大一块切开后内部不应有潮湿中心。","本示例不把生虾直接低温烘干。成品冷却、分装冷冻；取用只解冻当次需要的量，记录开包日期并避免反复回潮。"]}],"cautions":["果品室外晾晒只适合连续晴朗、干燥且有风的天气，通常需约30℃以上、相对湿度低于60%；防虫网、夜间露水和空气污染也要考虑。阴雨、潮湿、闷热不等于适合晒干，肉鱼虾不要按果干方式露天晒。","时长只是开始检查的参考，不保证杀菌或常温保质。家庭没有验证水分活度、包装与工艺时，肉鱼虾干按冷藏短期食物管理、长期冷冻，不用真空包装推定可常温存放。"],"sources":[{"title":"Penn State Extension · Dried apples","url":"https://extension.psu.edu/dried-apples/"},{"title":"MSU Extension · Drying fruits（气候与回潮检查）","url":"https://extension-store.montana.edu/montguides/drying-fruits"},{"title":"PNW Extension · Making jerky at home safely","url":"https://extension.oregonstate.edu/catalog/pnw-632-making-jerky-home-safely"},{"title":"FDA · Safe seafood cooking and handling","url":"https://www.fda.gov/food/buy-store-serve-safe-food/selecting-and-serving-fresh-and-frozen-seafood-safely"},{"title":"Backpacking Chef · Cooked-fish drying example","url":"https://www.backpackingchef.com/dehydrating-fish.html"},{"title":"Backpacking Chef · Precooked-shrimp drying example","url":"https://www.backpackingchef.com/dehydrating-meat.html"}]}'::jsonb, '{"overview":"Use separate methods for fruit, jerky, cooked fish and cooked shrimp. Dryer-air temperature is not food-core temperature; humid climates call for controlled heat and continuous moisture removal.","parameters":[{"label":"Fruit dryer-air temperature","value":"About 57–60°C; apple slices often need 6–12 hours"},{"label":"Jerky dryer-air temperature","value":"About 63–68°C, after the meat-heating step"},{"label":"Cooked fish / shrimp examples","value":"About 63°C; inspect fish flakes at 4–6 hours, shrimp pieces around 6 hours"}],"cycle":null,"sections":[{"title":"Fruit: apple-slice example","items":["Wash, core and slice evenly; lay out a single non-overlapping layer. With surface moisture, start around 63°C for one hour, then 57–60°C. Total drying often takes 6–12 hours, longer for thicker or wetter loads.","Cool and bend the thickest test pieces: there should be no visible wet centers or expressed juice. Pack after cooling and monitor for moisture; re-dry condensation-affected fruit, but discard moldy fruit."]},{"title":"Jerky: heat before drying","items":["For lean beef strips, trim fat and cut no thicker than about 6 mm; marinate refrigerated. Under a tested jerky process, first heat the center to at least 71.1°C for beef or 74°C for poultry, checked with a thermometer.","Immediately transfer to the preheated dryer at about 63–68°C, with strips spaced for airflow. Check dryness using the chosen method; softness or hardness cannot replace the prior heating step."]},{"title":"Fish: cooked flakes","items":["Choose fresh lower-fat fish, thaw refrigerated and remove bones. Cook first to at least 63°C internally, then flake and spread in one layer. Dry around 63°C and check from 4–6 hours for a brittle texture.","This cooked-flake example does not cover whole raw fish, low-temperature air drying or smoking. Brining is not a pathogen or parasite treatment; portion and freeze after cooling."]},{"title":"Shrimp: precooked pieces","items":["Use commercially precooked peeled shrimp, thaw refrigerated and drain. Cut medium shrimp into 4–5 pieces, spread in one layer and dry around 63°C; check around six hours, including the largest cut piece for a wet center.","Do not apply this example to raw shrimp placed directly in a low-temperature dryer. Cool, portion and freeze; thaw only what is needed and prevent repeated moisture exposure."]}],"cautions":["Outdoor fruit drying needs reliably hot, dry, breezy conditions, typically around 30°C or warmer with relative humidity below 60%, plus protection from insects, dew and pollution. Do not sun-dry meat or seafood using fruit methods.","Times indicate when to inspect, not sterilization or shelf stability. Without validated water activity, packaging and processing, keep dried meat/seafood refrigerated briefly or frozen; vacuum packing does not establish room-temperature safety."],"sources":[{"title":"Penn State Extension · Dried apples","url":"https://extension.psu.edu/dried-apples/"},{"title":"MSU Extension · Drying fruits（气候与回潮检查）","url":"https://extension-store.montana.edu/montguides/drying-fruits"},{"title":"PNW Extension · Making jerky at home safely","url":"https://extension.oregonstate.edu/catalog/pnw-632-making-jerky-home-safely"},{"title":"FDA · Safe seafood cooking and handling","url":"https://www.fda.gov/food/buy-store-serve-safe-food/selecting-and-serving-fresh-and-frozen-seafood-safely"},{"title":"Backpacking Chef · Cooked-fish drying example","url":"https://www.backpackingchef.com/dehydrating-fish.html"},{"title":"Backpacking Chef · Precooked-shrimp drying example","url":"https://www.backpackingchef.com/dehydrating-meat.html"}]}'::jsonb),
  ('system', 'preset', '蓄水设施', '{"overview":"关注满水重量、遮光防污染和彻底排空能力。","parameters":[],"cycle":null,"sections":[{"title":"开始前与操作","items":["装水前核对基础承重，检查盖、排空阀、溢流管与水位标识。","画出水源、阀门、过滤、出水和溢流的简图，标出能关闭和清洗的位置。"]},{"title":"日常照护与维护","items":["对照正常水位查不明下降，检查连接处渗漏；保留最近清洗日期。","先用清水试运行，沿途查看漏水、堵塞和回流；记下正常水位或流量作为对照。"]},{"title":"异常先看这里","items":["底座下沉、壁面裂纹或管件持续滴漏时停止补水并排查。"]},{"title":"检查提醒","items":["启用、清洗和长时间停用后都试运行；大雨、冰冻、停电后检查溢流和连接。"]}],"cautions":["储水不是饮用水处理；水电作业先断电，水箱和池面需防儿童及动物跌入。"],"sources":[{"title":"RHS · Collecting and storing water","url":"https://www.rhs.org.uk/garden-jobs/water-collecting-storing-and-using"}]}'::jsonb, '{"overview":"Plan for full weight, contamination protection, and complete draining.","parameters":[],"cycle":null,"sections":[{"title":"Start here","items":["Check the foundation rating, lid, drain valve, overflow, and level markings before filling.","Sketch the supply, valves, filters, outlets, and overflow; mark accessible shutoffs and cleaning points."]},{"title":"Routine care","items":["Compare normal levels for unexplained loss, inspect leaks, and retain the last cleaning date.","Test with clean water, check leaks, blockages, and backflow, and record normal level or flow for comparison."]},{"title":"If something changes","items":["Stop filling if the base settles, walls crack, or fittings continually leak."]},{"title":"When to check","items":["Test after commissioning, cleaning, and long shutdowns; check overflow and connections after rain, frost, or power loss."]}],"cautions":["Storage is not drinking-water treatment; isolate power for wet maintenance and protect tanks/ponds from falls by children and animals."],"sources":[{"title":"RHS · Collecting and storing water","url":"https://www.rhs.org.uk/garden-jobs/water-collecting-storing-and-using"}]}'::jsonb),
  ('insect_fish', 'preset', '牛毛毡', '{"overview":"用小丛扩展前景草坪，保留根部之间的生长空间。","parameters":[{"label":"光照","value":"中至强光"},{"label":"参考水温范围","value":"12–26℃","note":"资料所列范围，并非全程最适温度。"},{"label":"生长方式","value":"前景铺地"},{"label":"难度","value":"中等"}],"cycle":null,"sections":[{"title":"开始前与操作","items":["分丛栽入底床，基部不要整团压埋；把种植范围拍下来。","保留购买标签或学名；清除运输包装，先把种植位置和入缸状态拍下来。"]},{"title":"日常照护与维护","items":["清理枯叶和缠在草丛里的残饵，观察新匍匐生长是否外扩。","每周同角度拍新芽和老叶；修剪后捞净碎叶，记下光照、施肥或换水的单项变化。"]},{"title":"异常先看这里","items":["中间黄、边缘绿时查过密和积污，先疏开再观察。"]},{"title":"检查提醒","items":["刚定植时先检查是否松脱；修剪、移动灯具或换水后，连续观察新叶而不只看旧叶。"]}],"cautions":["俗名可能对应不同物种；不要凭名称套用统一水温。修剪物不要丢进河道或户外水体。","水温参考品种：Eleocharis pusilla，12–26℃。这是资料所列范围，并非整段都是最适温度；同名水草可能不是同一品种，不要据此骤升骤降水温。"],"sources":[{"title":"Tropica · Planting in the aquarium","url":"https://tropica.com/en/guide/get-the-right-start/planting/"},{"title":"Dennerle — Eleocharis pusilla","url":"https://dennerleplants.co.uk/products/eleocharis-pusilla"}]}'::jsonb, '{"overview":"Plant small hairgrass clumps with room for roots to spread.","parameters":[{"label":"Light","value":"Medium to high"},{"label":"Reference water-temperature range","value":"12–26°C","note":"Published range, not an optimum throughout."},{"label":"Growth form","value":"Carpet"},{"label":"Difficulty","value":"Moderate"}],"cycle":null,"sections":[{"title":"Start here","items":["Set divided clumps without burying the entire base and photograph the planted area.","Keep the label or scientific name, remove transport packaging, and photograph the planting position and arrival condition."]},{"title":"Routine care","items":["Remove dead blades and trapped food and track outward runners.","Photograph new and old leaves weekly; remove pruning debris and log individual changes in light, nutrients, or water."]},{"title":"If something changes","items":["If centers yellow but edges remain green, check crowding and debris before further changes."]},{"title":"When to check","items":["Check for loose plants after planting; following pruning, light changes, or water changes, track new growth as well as old leaves."]}],"cautions":["Trade names can cover different species; do not assume one temperature from a name. Keep trimmings out of natural waterways.","Temperature reference: Eleocharis pusilla, 12–26°C. This is a published range, not an ideal setpoint or permission for sudden temperature changes; other species sold under this common name may differ."],"sources":[{"title":"Tropica · Planting in the aquarium","url":"https://tropica.com/en/guide/get-the-right-start/planting/"},{"title":"Dennerle — Eleocharis pusilla","url":"https://dennerleplants.co.uk/products/eleocharis-pusilla"}]}'::jsonb),
  ('insect_fish', 'preset', '喜鹊', '{"overview":"观察筑巢、搬运和领地活动，避免用长期投喂改变行为。","parameters":[],"cycle":null,"sections":[{"title":"开始前与操作","items":["远距离确认巢树和飞行路线，不攀树查看或搬动巢材。","在原处选固定观察点，不抓捕、不搬巢，也不为了照片驱赶动物。"]},{"title":"日常照护与维护","items":["记录巢周活动及季节变化，收好散落塑料绳和危险线材。","记录时间、天气、数量与行为；保持观察距离，减少夜灯、噪声和宠物追逐。"]},{"title":"异常先看这里","items":["育雏期护巢时绕行，不驱赶或逗弄，必要时请专业人员协助。"]},{"title":"检查提醒","items":["繁殖或育幼期减少靠近；受伤个体先联系当地野生动物救助机构。"]}],"cautions":["不要把暂时停留或幼鸟离巢当作被遗弃；不强行喂水、喂奶或饲喂人类饭菜。"],"sources":[{"title":"RHS · Wildlife in gardens","url":"https://www.rhs.org.uk/wildlife/in-gardens"},{"title":"Cornell Lab · Window collisions and injured birds","url":"https://www.allaboutbirds.org/news/why-birds-hit-windows-and-how-you-can-help-prevent-it/"}]}'::jsonb, '{"overview":"Observe nests, carrying, and territory without persistent feeding that changes behavior.","parameters":[],"cycle":null,"sections":[{"title":"Start here","items":["Identify nest trees/routes from a distance without climbing or moving nest material.","Choose a fixed observation point in place; do not capture, move nests, or drive animals for a photo."]},{"title":"Routine care","items":["Log seasonal activity and remove loose plastic strings and dangerous lines from the surroundings.","Log time, weather, number, and behavior; keep distance and reduce night lighting, noise, and pet chasing."]},{"title":"If something changes","items":["Give defending parents space and seek professional help if needed rather than provoking them."]},{"title":"When to check","items":["Increase distance during nesting or rearing; contact a local wildlife rehabilitator for injured animals."]}],"cautions":["Resting or fledging is not automatically abandonment; do not force water, milk, or human meals."],"sources":[{"title":"RHS · Wildlife in gardens","url":"https://www.rhs.org.uk/wildlife/in-gardens"},{"title":"Cornell Lab · Window collisions and injured birds","url":"https://www.allaboutbirds.org/news/why-birds-hit-windows-and-how-you-can-help-prevent-it/"}]}'::jsonb),
  ('insect_fish', 'preset', '苹果螺', '{"overview":"俗名可能混指不同螺类，先确定种类再判断繁殖与植物兼容性。","parameters":[],"cycle":null,"sections":[{"title":"开始前与操作","items":["核对来源照片和学名，检查会不会啃食栽培水草并安排数量上限。","购买前确认准确种名、淡水或海水及是否需要陆地区；准备可独立观察的空间。"]},{"title":"日常照护与维护","items":["记录新增小螺和卵，调整过量残饵而不是让数量无计划增加。","观察活动、摄食和躲藏点，清走剩食；更换水或添加药剂前先核对对该物种是否适用。"]},{"title":"异常先看这里","items":["壳面异常、反复逃离或数量暴增时分别排查水质、识别与投喂。"]},{"title":"检查提醒","items":["新入缸、蜕壳或同伴数量变化后增加巡查，记录日期和所做调整。"]}],"cautions":["不要把清洁缸壁或吃残渣理解为不需要喂养，也不要放生或倾倒活体到自然水体。"],"sources":[{"title":"OATA · Freshwater aquarium care","url":"https://ornamentalfish.org/what-we-do/advice-information/care-sheets/caresheets-tropical-freshwater-fish/how-to-set-up-and-look-after-a-freshwater-tank-aquarium/"}]}'::jsonb, '{"overview":"The trade name can cover different snails; identify before planning breeding or plants.","parameters":[],"cycle":null,"sections":[{"title":"Start here","items":["Check source photos/name, possible plant feeding, and a population plan.","Confirm the species, freshwater/marine requirements, and any land area before purchase; prepare a separate observation space."]},{"title":"Routine care","items":["Log eggs and juveniles and correct excessive leftovers rather than allowing uncontrolled growth.","Check activity, feeding, and hiding places and remove leftovers; verify species suitability before water additives or medication."]},{"title":"If something changes","items":["For shell changes, repeated escape, or a population boom, review water, identification, and feeding separately."]},{"title":"When to check","items":["Increase checks after introduction, molts, or changes in companions; record dates and adjustments."]}],"cautions":["Grazing algae or scraps does not mean no feeding is needed; never release animals into natural water."],"sources":[{"title":"OATA · Freshwater aquarium care","url":"https://ornamentalfish.org/what-we-do/advice-information/care-sheets/caresheets-tropical-freshwater-fish/how-to-set-up-and-look-after-a-freshwater-tank-aquarium/"}]}'::jsonb),
  ('insect_fish', 'preset', '树蛙', '{"overview":"树栖种需要稳定攀附与通风，不能只给一盆水。","parameters":[],"cycle":null,"sections":[{"title":"开始前与操作","items":["确认物种后安装稳固枝叶、躲藏和合适浅水区，盖好通风防逃网。","先确认生活阶段和物种；分别检查水区、陆区与出水坡道，不能只按“蛙类”设置。"]},{"title":"日常照护与维护","items":["观察能否稳稳攀附，清理叶面残饵，检查喷湿后是否持续闷湿。","少接触皮肤，清走残饵；每天从外部观察姿态、体表和水区状态。"]},{"title":"异常先看这里","items":["频繁滑落、腹部异常或皮肤损伤先检查表面和环境，并咨询异宠兽医。"]},{"title":"检查提醒","items":["变态、季节变化和拒食时复核栖息条件；异常记录照片供专业人员判断。"]}],"cautions":["不抓野生个体回家混养；持续失衡、皮肤病变或明显消瘦应咨询异宠兽医。"],"sources":[{"title":"RSPCA · Caring for exotic pets","url":"https://www.rspca.org.uk/adviceandwelfare/pets/other"}]}'::jsonb, '{"overview":"Arboreal frogs need secure climbing and airflow, not just a bowl of water.","parameters":[],"cycle":null,"sections":[{"title":"Start here","items":["After identification, provide stable branches, cover, an appropriate shallow water area, and a ventilated secure lid.","Identify species and life stage; check water, land, and exit routes rather than using a single frog setup."]},{"title":"Routine care","items":["Observe grip, clear leftovers, and check that misting does not leave persistent stagnant wetness.","Minimize skin contact and remove leftovers; observe posture, skin, and water conditions from outside each day."]},{"title":"If something changes","items":["Repeated slipping or skin/body abnormalities need surface/environment checks and exotics-vet advice."]},{"title":"When to check","items":["Review conditions at metamorphosis, seasonal changes, or appetite loss; photograph abnormalities for professional advice."]}],"cautions":["Do not collect wild animals for mixed housing; persistent imbalance, skin lesions, or weight loss needs an exotics vet."],"sources":[{"title":"RSPCA · Caring for exotic pets","url":"https://www.rspca.org.uk/adviceandwelfare/pets/other"}]}'::jsonb),
  ('insect_fish', 'preset', '蛞蝓', '{"overview":"无壳体保护，更适合在原处观察夜间活动与湿度关系。","parameters":[],"cycle":null,"sections":[{"title":"开始前与操作","items":["选择落叶或木片附近固定观察点，不为了拍照移到干热地面。","先在原处观察，若饲养需确认来源与物种；准备通风、防逃逸且无农药残留的容器。"]},{"title":"日常照护与维护","items":["记录雨后与干燥时的活动和取食痕，保留其躲藏处。","每天移走变质食物并检查角落积水、霉点和盖子；洗手后再接触用具。"]},{"title":"异常先看这里","items":["发现贴近幼苗的啃食时先确认对象，可用隔离和移走躲藏杂物保护苗，不直接撒盐。"]},{"title":"检查提醒","items":["高温、干燥或更换基质后查看活动变化；保留湿度差异，不让整个容器积水。"]}],"cautions":["不徒手接触黏液后揉眼或拿食物；野采个体不要混入家庭饲养群。"],"sources":[{"title":"RHS · Wildlife in gardens","url":"https://www.rhs.org.uk/wildlife/in-gardens"}]}'::jsonb, '{"overview":"With no shell protection, observe slug activity and moisture in place.","parameters":[],"cycle":null,"sections":[{"title":"Start here","items":["Use a fixed spot near leaf litter or wood and avoid moving slugs onto hot dry surfaces.","Prefer observation in place; for kept animals confirm species/source and use a ventilated, escape-resistant, pesticide-free enclosure."]},{"title":"Routine care","items":["Log activity and feeding traces in wet/dry weather and retain shelter.","Remove spoiled food and check corners for pooling, mold, and lid gaps daily; wash hands when handling equipment."]},{"title":"If something changes","items":["For seedling damage, verify the cause and protect plants with barriers or shelter management, not salt."]},{"title":"When to check","items":["Watch activity after heat, dry weather, or substrate changes; offer a moisture gradient without flooding the enclosure."]}],"cautions":["Avoid touching eyes or food after contact with mucus; do not mix wild-caught individuals into kept groups."],"sources":[{"title":"RHS · Wildlife in gardens","url":"https://www.rhs.org.uk/wildlife/in-gardens"}]}'::jsonb),
  ('system', 'preset', '排水系统', '{"overview":"先看水从哪里来、在哪里停，不先挖一条无出口的沟。","parameters":[],"cycle":null,"sections":[{"title":"开始前与操作","items":["雨中或雨后画出积水线，检查已有出口；施工前核对地下管线。","画出水源、阀门、过滤、出水和溢流的简图，标出能关闭和清洗的位置。"]},{"title":"日常照护与维护","items":["清理落叶和沉沙，检查检修口；用少量清水测试是否顺畅排出。","先用清水试运行，沿途查看漏水、堵塞和回流；记下正常水位或流量作为对照。"]},{"title":"异常先看这里","items":["清完又堵先找上游泥沙来源；持续积水或倒灌请专业人员检查坡度与容量。"]},{"title":"检查提醒","items":["启用、清洗和长时间停用后都试运行；大雨、冰冻、停电后检查溢流和连接。"]}],"cautions":["储水不是饮用水处理；水电作业先断电，水箱和池面需防儿童及动物跌入。"],"sources":[{"title":"RHS · Collecting and storing water","url":"https://www.rhs.org.uk/garden-jobs/water-collecting-storing-and-using"}]}'::jsonb, '{"overview":"Map where water arrives and stalls before digging a drain without an outlet.","parameters":[],"cycle":null,"sections":[{"title":"Start here","items":["Mark pooling during/after rain and inspect existing outlets; locate buried utilities before work.","Sketch the supply, valves, filters, outlets, and overflow; mark accessible shutoffs and cleaning points."]},{"title":"Routine care","items":["Remove leaves and sediment, inspect access points, and test with a small clean-water flow.","Test with clean water, check leaks, blockages, and backflow, and record normal level or flow for comparison."]},{"title":"If something changes","items":["Repeated clogs need upstream sediment control; persistent pooling/backflow needs a professional grade and capacity check."]},{"title":"When to check","items":["Test after commissioning, cleaning, and long shutdowns; check overflow and connections after rain, frost, or power loss."]}],"cautions":["Storage is not drinking-water treatment; isolate power for wet maintenance and protect tanks/ponds from falls by children and animals."],"sources":[{"title":"RHS · Collecting and storing water","url":"https://www.rhs.org.uk/garden-jobs/water-collecting-storing-and-using"}]}'::jsonb),
  ('insect_fish', 'preset', '宝塔草', '{"overview":"分层叶片容易互相遮挡，株间留隙更方便保持形态。","parameters":[{"label":"光照","value":"中至强光"},{"label":"参考水温范围","value":"水温待确认"},{"label":"生长方式","value":"茎草"},{"label":"难度","value":"中等"}],"cycle":null,"sections":[{"title":"开始前与操作","items":["分茎定植，避免压碎层状叶片，给上部长高留空间。","保留购买标签或学名；清除运输包装，先把种植位置和入缸状态拍下来。"]},{"title":"日常照护与维护","items":["从健康节位分次修剪，及时捞出漂浮剪屑，比较下层叶片状态。","每周同角度拍新芽和老叶；修剪后捞净碎叶，记下光照、施肥或换水的单项变化。"]},{"title":"异常先看这里","items":["下层发黑或大量掉叶时查过密、积污和遮光。"]},{"title":"检查提醒","items":["刚定植时先检查是否松脱；修剪、移动灯具或换水后，连续观察新叶而不只看旧叶。"]}],"cautions":["俗名可能对应不同物种；不要凭名称套用统一水温。修剪物不要丢进河道或户外水体。"],"sources":[{"title":"Tropica · Planting in the aquarium","url":"https://tropica.com/en/guide/get-the-right-start/planting/"}]}'::jsonb, '{"overview":"Leave room around layered foliage so lower leaves are not crowded out.","parameters":[{"label":"Light","value":"Medium to high"},{"label":"Reference water-temperature range","value":"Range unverified"},{"label":"Growth form","value":"Stem plant"},{"label":"Difficulty","value":"Moderate"}],"cycle":null,"sections":[{"title":"Start here","items":["Plant stems separately without crushing whorls and leave vertical space.","Keep the label or scientific name, remove transport packaging, and photograph the planting position and arrival condition."]},{"title":"Routine care","items":["Trim healthy sections gradually, collect floating debris, and compare lower foliage.","Photograph new and old leaves weekly; remove pruning debris and log individual changes in light, nutrients, or water."]},{"title":"If something changes","items":["For dark or shedding lower leaves, inspect density, debris, and shading."]},{"title":"When to check","items":["Check for loose plants after planting; following pruning, light changes, or water changes, track new growth as well as old leaves."]}],"cautions":["Trade names can cover different species; do not assume one temperature from a name. Keep trimmings out of natural waterways."],"sources":[{"title":"Tropica · Planting in the aquarium","url":"https://tropica.com/en/guide/get-the-right-start/planting/"}]}'::jsonb),
  ('system', 'preset', '种植箱', '{"overview":"重点是湿土承重、排水口和今后的清理通道。","parameters":[],"cycle":null,"sections":[{"title":"开始前与操作","items":["填土前试注清水，确认排水口畅通；垫高方式按箱体说明，不封死底孔。","按产品说明核对满载重量、连接件和固定方式；先空载装好，再分次放入湿土或花盆。"]},{"title":"日常照护与维护","items":["浇透后检查排水，移走接水盘长时间积水；随土沉降少量补基质。","浇水后检查支脚、接缝和地面积水；固定同一角度拍照，便于发现歪斜和下沉。"]},{"title":"异常先看这里","items":["箱壁外鼓、底板变形或支脚下沉时先停止加土，卸载后检查。"]},{"title":"检查提醒","items":["增加花盆、移动位置和大风后重新检查；发现松动先卸载再修复。"]}],"cautions":["阳台、屋顶和悬挂设施的承重不能靠目测确认；不明承重时先让专业人员核实。"],"sources":[]}'::jsonb, '{"overview":"Plan for wet-soil load, open drainage, and cleaning access.","parameters":[],"cycle":null,"sections":[{"title":"Start here","items":["Test drainage with clean water before filling; support the box as specified without blocking outlets.","Check the product''s loaded-weight rating, fasteners, and anchoring; assemble empty and add wet soil or pots in stages."]},{"title":"Routine care","items":["Check drainage after watering, clear standing saucer water, and top up settled medium gradually.","After watering, inspect feet, joints, and standing water; repeat photos from one angle to reveal tilt or settlement."]},{"title":"If something changes","items":["Stop adding soil if walls bulge, the base distorts, or feet sink; unload before inspection."]},{"title":"When to check","items":["Recheck after adding pots, moving, or strong wind; unload a loose structure before repair."]}],"cautions":["Balcony, roof, and hanging loads cannot be judged by appearance; obtain a qualified assessment where capacity is unknown."],"sources":[]}'::jsonb),
  ('system', 'preset', '焖烧土堆', '{"overview":"作为传统熏土、火土肥工艺单列记录。它涉及燃烧，不属于微生物堆肥，不建议在家庭庭院制作。","parameters":[{"label":"指引范围","value":"传统工艺记录与材料风险判断"},{"label":"家庭使用","value":"不提供点火、焖烧制作流程"}],"cycle":null,"sections":[{"title":"先识别材料","items":["保留当地名称、原料来源和工艺记录；熏土、纯草木灰、生物炭并非同一种材料，不能共用一个施用比例。","已有成品也要查是否混入煤灰、涂漆木料或垃圾；来源不明时不加入菜地和盆栽。"]},{"title":"记录与替代","items":["不能因经过火烧就认定肥力更高、无病原或适合所有土；有明确成分检测和土检建议后才考虑小区试验。","想补有机物可选堆肥、腐叶土或绿肥；需要纠正pH时按土检处理，不用焖烧替代。"]}],"cautions":["烟尘会影响呼吸健康，余火可引发火灾；不要在室内、棚内、住宅附近或不符合当地用火要求的地方尝试。"],"sources":[{"title":"《肥料与健康》· 我国古代农业培肥地力的智慧与启示","url":"https://flyjk.ghs.cn/qk_f/1600419767973/resource/PDF/flyjk-47-2-14.pdf"},{"title":"OSU Extension · Wood ash and soil pH","url":"https://extension.oregonstate.edu/news/sweep-wood-ash-fireplace-garden"},{"title":"EPA · Wood smoke and health","url":"https://www.epa.gov/burnwise/wood-smoke-and-your-health"}]}'::jsonb, '{"overview":"Record this separately as a traditional burnt-earth practice. It involves combustion, not microbial composting, and is not recommended for home production.","parameters":[{"label":"Scope","value":"Historical records and material-risk assessment"},{"label":"Home use","value":"No ignition or smouldering instructions"}],"cycle":null,"sections":[{"title":"Identify the material","items":["Record the local name, feedstock, and process. Burnt earth, wood ash, and biochar are different materials and cannot share one application rate.","Check any existing material for coal ash, painted wood, or waste. Keep unknown material out of food beds and pots."]},{"title":"Record and consider alternatives","items":["Burning does not by itself prove greater fertility, pathogen safety, or universal suitability. Consider a trial only with material analysis and soil-test advice.","For organic matter, choose compost, leafmould, or green manure. Follow soil-test advice for pH instead of burning."]}],"cautions":["Smoke harms respiratory health and embers can start fires. Do not attempt this indoors, in sheds, near homes, or contrary to local fire requirements."],"sources":[{"title":"《肥料与健康》· 我国古代农业培肥地力的智慧与启示","url":"https://flyjk.ghs.cn/qk_f/1600419767973/resource/PDF/flyjk-47-2-14.pdf"},{"title":"OSU Extension · Wood ash and soil pH","url":"https://extension.oregonstate.edu/news/sweep-wood-ash-fireplace-garden"},{"title":"EPA · Wood smoke and health","url":"https://www.epa.gov/burnwise/wood-smoke-and-your-health"}]}'::jsonb),
  ('insect_fish', 'preset', '蝴蝶', '{"overview":"种植寄主与蜜源、少干扰，比捕捉成蝶更适合庭院观察。","parameters":[],"cycle":null,"sections":[{"title":"开始前与操作","items":["确认本地蝶种的幼虫寄主，保留可供停歇和化蛹的安静枝叶。","拍下成体或幼体特征、发现植物和日期，先确认对象及生活阶段。"]},{"title":"日常照护与维护","items":["记录访花、产卵和幼虫变化，避免对寄主喷施杀虫剂。","用短时观察代替频繁翻动，记录取食、蜕变和所处植物；及时清除饲养容器中的腐败物。"]},{"title":"异常先看这里","items":["叶片被吃时先确认是否为目标蝶种幼虫，不因孔洞立即清除。"]},{"title":"检查提醒","items":["蜕皮、化蛹或羽化前后减少触碰；变化当天拍照记录，而非按固定天数催促。"]}],"cautions":["不能可靠识别、有毒或有蜇伤风险的种类以远距离观察为主；不跨地区释放饲养个体。"],"sources":[{"title":"RHS · Wildlife in gardens","url":"https://www.rhs.org.uk/wildlife/in-gardens"},{"title":"RHS · Butterflies in the garden","url":"https://www.rhs.org.uk/wildlife/butterflies-in-your-garden"}]}'::jsonb, '{"overview":"Host and nectar plants with low disturbance support observation better than catching adults.","parameters":[],"cycle":null,"sections":[{"title":"Start here","items":["Identify host plants for local larvae and retain quiet foliage for resting and pupation.","Photograph identifying features, host plant, and date; establish the organism and life stage first."]},{"title":"Routine care","items":["Log flower visits, egg laying, and larvae and avoid insecticides on host plants.","Use brief observation instead of repeated disturbance; log feeding, molts, and host plants and remove decaying material from kept enclosures."]},{"title":"If something changes","items":["Identify caterpillars before removing them simply because host leaves have holes."]},{"title":"When to check","items":["Minimize handling around molts, pupation, and emergence; record the actual change rather than forcing a calendar."]}],"cautions":["Observe unidentified, venomous, or stinging organisms from a distance; do not release captive individuals in other regions."],"sources":[{"title":"RHS · Wildlife in gardens","url":"https://www.rhs.org.uk/wildlife/in-gardens"},{"title":"RHS · Butterflies in the garden","url":"https://www.rhs.org.uk/wildlife/butterflies-in-your-garden"}]}'::jsonb),
  ('insect_fish', 'preset', '海螺', '{"overview":"先分清草食、杂食或捕食种，不能都当除藻螺。","parameters":[],"cycle":null,"sections":[{"title":"开始前与操作","items":["核对准确种名和食性，确认不会捕食现有鱼虾或珊瑚。","用水族海盐配制新水，单独混匀并测盐度、水温；食盐水不能替代海水。"]},{"title":"日常照护与维护","items":["观察实际摄食和夜间位置，检查是否卡在石缝或被同伴攻击。","区分蒸发补水与换水：按实际盐度纠偏，补蒸发水前先核对仪表和水位。"]},{"title":"异常先看这里","items":["翻倒、长期不动或壳口损伤时先排查卡住、攻击与水质，勿徒手处理未知有毒种。"]},{"title":"检查提醒","items":["每天看水位、循环和动物呼吸；换水或增加生物前后复测盐度和氮废物。"]}],"cautions":["珊瑚、鱼和无脊椎动物的兼容性需分别核对；不根据气泡或水色判断水质安全。"],"sources":[{"title":"OATA · Marine aquarium care","url":"https://ornamentalfish.org/what-we-do/advice-information/care-sheets/caresheets-marine-fish/how-to-set-up-and-look-after-a-marine-tank-aquarium/"}]}'::jsonb, '{"overview":"Identify herbivorous, omnivorous, or predatory snails rather than treating all as grazers.","parameters":[],"cycle":null,"sections":[{"title":"Start here","items":["Confirm the species/diet and compatibility with current fish, shrimp, and corals.","Prepare replacement water separately with aquarium marine salt, then measure salinity and temperature; table salt is not a substitute."]},{"title":"Routine care","items":["Check feeding and nighttime position for trapping in rockwork or attacks.","Distinguish evaporation top-ups from water changes; check the instrument, level, and salinity before correction."]},{"title":"If something changes","items":["For overturning, inactivity, or opening injuries, inspect trapping, aggression, and water; do not handle unknown venomous species."]},{"title":"When to check","items":["Check level, circulation, and breathing daily; retest salinity and nitrogen waste around water changes and stocking."]}],"cautions":["Check compatibility separately for fish, corals, and invertebrates; bubbles or water color do not establish safety."],"sources":[{"title":"OATA · Marine aquarium care","url":"https://ornamentalfish.org/what-we-do/advice-information/care-sheets/caresheets-marine-fish/how-to-set-up-and-look-after-a-marine-tank-aquarium/"}]}'::jsonb),
  ('insect_fish', 'preset', '原生鱼', '{"overview":"“原生鱼”不是单一物种，先辨种再决定水温、流速和食物。","parameters":[],"cycle":null,"sections":[{"title":"开始前与操作","items":["保存准确种名与合法来源信息，分别确认成鱼体型、温度和流速需求。","入鱼前用检测确认过滤系统能处理氨和亚硝酸盐，不以水清或开机天数代替检测。"]},{"title":"日常照护与维护","items":["用温度计与水流观察记录季节变化，食物按已确认的食性选择。","每天先观察呼吸、游姿和摄食再投喂；记下剩饵和换水量，换水时匹配新水条件。"]},{"title":"异常先看这里","items":["未知种拒食不要轮番投药或野采饵料；先请可靠人员辨种并核对环境。"]},{"title":"检查提醒","items":["新入鱼、过滤维护或停电后增加水质检查；离家前确认有人能查看设备和动物。"]}],"cautions":["异常先查水质和设备；持续呼吸困难、损伤或不进食应联系水生动物兽医，不混用药物试错。"],"sources":[{"title":"OATA · Freshwater aquarium care","url":"https://ornamentalfish.org/what-we-do/advice-information/care-sheets/caresheets-tropical-freshwater-fish/how-to-set-up-and-look-after-a-freshwater-tank-aquarium/"}]}'::jsonb, '{"overview":"Native fish are not one species; identify before choosing temperature, flow, or diet.","parameters":[],"cycle":null,"sections":[{"title":"Start here","items":["Keep the exact name and lawful source and confirm adult size, temperature, and flow separately.","Before stocking, use tests to confirm the filter handles ammonia and nitrite; clear water or elapsed days are not proof."]},{"title":"Routine care","items":["Log seasonal temperature/flow and choose food for the confirmed diet.","Observe breathing, swimming, and appetite before feeding; log leftovers and water changes and match replacement-water conditions."]},{"title":"If something changes","items":["For an unidentified fish refusing food, seek identification and environment review rather than cycling drugs or wild foods."]},{"title":"When to check","items":["Increase water checks after additions, filter work, or power loss; arrange equipment and animal checks before travel."]}],"cautions":["Check water and equipment first; persistent breathing difficulty, injury, or refusal to feed needs aquatic-veterinary advice, not mixed treatments."],"sources":[{"title":"OATA · Freshwater aquarium care","url":"https://ornamentalfish.org/what-we-do/advice-information/care-sheets/caresheets-tropical-freshwater-fish/how-to-set-up-and-look-after-a-freshwater-tank-aquarium/"}]}'::jsonb),
  ('insect_fish', 'preset', '蜈蚣草', '{"overview":"商品俗名并不唯一，先凭标签确定是哪种茎草。","parameters":[{"label":"光照","value":"弱至中光"},{"label":"参考水温范围","value":"水温待确认"},{"label":"生长方式","value":"茎生／漂浮"},{"label":"难度","value":"容易"}],"cycle":null,"sections":[{"title":"开始前与操作","items":["保留标签与全株照片，按确认后的水生品种分茎定植。","保留购买标签或学名；清除运输包装，先把种植位置和入缸状态拍下来。"]},{"title":"日常照护与维护","items":["查看新芽与节间变化，修剪时保留健康茎段并移走坏死部分。","每周同角度拍新芽和老叶；修剪后捞净碎叶，记下光照、施肥或换水的单项变化。"]},{"title":"异常先看这里","items":["长期只有旧叶没有水下新生长，先核对是否买到适合长期沉水的种类。"]},{"title":"检查提醒","items":["刚定植时先检查是否松脱；修剪、移动灯具或换水后，连续观察新叶而不只看旧叶。"]}],"cautions":["俗名可能对应不同物种；不要凭名称套用统一水温。修剪物不要丢进河道或户外水体。"],"sources":[{"title":"Tropica · Planting in the aquarium","url":"https://tropica.com/en/guide/get-the-right-start/planting/"}]}'::jsonb, '{"overview":"The trade name is ambiguous; identify the actual stem plant first.","parameters":[{"label":"Light","value":"Low to medium"},{"label":"Reference water-temperature range","value":"Range unverified"},{"label":"Growth form","value":"Stem / floating"},{"label":"Difficulty","value":"Easy"}],"cycle":null,"sections":[{"title":"Start here","items":["Keep the label and whole-plant photo, then space stems for the confirmed aquatic species.","Keep the label or scientific name, remove transport packaging, and photograph the planting position and arrival condition."]},{"title":"Routine care","items":["Track shoots and internodes; retain healthy sections and remove dead material during pruning.","Photograph new and old leaves weekly; remove pruning debris and log individual changes in light, nutrients, or water."]},{"title":"If something changes","items":["If old leaves persist without submerged new growth, verify suitability for long-term underwater growth."]},{"title":"When to check","items":["Check for loose plants after planting; following pruning, light changes, or water changes, track new growth as well as old leaves."]}],"cautions":["Trade names can cover different species; do not assume one temperature from a name. Keep trimmings out of natural waterways."],"sources":[{"title":"Tropica · Planting in the aquarium","url":"https://tropica.com/en/guide/get-the-right-start/planting/"}]}'::jsonb),
  ('insect_fish', 'preset', '红蝴蝶', '{"overview":"先养稳新叶与根，再评估颜色，不为追红同时猛调灯和肥。","parameters":[{"label":"光照","value":"强光"},{"label":"参考水温范围","value":"22–28℃","note":"资料所列范围，并非全程最适温度。"},{"label":"生长方式","value":"茎草"},{"label":"难度","value":"较难"}],"cycle":null,"sections":[{"title":"开始前与操作","items":["确认准确品种及供应方栽培条件，分茎种植并记录原来叶色。","保留购买标签或学名；清除运输包装，先把种植位置和入缸状态拍下来。"]},{"title":"日常照护与维护","items":["固定拍摄位置比较新叶，灯、肥或碳源每次只改一项。","每周同角度拍新芽和老叶；修剪后捞净碎叶，记下光照、施肥或换水的单项变化。"]},{"title":"异常先看这里","items":["叶尖损伤或大量落叶时先回查最近改动，不把颜色浅直接判为缺肥。"]},{"title":"检查提醒","items":["刚定植时先检查是否松脱；修剪、移动灯具或换水后，连续观察新叶而不只看旧叶。"]}],"cautions":["俗名可能对应不同物种；不要凭名称套用统一水温。修剪物不要丢进河道或户外水体。","水温参考品种：Rotala macrandra ''Bangladesh''，22–28℃。这是资料所列范围，并非整段都是最适温度；同名水草可能不是同一品种，不要据此骤升骤降水温。"],"sources":[{"title":"Tropica · Planting in the aquarium","url":"https://tropica.com/en/guide/get-the-right-start/planting/"},{"title":"Dennerle — Rotala macrandra ''Bangladesh''","url":"https://dennerleplants.co.uk/products/rotala-macrandra-bangladesh"}]}'::jsonb, '{"overview":"Establish roots and new leaves before chasing red coloration.","parameters":[{"label":"Light","value":"High light"},{"label":"Reference water-temperature range","value":"22–28°C","note":"Published range, not an optimum throughout."},{"label":"Growth form","value":"Stem plant"},{"label":"Difficulty","value":"Advanced"}],"cycle":null,"sections":[{"title":"Start here","items":["Confirm the exact species and supplier conditions, space stems, and record initial color.","Keep the label or scientific name, remove transport packaging, and photograph the planting position and arrival condition."]},{"title":"Routine care","items":["Compare new leaves from a fixed photo position and change only light, nutrients, or carbon at a time.","Photograph new and old leaves weekly; remove pruning debris and log individual changes in light, nutrients, or water."]},{"title":"If something changes","items":["For damaged tips or heavy leaf loss, review recent changes; pale color alone is not a fertilizer diagnosis."]},{"title":"When to check","items":["Check for loose plants after planting; following pruning, light changes, or water changes, track new growth as well as old leaves."]}],"cautions":["Trade names can cover different species; do not assume one temperature from a name. Keep trimmings out of natural waterways.","Temperature reference: Rotala macrandra ''Bangladesh'', 22–28°C. This is a published range, not an ideal setpoint or permission for sudden temperature changes; other species sold under this common name may differ."],"sources":[{"title":"Tropica · Planting in the aquarium","url":"https://tropica.com/en/guide/get-the-right-start/planting/"},{"title":"Dennerle — Rotala macrandra ''Bangladesh''","url":"https://dennerleplants.co.uk/products/rotala-macrandra-bangladesh"}]}'::jsonb),
  ('system', 'preset', '腐叶土', '{"overview":"让落叶缓慢分解成保水、改善结构的材料；它通常养分较低，不等同于肥料或普通园土。","parameters":[{"label":"材料","value":"干净落叶，厚硬叶先剪碎"},{"label":"参考时间","value":"约1年可作覆盖，细熟料常需2年或更久"}],"cycle":null,"sections":[{"title":"收集与堆放","items":["收集无明显污染的落叶，去掉塑料和杂物；干叶润湿后放入打孔袋或网围，袋口松扎，标注日期。","放在避风处，干燥时补水；厚叶结成板状就轻轻打散。无需追求像热堆肥那样升温。"]},{"title":"分级使用","items":["仍看得出叶片的半熟料用于地表覆盖，避开植物茎基；细碎、充分分解的部分再混入适宜基质。","记录叶片来源、湿度和使用后排水情况；苗盆先少量试配，不把年份直接当成成熟保证。"]}],"cautions":["不使用疑似受除草剂或道路污染的落叶；育苗所需养分和卫生条件仍要单独管理。"],"sources":[{"title":"RHS · Leafmould","url":"https://www.rhs.org.uk/soil-composts-mulches/leaf-mould"},{"title":"RHS · Making the most of fallen leaves","url":"https://www.rhs.org.uk/advice/grow-your-own/features/making-leafmould"}]}'::jsonb, '{"overview":"Let leaves decay into a moisture-retaining soil conditioner. Leafmould is generally low in nutrients, not a complete fertilizer or ordinary topsoil.","parameters":[{"label":"Material","value":"Clean fallen leaves; shred thick leaves"},{"label":"Time reference","value":"About a year for mulch; finer material often takes two years or more"}],"cycle":null,"sections":[{"title":"Collect and store","items":["Remove litter from clean leaves. Moisten dry leaves and place in perforated bags or a mesh enclosure; loosely close bags and date each batch.","Shelter from wind, add moisture when dry, and loosen matted layers. Heating like a hot compost pile is not the goal."]},{"title":"Use by maturity","items":["Use partly decomposed leaves as surface mulch away from stems. Blend only fine, well-decomposed material into suitable growing media.","Log leaf source, moisture, and drainage after use. Trial a small potting mix; age alone is not proof of readiness."]}],"cautions":["Avoid suspect herbicide or roadside contamination. Manage seedling nutrition and hygiene separately."],"sources":[{"title":"RHS · Leafmould","url":"https://www.rhs.org.uk/soil-composts-mulches/leaf-mould"},{"title":"RHS · Making the most of fallen leaves","url":"https://www.rhs.org.uk/advice/grow-your-own/features/making-leafmould"}]}'::jsonb),
  ('insect_fish', 'preset', '水榕', '{"overview":"水榕适合固定在石木上，粗壮根茎不能埋住。","parameters":[{"label":"光照","value":"弱光"},{"label":"参考水温范围","value":"22–28℃","note":"资料所列范围，并非全程最适温度。"},{"label":"生长方式","value":"附生"},{"label":"难度","value":"容易"}],"cycle":null,"sections":[{"title":"开始前与操作","items":["把细根与横向根茎分清，只固定根或根茎外侧，保持根茎露出。","保留购买标签或学名；清除运输包装，先把种植位置和入缸状态拍下来。"]},{"title":"日常照护与维护","items":["轻擦老叶积尘和附着藻，剪除完全坏死叶片，观察根茎上的新芽。","每周同角度拍新芽和老叶；修剪后捞净碎叶，记下光照、施肥或换水的单项变化。"]},{"title":"异常先看这里","items":["根茎发软先查是否被埋、绑得过紧或局部坏死，不继续加肥。"]},{"title":"检查提醒","items":["刚定植时先检查是否松脱；修剪、移动灯具或换水后，连续观察新叶而不只看旧叶。"]}],"cautions":["俗名可能对应不同物种；不要凭名称套用统一水温。修剪物不要丢进河道或户外水体。","水温参考品种：Anubias barteri var. nana，22–28℃。这是资料所列范围，并非整段都是最适温度；同名水草可能不是同一品种，不要据此骤升骤降水温。"],"sources":[{"title":"Tropica · Planting in the aquarium","url":"https://tropica.com/en/guide/get-the-right-start/planting/"},{"title":"Dennerle — Anubias barteri var. nana","url":"https://dennerleplants.com/en/plants/plantdetails/Anubiasbarterivar.nana(781)/27804"}]}'::jsonb, '{"overview":"Anubias can attach to hardscape; keep its thick rhizome exposed.","parameters":[{"label":"Light","value":"Low light"},{"label":"Reference water-temperature range","value":"22–28°C","note":"Published range, not an optimum throughout."},{"label":"Growth form","value":"Epiphyte"},{"label":"Difficulty","value":"Easy"}],"cycle":null,"sections":[{"title":"Start here","items":["Distinguish fine roots from the horizontal rhizome and secure it without burial.","Keep the label or scientific name, remove transport packaging, and photograph the planting position and arrival condition."]},{"title":"Routine care","items":["Gently clear debris/algae on older leaves, remove dead leaves, and watch new shoots.","Photograph new and old leaves weekly; remove pruning debris and log individual changes in light, nutrients, or water."]},{"title":"If something changes","items":["For a soft rhizome, inspect burial, tight ties, or rot before adding fertilizer."]},{"title":"When to check","items":["Check for loose plants after planting; following pruning, light changes, or water changes, track new growth as well as old leaves."]}],"cautions":["Trade names can cover different species; do not assume one temperature from a name. Keep trimmings out of natural waterways.","Temperature reference: Anubias barteri var. nana, 22–28°C. This is a published range, not an ideal setpoint or permission for sudden temperature changes; other species sold under this common name may differ."],"sources":[{"title":"Tropica · Planting in the aquarium","url":"https://tropica.com/en/guide/get-the-right-start/planting/"},{"title":"Dennerle — Anubias barteri var. nana","url":"https://dennerleplants.com/en/plants/plantdetails/Anubiasbarterivar.nana(781)/27804"}]}'::jsonb),
  ('other', 'preset', '臭卤菜', '{"overview":"“臭味正常”不是安全依据，老卤尤其需要明确来源和经过验证的工艺。","parameters":[],"cycle":null,"sections":[{"title":"开始前与操作","items":["没有可验证的卤液来源、温度和处理流程时不要启动家庭自然发酵；可改用正规成品卤料的配套做法。","开始前要有适用于该食品的明确菌种和经过验证的完整工艺；记录盐量、温度与容器，不凭口味减盐。"]},{"title":"日常照护与维护","items":["原卤、处理原料和成品用具分开，记录每次加入物，禁止把不明剩料反复续入。","每次检查先清洁工具；按原工艺管理液面、通气和温度，不边做边更换配方。"]},{"title":"异常先看这里","items":["批次记录缺失或出现非工艺预期的产气、黏滑和霉变时停止使用，煮沸不保证消除所有风险。"]},{"title":"检查提醒","items":["关键温度、时间或配比失控就停止作为可食用成品使用；不要把补盐、再煮或挑掉霉点当作补救。"]}],"cautions":["此页用于操作前核查和过程记录，不构成家庭自然发酵配方；缺少可靠工艺时选择有资质来源的成品。"],"sources":[{"title":"NCHFP · Fermentation controls","url":"https://nchfp.uga.edu/how/ferment/general-information-on-fermenting/"},{"title":"Centre for Food Safety · Safe bean-curd preparation","url":"https://www.cfs.gov.hk/english/multimedia/multimedia_pub/multimedia_pub_fsf_239_02.html"}]}'::jsonb, '{"overview":"An expected strong odor does not establish safety; old brines need traceability and a validated process.","parameters":[],"cycle":null,"sections":[{"title":"Start here","items":["Do not start spontaneous home fermentation without verifiable brine, temperature, and process controls; use a reputable prepared product with instructions instead.","Start only with an identified culture and a validated process for that food; record salt, temperature, and vessel, and do not reduce salt by taste."]},{"title":"Routine care","items":["Separate brine, raw-material, and finished-food utensils and log every addition; never keep adding unknown leftovers.","Clean tools before checks and manage liquid level, aeration, and temperature according to the original method rather than changing recipes mid-process."]},{"title":"If something changes","items":["Missing controls or unexpected gas, slime, or mold means stop use; boiling does not guarantee removal of every hazard."]},{"title":"When to check","items":["If critical time, temperature, or proportions fail, stop treating the batch as edible; extra salt, reheating, or removing mold is not a validated rescue."]}],"cautions":["This is a preparation and process-check guide, not a spontaneous-fermentation recipe; choose a reputable finished product if a reliable process is unavailable."],"sources":[{"title":"NCHFP · Fermentation controls","url":"https://nchfp.uga.edu/how/ferment/general-information-on-fermenting/"},{"title":"Centre for Food Safety · Safe bean-curd preparation","url":"https://www.cfs.gov.hk/english/multimedia/multimedia_pub/multimedia_pub_fsf_239_02.html"}]}'::jsonb),
  ('other', 'preset', '其他', '{"overview":"先写清正在做哪种食物和打算怎么保存，再选择对应的安全工艺。","parameters":[],"cycle":null,"sections":[{"title":"开始前与操作","items":["把食物名、原料、加工方法与保存目标写入项目，找到适用于该食品的可靠做法。","称量原料并保存所用可靠配方；把容器、加工日期和冷藏方式写在记录里。"]},{"title":"日常照护与维护","items":["记录关键重量、时间和储存条件；没有成熟工艺时先做少量即食，不扩展成长期保存。","按配方的完整流程操作，器具接触生料后重新清洁；分装时避免把旧批次混入新批次。"]},{"title":"异常先看这里","items":["涉及低酸罐藏、真空常温保存或不明发酵时，不用其他食物的经验替代验证。"]},{"title":"检查提醒","items":["制作和开封时各记一次日期；没有经过验证的常温保存工艺，就不要按罐头长期存放。"]}],"cautions":["鼓盖、渗漏、霉变或保存条件不明时不要试吃；闻起来正常也不能证明安全。"],"sources":[{"title":"NCHFP · Tested home-preservation methods","url":"https://nchfp.uga.edu/how/pickle/general-information-pickling/general-information-on-pickling/"}]}'::jsonb, '{"overview":"Name the food and intended storage before selecting a safe process.","parameters":[],"cycle":null,"sections":[{"title":"Start here","items":["Record food, ingredients, method, and storage goal and find a reliable method for that food.","Weigh ingredients and retain the reliable recipe; record the container, processing date, and refrigeration method."]},{"title":"Routine care","items":["Log critical weights, times, and storage; without an established method, do not extrapolate a small fresh dish into long-term storage.","Follow the complete method, clean utensils after raw ingredients, and do not mix an old batch into a new one."]},{"title":"If something changes","items":["For low-acid canning, room-temperature vacuum storage, or unknown fermentation, another food''s experience is not validation."]},{"title":"When to check","items":["Record both making and opening dates; without a validated shelf-stable process, do not treat the product as a long-life preserve."]}],"cautions":["Do not taste swollen, leaking, moldy, or questionably stored food; a normal smell does not prove safety."],"sources":[{"title":"NCHFP · Tested home-preservation methods","url":"https://nchfp.uga.edu/how/pickle/general-information-pickling/general-information-on-pickling/"}]}'::jsonb),
  ('other', 'preset', '酱油', '{"overview":"制曲和酱醪成熟是受控过程，不是把豆子泡咸水即可。","parameters":[],"cycle":null,"sections":[{"title":"开始前与操作","items":["没有稳定菌种、卫生和工艺条件时不建议从自然接种开始；先明确原料、盐水与成熟流程。","开始前要有适用于该食品的明确菌种和经过验证的完整工艺；记录盐量、温度与容器，不凭口味减盐。"]},{"title":"日常照护与维护","items":["记录每个阶段的称量和温度，取样用洁净工具，按原工艺安排后处理。","每次检查先清洁工具；按原工艺管理液面、通气和温度，不边做边更换配方。"]},{"title":"异常先看这里","items":["仅靠咸味、颜色或闻香不能确认安全；异常批次不与正常酱油混合。"]},{"title":"检查提醒","items":["关键温度、时间或配比失控就停止作为可食用成品使用；不要把补盐、再煮或挑掉霉点当作补救。"]}],"cautions":["此页用于操作前核查和过程记录，不构成家庭自然发酵配方；缺少可靠工艺时选择有资质来源的成品。"],"sources":[{"title":"NCHFP · Fermentation controls","url":"https://nchfp.uga.edu/how/ferment/general-information-on-fermenting/"},{"title":"Centre for Food Safety · Safe bean-curd preparation","url":"https://www.cfs.gov.hk/english/multimedia/multimedia_pub/multimedia_pub_fsf_239_02.html"}]}'::jsonb, '{"overview":"Koji and mash maturation are controlled processes, not simply beans in salty water.","parameters":[],"cycle":null,"sections":[{"title":"Start here","items":["Do not start with spontaneous inoculation without reliable culture, hygiene, and controls; define ingredients, brine, and maturation first.","Start only with an identified culture and a validated process for that food; record salt, temperature, and vessel, and do not reduce salt by taste."]},{"title":"Routine care","items":["Log weights and temperatures by stage, sample cleanly, and follow the specified finishing process.","Clean tools before checks and manage liquid level, aeration, and temperature according to the original method rather than changing recipes mid-process."]},{"title":"If something changes","items":["Saltiness, color, or aroma cannot establish safety; never blend a suspect batch into good sauce."]},{"title":"When to check","items":["If critical time, temperature, or proportions fail, stop treating the batch as edible; extra salt, reheating, or removing mold is not a validated rescue."]}],"cautions":["This is a preparation and process-check guide, not a spontaneous-fermentation recipe; choose a reputable finished product if a reliable process is unavailable."],"sources":[{"title":"NCHFP · Fermentation controls","url":"https://nchfp.uga.edu/how/ferment/general-information-on-fermenting/"},{"title":"Centre for Food Safety · Safe bean-curd preparation","url":"https://www.cfs.gov.hk/english/multimedia/multimedia_pub/multimedia_pub_fsf_239_02.html"}]}'::jsonb),
  ('insect_fish', 'preset', '黑水虻', '{"overview":"重点管理来源清楚的湿料、透气和幼虫迁出，避免变成积液臭桶。","parameters":[],"cycle":null,"sections":[{"title":"开始前与操作","items":["准备可排液、防逃且便于清理的容器，少量投放可追溯原料。","拍下成体或幼体特征、发现植物和日期，先确认对象及生活阶段。"]},{"title":"日常照护与维护","items":["按实际消耗补料，不让新料压成厚层；检查积液、气味和幼虫活力。","用短时观察代替频繁翻动，记录取食、蜕变和所处植物；及时清除饲养容器中的腐败物。"]},{"title":"异常先看这里","items":["腐臭或大量死亡先停投料并排查积液与过热；不把不明原料养出的虫直接作饲料。"]},{"title":"检查提醒","items":["蜕皮、化蛹或羽化前后减少触碰；变化当天拍照记录，而非按固定天数催促。"]}],"cautions":["不能可靠识别、有毒或有蜇伤风险的种类以远距离观察为主；不跨地区释放饲养个体。"],"sources":[{"title":"RHS · Wildlife in gardens","url":"https://www.rhs.org.uk/wildlife/in-gardens"}]}'::jsonb, '{"overview":"Manage traceable feed, air, and larval movement without creating a foul liquid-filled bin.","parameters":[],"cycle":null,"sections":[{"title":"Start here","items":["Use a drainable, cleanable, contained vessel and start with small traceable feed additions.","Photograph identifying features, host plant, and date; establish the organism and life stage first."]},{"title":"Routine care","items":["Replenish according to consumption, avoid compact thick layers, and inspect liquid, odor, and activity.","Use brief observation instead of repeated disturbance; log feeding, molts, and host plants and remove decaying material from kept enclosures."]},{"title":"If something changes","items":["For foul odor or deaths, stop feeding and inspect pooling/heat; do not use larvae raised on unknown waste as feed."]},{"title":"When to check","items":["Minimize handling around molts, pupation, and emergence; record the actual change rather than forcing a calendar."]}],"cautions":["Observe unidentified, venomous, or stinging organisms from a distance; do not release captive individuals in other regions."],"sources":[{"title":"RHS · Wildlife in gardens","url":"https://www.rhs.org.uk/wildlife/in-gardens"}]}'::jsonb),
  ('insect_fish', 'preset', '猪', '{"overview":"饮水是否真正可用、地面是否干燥，往往比多加一顿料更先检查。","parameters":[],"cycle":null,"sections":[{"title":"开始前与操作","items":["测试饮水嘴实际出水，准备遮阴通风、干燥卧区及按阶段配制的饲料。","按年龄、体况和繁殖阶段向当地兽医或饲养顾问确认日粮；新个体设独立观察区。"]},{"title":"日常照护与维护","items":["比较每天饮水和剩料变化，查看躺卧、喘气、争食及地面湿滑。","每天实际检查饮水是否流出、食槽余量、粪便和行走；不要只记录已投了多少料。"]},{"title":"异常先看这里","items":["突然少饮或多饮时先复核饮水器、漏水和环境，再联系兽医分析伴随症状。"]},{"title":"检查提醒","items":["高温、转栏、换料和临近生产时增加巡查；疫苗、驱虫及用药计划交由当地兽医制定。"]}],"cautions":["倒地、明显腹胀、呼吸困难或持续不采食应及时求助；大型动物操作需有安全退路。"],"sources":[{"title":"UMN Extension · Monitoring pigs'' water intake","url":"https://extension.umn.edu/agriculture/animals-and-livestock/swine/using-water-intake-monitor-pig-performance"}]}'::jsonb, '{"overview":"Check functioning water and dry flooring before simply adding feed.","parameters":[],"cycle":null,"sections":[{"title":"Start here","items":["Test nipple flow and provide shade, airflow, dry lying space, and stage-appropriate feed.","Confirm the ration for age, condition, and reproductive stage with a local vet or nutrition adviser; separate newcomers for observation."]},{"title":"Routine care","items":["Compare water/feed leftovers and observe lying, panting, competition, and slippery floors.","Check that water actually flows, inspect feed leftovers, manure, and gait daily, rather than recording only feed offered."]},{"title":"If something changes","items":["For sudden intake changes, verify drinkers, leaks, and conditions, then discuss accompanying signs with a vet."]},{"title":"When to check","items":["Increase checks during heat, moves, ration changes, and near birth; let a local vet set vaccination, parasite, and medicine plans."]}],"cautions":["Collapse, marked bloating, breathing difficulty, or persistent appetite loss needs prompt help; keep an escape route when handling large animals."],"sources":[{"title":"UMN Extension · Monitoring pigs'' water intake","url":"https://extension.umn.edu/agriculture/animals-and-livestock/swine/using-water-intake-monitor-pig-performance"}]}'::jsonb),
  ('insect_fish', 'preset', '浮萍', '{"overview":"管理重点是表面覆盖率，而不是让整片水面长期封住。","parameters":[{"label":"光照","value":"弱至中光"},{"label":"参考水温范围","value":"水温待确认"},{"label":"生长方式","value":"漂浮"},{"label":"难度","value":"容易"}],"cycle":null,"sections":[{"title":"开始前与操作","items":["先放少量在安静水面，给进出水口和其他植物上方留空。","保留购买标签或学名；清除运输包装，先把种植位置和入缸状态拍下来。"]},{"title":"日常照护与维护","items":["定期捞去多余部分，查看下层光线、水面交换和设备堵塞。","每周同角度拍新芽和老叶；修剪后捞净碎叶，记下光照、施肥或换水的单项变化。"]},{"title":"异常先看这里","items":["快速铺满时先疏除并回查营养来源；发黄则检查水流冲击和环境变化。"]},{"title":"检查提醒","items":["刚定植时先检查是否松脱；修剪、移动灯具或换水后，连续观察新叶而不只看旧叶。"]}],"cautions":["俗名可能对应不同物种；不要凭名称套用统一水温。修剪物不要丢进河道或户外水体。"],"sources":[{"title":"Tropica · Planting in the aquarium","url":"https://tropica.com/en/guide/get-the-right-start/planting/"}]}'::jsonb, '{"overview":"Manage surface coverage rather than leaving the whole surface sealed.","parameters":[{"label":"Light","value":"Low to medium"},{"label":"Reference water-temperature range","value":"Range unverified"},{"label":"Growth form","value":"Floating"},{"label":"Difficulty","value":"Easy"}],"cycle":null,"sections":[{"title":"Start here","items":["Start with a small amount on calm water, clear of outlets and plants below.","Keep the label or scientific name, remove transport packaging, and photograph the planting position and arrival condition."]},{"title":"Routine care","items":["Remove excess regularly and check light below, surface exchange, and equipment blockage.","Photograph new and old leaves weekly; remove pruning debris and log individual changes in light, nutrients, or water."]},{"title":"If something changes","items":["For rapid coverage thin first and review nutrient inputs; for yellowing inspect turbulence and changes."]},{"title":"When to check","items":["Check for loose plants after planting; following pruning, light changes, or water changes, track new growth as well as old leaves."]}],"cautions":["Trade names can cover different species; do not assume one temperature from a name. Keep trimmings out of natural waterways."],"sources":[{"title":"Tropica · Planting in the aquarium","url":"https://tropica.com/en/guide/get-the-right-start/planting/"}]}'::jsonb),
  ('insect_fish', 'preset', '白头鹎', '{"overview":"可观察访果、访花和鸣叫，优先通过植物提供自然环境。","parameters":[],"cycle":null,"sections":[{"title":"开始前与操作","items":["记录常来的灌木与果实，不设黏网或用食物诱入室内。","在原处选固定观察点，不抓捕、不搬巢，也不为了照片驱赶动物。"]},{"title":"日常照护与维护","items":["比较结果季和非结果季活动，修剪灌丛前查看是否有巢。","记录时间、天气、数量与行为；保持观察距离，减少夜灯、噪声和宠物追逐。"]},{"title":"异常先看这里","items":["果树受啄时用安全隔离保护果实，避免松散网线缠鸟。"]},{"title":"检查提醒","items":["繁殖或育幼期减少靠近；受伤个体先联系当地野生动物救助机构。"]}],"cautions":["不要把暂时停留或幼鸟离巢当作被遗弃；不强行喂水、喂奶或饲喂人类饭菜。"],"sources":[{"title":"RHS · Wildlife in gardens","url":"https://www.rhs.org.uk/wildlife/in-gardens"},{"title":"Cornell Lab · Window collisions and injured birds","url":"https://www.allaboutbirds.org/news/why-birds-hit-windows-and-how-you-can-help-prevent-it/"}]}'::jsonb, '{"overview":"Observe fruit/flower visits and calls and support habitat through plants.","parameters":[],"cycle":null,"sections":[{"title":"Start here","items":["Record favored shrubs/fruit without sticky traps or luring birds indoors.","Choose a fixed observation point in place; do not capture, move nests, or drive animals for a photo."]},{"title":"Routine care","items":["Compare activity across fruiting seasons and check shrubs before pruning.","Log time, weather, number, and behavior; keep distance and reduce night lighting, noise, and pet chasing."]},{"title":"If something changes","items":["Protect fruit with safe barriers that cannot entangle birds, not loose net strands."]},{"title":"When to check","items":["Increase distance during nesting or rearing; contact a local wildlife rehabilitator for injured animals."]}],"cautions":["Resting or fledging is not automatically abandonment; do not force water, milk, or human meals."],"sources":[{"title":"RHS · Wildlife in gardens","url":"https://www.rhs.org.uk/wildlife/in-gardens"},{"title":"Cornell Lab · Window collisions and injured birds","url":"https://www.allaboutbirds.org/news/why-birds-hit-windows-and-how-you-can-help-prevent-it/"}]}'::jsonb),
  ('system', 'preset', '绿肥种植与还田', '{"overview":"绿肥可以先种起来覆盖土壤，再割下还田；还田可翻入表土，也可留在地表分解，不必一律深翻。","parameters":[{"label":"选择依据","value":"本地季节、下茬作物、空闲时间"},{"label":"翻入后","value":"预留约1个月再播种或定植，并检查分解情况"}],"cycle":null,"sections":[{"title":"选种与管理","items":["根据当地播期选适宜绿肥，不照搬国外月份；查下茬作物科属，避免用同科绿肥延续病害。播量按所选品种说明。","记下播种量和覆盖面积，及时管理杂草；准备下茬前割下地上部，尽量避免结籽后变成新的杂草。"]},{"title":"割下与还田","items":["割下后萎蔫、切碎。土壤可操作时可混入表土；少扰动地块可作为地表覆盖，但要确认绿肥不会继续再生。","翻入后不要立即播种；到预留时间再查看残体和土壤状态，分解慢则继续等。留覆盖时腾出播种带，并检查蜗牛、蛞蝓。"]}],"cautions":["豆科固氮与品种、根瘤菌及条件有关；不能把所有绿肥都当作补氮肥，也不能保证固定天数腐烂完成。"],"sources":[{"title":"RHS · Green manures","url":"https://www.rhs.org.uk/soil-composts-mulches/green-manures"},{"title":"UMN Extension · Cover crop selection","url":"https://extension.umn.edu/agriculture/specialty-crops/vegetable-farming/cover-crop-selection-vegetable-growers"}]}'::jsonb, '{"overview":"Grow a cover crop, then return its growth to the bed. Incorporation and surface mulching are options; deep digging is not always necessary.","parameters":[{"label":"Choose by","value":"Local season, next crop, available time"},{"label":"After incorporation","value":"Allow about a month before planting and check decomposition"}],"cycle":null,"sections":[{"title":"Select and grow","items":["Choose a locally suitable crop and sowing window, not overseas calendar dates. Account for the following crop''s family and use the chosen seed''s sowing rate.","Record seed quantity and area; manage weeds. Terminate before the next crop and avoid viable seed production that creates a weed problem."]},{"title":"Terminate and return","items":["Wilt and chop the cut growth. Mix into workable topsoil, or leave as mulch in a low-disturbance bed while checking for regrowth.","Do not sow immediately after incorporation. Recheck residues after the waiting period and allow longer if needed. Clear a sowing strip in mulch and check for slugs."]}],"cautions":["Legume nitrogen fixation depends on species, rhizobia, and conditions. Not every cover crop adds nitrogen or decomposes on a fixed schedule."],"sources":[{"title":"RHS · Green manures","url":"https://www.rhs.org.uk/soil-composts-mulches/green-manures"},{"title":"UMN Extension · Cover crop selection","url":"https://extension.umn.edu/agriculture/specialty-crops/vegetable-farming/cover-crop-selection-vegetable-growers"}]}'::jsonb),
  ('system', 'preset', '蚯蚓堆肥', '{"overview":"用适合堆肥的蚯蚓处理少量植物残料；保持凉爽、湿润和通气，不把蚯蚓放进发热堆。","parameters":[{"label":"常用蚯蚓","value":"赤子爱胜蚓等堆肥蚯蚓"},{"label":"本例温度","value":"约15–25℃，以箱内实测为准"}],"cycle":null,"sections":[{"title":"安置与投料","items":["选遮阴、不会积水的通气箱；铺润湿后挤去余水的碎纸板或落叶垫料，再放入来源明确的堆肥蚯蚓。","少量切碎果蔬残料埋在垫料下，轮换投料位置；上一份基本吃完再加，不按固定日历强行投喂。"]},{"title":"异常与收取","items":["蚯蚓集中逃离或箱内发臭时暂停投料，查温度、积水和通气；移到凉处，过湿补干垫料，过干少量喷水。","把新料集中一侧，引蚯蚓迁移后分批取另一侧细料；挑出未消化残料，不把底部积液当成已经处理好的肥料。"]}],"cautions":["不投肉、油、乳制品或宠物粪便；堆肥蚯蚓不放生到野外，也不用野采蚯蚓替代。"],"sources":[{"title":"NC State Extension · Composting and worm bins","url":"https://content.ces.ncsu.edu/extension-gardener-handbook/2-composting"},{"title":"EPA · Composting at home","url":"https://www.epa.gov/recycle/composting-home"}]}'::jsonb, '{"overview":"Use composting worms for small amounts of plant scraps. Keep the bin cool, moist, and aerated; never add worms to a heating pile.","parameters":[{"label":"Common worm","value":"Composting worms such as Eisenia fetida"},{"label":"Working temperature","value":"About 15–25°C; measure inside the bin"}],"cycle":null,"sections":[{"title":"Set up and feed","items":["Choose a shaded, ventilated, drainable bin. Add damp, fluffed plain cardboard or leaf bedding and composting worms from a known source.","Bury small portions of chopped produce scraps under bedding, changing feeding spots. Wait until the previous portion is mostly consumed before adding more."]},{"title":"Troubleshoot and harvest","items":["Pause feeding if worms flee or the bin smells. Check heat, water, and air; relocate to a cooler spot, add dry bedding if wet, or mist if dry.","Feed one side to encourage migration, then collect finished material from the other in stages. Remove scraps; drainage liquid is not finished vermicompost."]}],"cautions":["Exclude meat, oil, dairy, and pet waste. Do not release composting worms or substitute wild-collected worms."],"sources":[{"title":"NC State Extension · Composting and worm bins","url":"https://content.ces.ncsu.edu/extension-gardener-handbook/2-composting"},{"title":"EPA · Composting at home","url":"https://www.epa.gov/recycle/composting-home"}]}'::jsonb),
  ('insect_fish', 'preset', '皇冠草', '{"overview":"按丛生水草预留成株叶片展开的位置。","parameters":[{"label":"光照","value":"中光"},{"label":"参考水温范围","value":"22–28℃","note":"资料所列范围，并非全程最适温度。"},{"label":"生长方式","value":"扎根"},{"label":"难度","value":"容易"}],"cycle":null,"sections":[{"title":"开始前与操作","items":["单株定植，根扎入底床但不埋叶心，与前景草和出水口留开距离。","保留购买标签或学名；清除运输包装，先把种植位置和入缸状态拍下来。"]},{"title":"日常照护与维护","items":["从基部剪除衰老叶，记录新叶大小与周围遮阴变化。","每周同角度拍新芽和老叶；修剪后捞净碎叶，记下光照、施肥或换水的单项变化。"]},{"title":"异常先看这里","items":["新叶长期变小先检查根区、遮光和底床变化，不一次叠加多种肥。"]},{"title":"检查提醒","items":["刚定植时先检查是否松脱；修剪、移动灯具或换水后，连续观察新叶而不只看旧叶。"]}],"cautions":["俗名可能对应不同物种；不要凭名称套用统一水温。修剪物不要丢进河道或户外水体。","水温参考品种：Echinodorus grisebachii ''Bleherae''，22–28℃。这是资料所列范围，并非整段都是最适温度；同名水草可能不是同一品种，不要据此骤升骤降水温。"],"sources":[{"title":"Tropica · Planting in the aquarium","url":"https://tropica.com/en/guide/get-the-right-start/planting/"},{"title":"Dennerle — Echinodorus grisebachii ''Bleherae''","url":"https://dennerleplants.com/en/plants/plantdetails/Echinodorus-grisebachii-%27Bleherae%27-%28154%29/23002"}]}'::jsonb, '{"overview":"Leave room for a rosette plant''s mature spread.","parameters":[{"label":"Light","value":"Medium light"},{"label":"Reference water-temperature range","value":"22–28°C","note":"Published range, not an optimum throughout."},{"label":"Growth form","value":"Rooted"},{"label":"Difficulty","value":"Easy"}],"cycle":null,"sections":[{"title":"Start here","items":["Plant separately with roots below and crown above the substrate, clear of foreground plants and outlets.","Keep the label or scientific name, remove transport packaging, and photograph the planting position and arrival condition."]},{"title":"Routine care","items":["Remove aging leaves at the base and track new-leaf size and shading.","Photograph new and old leaves weekly; remove pruning debris and log individual changes in light, nutrients, or water."]},{"title":"If something changes","items":["For persistently smaller new leaves, review root zone, shading, and substrate changes before stacking fertilizers."]},{"title":"When to check","items":["Check for loose plants after planting; following pruning, light changes, or water changes, track new growth as well as old leaves."]}],"cautions":["Trade names can cover different species; do not assume one temperature from a name. Keep trimmings out of natural waterways.","Temperature reference: Echinodorus grisebachii ''Bleherae'', 22–28°C. This is a published range, not an ideal setpoint or permission for sudden temperature changes; other species sold under this common name may differ."],"sources":[{"title":"Tropica · Planting in the aquarium","url":"https://tropica.com/en/guide/get-the-right-start/planting/"},{"title":"Dennerle — Echinodorus grisebachii ''Bleherae''","url":"https://dennerleplants.com/en/plants/plantdetails/Echinodorus-grisebachii-%27Bleherae%27-%28154%29/23002"}]}'::jsonb),
  ('system', 'preset', '土壤酸碱调整', '{"overview":"先测pH并确认目标植物的需要，再决定是否调整；不按固定日历浇醋水、撒石灰或加硫。","parameters":[{"label":"剂量依据","value":"检测建议、土质、面积、产品有效含量"},{"label":"生效速度","value":"材料与温湿度不同，不追求立刻改变"}],"cycle":null,"sections":[{"title":"测土与选择","items":["按检测机构要求取样；不同地块分开送检。先确定是偏酸、偏碱还是根系积水等其他问题。","需要提高或降低pH时，分别选检测建议的园艺改良材料；按产品标签换算试验区用量，不同时叠加多种调酸调碱材料。"]},{"title":"施用与复测","items":["称量并记录材料、含量、面积和日期，均匀施用并避开幼苗；按标签要求等待后在同一取样规则下复测。","硫的作用在低温下较慢，不因短期读数未变就重复加量；不适宜长期改酸的土，可考虑合适基质的容器种植。"]}],"cautions":["不使用强酸强碱或来历不明灰渣；草木灰也会改变pH，不能当作所有植物都适用的肥料。"],"sources":[{"title":"RHS · Acidifying soil","url":"https://www.rhs.org.uk/soil-composts-mulches/acidifying-soil"},{"title":"UMN Extension · Soil testing","url":"https://extension.umn.edu/garden-and-home/yard-and-garden/gardening-in-minnesota/soil-testing-for-lawns-and-gardens"},{"title":"OSU Extension · Wood ash and soil pH","url":"https://extension.oregonstate.edu/news/sweep-wood-ash-fireplace-garden"}]}'::jsonb, '{"overview":"Measure pH and identify the plant''s needs before adjusting. Do not use vinegar, lime, or sulfur on a routine calendar.","parameters":[{"label":"Dose depends on","value":"Lab advice, soil, area, product strength"},{"label":"Response time","value":"Varies with material, moisture, and temperature"}],"cycle":null,"sections":[{"title":"Test and choose","items":["Sample as directed by the lab, keeping distinct beds separate. Determine whether the issue is pH or another cause such as waterlogged roots.","Use a horticultural amendment recommended for the required direction. Calculate the trial-area dose from its label; avoid stacking different acidifying and liming materials."]},{"title":"Apply and retest","items":["Weigh and log material, strength, area, and date. Apply evenly, protecting seedlings; retest consistently after the label''s waiting period.","Sulfur works more slowly in cold soil; an unchanged early reading is not a reason to redose. Consider containers with suitable media where lasting acidification is impractical."]}],"cautions":["Avoid strong acids, caustics, or unknown ash. Wood ash changes pH and is not suitable for every plant."],"sources":[{"title":"RHS · Acidifying soil","url":"https://www.rhs.org.uk/soil-composts-mulches/acidifying-soil"},{"title":"UMN Extension · Soil testing","url":"https://extension.umn.edu/garden-and-home/yard-and-garden/gardening-in-minnesota/soil-testing-for-lawns-and-gardens"},{"title":"OSU Extension · Wood ash and soil pH","url":"https://extension.oregonstate.edu/news/sweep-wood-ash-fireplace-garden"}]}'::jsonb),
  ('system', 'preset', '堆肥', '{"overview":"以通气、含水和干湿料配比管理好氧堆肥，熟化后再使用。","parameters":[{"label":"起步配比","value":"干料∶湿料约2–3∶1（体积）"},{"label":"含水检查","value":"拧干海绵般湿润，不滴水"}],"cycle":null,"sections":[{"title":"配料与建堆","items":["用同一桶量取干叶或碎纸板与果蔬残料，剪碎后混合；底部放较粗干料，位置应能排水并方便翻堆。","新加厨余埋入干料中，不压成湿厚层；翻堆时把外围材料带到内部。太干分次加水，有酸臭先翻松并补干料。"]},{"title":"熟化与使用","items":["停止投新料，翻拌后不再明显升温且食物残渣基本分解，再留至少4周熟化；记下停止投料和熟化起始日期。","成品应松散、气味似土；未分解枝条筛出回堆。先在小块地试用，不把未熟料直接放进育苗盆或贴根埋。"]}],"cautions":["家庭堆肥不能保证杀灭病原和杂草种子；不加宠物粪便、病株、带除草剂残留的材料及肉油乳制品。"],"sources":[{"title":"EPA · Composting at home","url":"https://www.epa.gov/recycle/composting-home"},{"title":"RHS · Composting","url":"https://www.rhs.org.uk/soil-composts-mulches/composting"}]}'::jsonb, '{"overview":"Manage an aerobic pile with air, moisture, and a balance of dry and fresh material; cure before use.","parameters":[{"label":"Starting mix","value":"Browns:greens about 2–3:1 by volume"},{"label":"Moisture check","value":"Damp like a wrung-out sponge, not dripping"}],"cycle":null,"sections":[{"title":"Build the pile","items":["Measure dry leaves or shredded plain cardboard and produce scraps with the same bucket. Chop and mix; use coarse dry material at the base in a drainable, accessible spot.","Bury scraps in dry material without compact wet layers. Turn outer material inward. Add water gradually if dry; loosen and add browns if sour-smelling."]},{"title":"Cure and use","items":["Close the batch. Once mixing no longer causes heating and food scraps have decomposed, allow at least four weeks of curing; record both dates.","Look for a crumbly, earthy-smelling product. Return woody remnants to the pile. Trial it in a small bed; keep unfinished material out of seed pots and away from roots."]}],"cautions":["Home piles do not guarantee pathogen or weed-seed destruction. Exclude pet waste, diseased plants, herbicide residues, meat, oils, and dairy."],"sources":[{"title":"EPA · Composting at home","url":"https://www.epa.gov/recycle/composting-home"},{"title":"RHS · Composting","url":"https://www.rhs.org.uk/soil-composts-mulches/composting"}]}'::jsonb),
  ('insect_fish', 'preset', '蚂蚁', '{"overview":"观察觅食路线和植物关系，避免随意挖巢或捕捉蚁后。","parameters":[],"cycle":null,"sections":[{"title":"开始前与操作","items":["在安全距离记录进出点和搬运食物，不堵住巢口做试验。","拍下成体或幼体特征、发现植物和日期，先确认对象及生活阶段。"]},{"title":"日常照护与维护","items":["比较天气、时间与觅食量；室内食物密封并清除洒落残渣。","用短时观察代替频繁翻动，记录取食、蜕变和所处植物；及时清除饲养容器中的腐败物。"]},{"title":"异常先看这里","items":["若有叮咬风险或疑似入侵种，停止接触并请专业人员辨识处理。"]},{"title":"检查提醒","items":["蜕皮、化蛹或羽化前后减少触碰；变化当天拍照记录，而非按固定天数催促。"]}],"cautions":["不能可靠识别、有毒或有蜇伤风险的种类以远距离观察为主；不跨地区释放饲养个体。"],"sources":[{"title":"RHS · Wildlife in gardens","url":"https://www.rhs.org.uk/wildlife/in-gardens"}]}'::jsonb, '{"overview":"Observe trails and plant relationships without digging nests or taking queens.","parameters":[],"cycle":null,"sections":[{"title":"Start here","items":["Record entrances and carried food at a safe distance; do not block nests as an experiment.","Photograph identifying features, host plant, and date; establish the organism and life stage first."]},{"title":"Routine care","items":["Compare activity with weather/time and seal indoor food and spills.","Use brief observation instead of repeated disturbance; log feeding, molts, and host plants and remove decaying material from kept enclosures."]},{"title":"If something changes","items":["For biting risk or suspected invasive species, stop contact and request professional identification."]},{"title":"When to check","items":["Minimize handling around molts, pupation, and emergence; record the actual change rather than forcing a calendar."]}],"cautions":["Observe unidentified, venomous, or stinging organisms from a distance; do not release captive individuals in other regions."],"sources":[{"title":"RHS · Wildlife in gardens","url":"https://www.rhs.org.uk/wildlife/in-gardens"}]}'::jsonb),
  ('insect_fish', 'preset', '蛇', '{"overview":"先确认物种、成年体型和安全等级，再考虑长期饲养。","parameters":[],"cycle":null,"sections":[{"title":"开始前与操作","items":["只考虑能可靠识别且有合法来源的种类；检查锁扣、管线孔与冷热两端躲藏。","在动物实际停留处测量温度；加热设备用合适的温控和防接触保护，不只读房间温度。"]},{"title":"日常照护与维护","items":["按种类制定喂食与测重记录，蜕皮期间观察完整性，不强行揭皮。","每天检查饮水、排泄、活动与设备；换灯或移动晒台后重新测量，不照搬旧距离。"]},{"title":"异常先看这里","items":["持续残皮、呼吸杂音或体重下降应找异宠兽医；不要用活体猎物无人看管试喂。"]},{"title":"检查提醒","items":["保留设备说明、灯具启用日期和体重趋势；换季先复核种类需要，不自行安排冬眠。"]}],"cautions":["先确定物种再选食物、温度和UVB方案；呼吸异常、持续拒食或外伤需异宠兽医，指引不提供用药剂量。"],"sources":[{"title":"RSPCA · Caring for exotic pets","url":"https://www.rspca.org.uk/adviceandwelfare/pets/other"}]}'::jsonb, '{"overview":"Identify species, adult size, and safety requirements before keeping a snake.","parameters":[],"cycle":null,"sections":[{"title":"Start here","items":["Consider only reliably identified, lawfully sourced species; inspect locks, cable gaps, and hides across the gradient.","Measure where the animal actually rests; use suitable thermostats and contact guards, not room temperature alone."]},{"title":"Routine care","items":["Follow a species-specific feeding/weight log and observe sheds without forcibly peeling skin.","Check water, droppings, behavior, and equipment daily; remeasure after moving a basking site or replacing a lamp."]},{"title":"If something changes","items":["Persistent retained shed, breathing noise, or weight loss needs an exotics vet; never leave live prey unattended."]},{"title":"When to check","items":["Keep equipment instructions, lamp start dates, and weight trends; review species needs seasonally rather than initiating hibernation yourself."]}],"cautions":["Identify the species before choosing food, temperatures, or UVB; breathing problems, persistent refusal to eat, or injuries need an exotics vet. No drug doses are supplied here."],"sources":[{"title":"RSPCA · Caring for exotic pets","url":"https://www.rspca.org.uk/adviceandwelfare/pets/other"}]}'::jsonb),
  ('system', 'preset', '雨水收集', '{"overview":"让屋面杂物先被拦下，储水和溢流都有明确去向。","parameters":[],"cycle":null,"sections":[{"title":"开始前与操作","items":["清理集水面和落水管，装拦叶网；确认桶盖、溢流与可清洗入口。","画出水源、阀门、过滤、出水和溢流的简图，标出能关闭和清洗的位置。"]},{"title":"日常照护与维护","items":["雨后查看杂物和水味，定期用掉存水，清洁时刷洗沉积物。","先用清水试运行，沿途查看漏水、堵塞和回流；记下正常水位或流量作为对照。"]},{"title":"异常先看这里","items":["水发臭或积泥明显时暂停使用并清洗；不把消毒剂随意倒进灌溉桶。"]},{"title":"检查提醒","items":["启用、清洗和长时间停用后都试运行；大雨、冰冻、停电后检查溢流和连接。"]}],"cautions":["储水不是饮用水处理；水电作业先断电，水箱和池面需防儿童及动物跌入。"],"sources":[{"title":"RHS · Collecting and storing water","url":"https://www.rhs.org.uk/garden-jobs/water-collecting-storing-and-using"}]}'::jsonb, '{"overview":"Intercept roof debris and provide clear storage and overflow routes.","parameters":[],"cycle":null,"sections":[{"title":"Start here","items":["Clean the catchment and gutter, fit a leaf screen, and check lid, overflow, and cleaning access.","Sketch the supply, valves, filters, outlets, and overflow; mark accessible shutoffs and cleaning points."]},{"title":"Routine care","items":["Inspect debris and odor after rain, use stored water regularly, and brush deposits during cleaning.","Test with clean water, check leaks, blockages, and backflow, and record normal level or flow for comparison."]},{"title":"If something changes","items":["Pause use and clean foul-smelling or muddy storage; do not casually add disinfectants to irrigation water."]},{"title":"When to check","items":["Test after commissioning, cleaning, and long shutdowns; check overflow and connections after rain, frost, or power loss."]}],"cautions":["Storage is not drinking-water treatment; isolate power for wet maintenance and protect tanks/ponds from falls by children and animals."],"sources":[{"title":"RHS · Collecting and storing water","url":"https://www.rhs.org.uk/garden-jobs/water-collecting-storing-and-using"}]}'::jsonb),
  ('insect_fish', 'preset', '蛤蜊', '{"overview":"食用名称不代表适合家庭水族，先确认盐度与滤食条件。","parameters":[],"cycle":null,"sections":[{"title":"开始前与操作","items":["确认是海水或汽水种及食物来源，没有匹配系统就不要临时放进淡水缸。","购买前确认准确种名、淡水或海水及是否需要陆地区；准备可独立观察的空间。"]},{"title":"日常照护与维护","items":["记录盐度、底床和开闭壳变化，按实际种类维持水流与饲料。","观察活动、摄食和躲藏点，清走剩食；更换水或添加药剂前先核对对该物种是否适用。"]},{"title":"异常先看这里","items":["长期闭壳或无反应先核对水体条件；饲养过的水族个体不作为食材。"]},{"title":"检查提醒","items":["新入缸、蜕壳或同伴数量变化后增加巡查，记录日期和所做调整。"]}],"cautions":["不要把清洁缸壁或吃残渣理解为不需要喂养，也不要放生或倾倒活体到自然水体。"],"sources":[{"title":"OATA · Freshwater aquarium care","url":"https://ornamentalfish.org/what-we-do/advice-information/care-sheets/caresheets-tropical-freshwater-fish/how-to-set-up-and-look-after-a-freshwater-tank-aquarium/"}]}'::jsonb, '{"overview":"An edible trade name does not establish aquarium suitability; confirm salinity and food.","parameters":[],"cycle":null,"sections":[{"title":"Start here","items":["Check marine/brackish identity and food; do not temporarily place unmatched animals in freshwater.","Confirm the species, freshwater/marine requirements, and any land area before purchase; prepare a separate observation space."]},{"title":"Routine care","items":["Log salinity, substrate, and shell behavior and maintain species-specific flow and food.","Check activity, feeding, and hiding places and remove leftovers; verify species suitability before water additives or medication."]},{"title":"If something changes","items":["For prolonged closure or no response, check conditions first; do not eat aquarium-kept animals."]},{"title":"When to check","items":["Increase checks after introduction, molts, or changes in companions; record dates and adjustments."]}],"cautions":["Grazing algae or scraps does not mean no feeding is needed; never release animals into natural water."],"sources":[{"title":"OATA · Freshwater aquarium care","url":"https://ornamentalfish.org/what-we-do/advice-information/care-sheets/caresheets-tropical-freshwater-fish/how-to-set-up-and-look-after-a-freshwater-tank-aquarium/"}]}'::jsonb),
  ('system', 'preset', '爬藤架', '{"overview":"按成株、果实和大风后的负荷选架，不按幼苗重量选。","parameters":[],"cycle":null,"sections":[{"title":"开始前与操作","items":["立柱和横杆固定后再引蔓，用柔软绑带留出茎增粗空间。","按产品说明核对满载重量、连接件和固定方式；先空载装好，再分次放入湿土或花盆。"]},{"title":"日常照护与维护","items":["把新蔓分散引上架，及时松开勒茎绑带，保留采收通道。","浇水后检查支脚、接缝和地面积水；固定同一角度拍照，便于发现歪斜和下沉。"]},{"title":"异常先看这里","items":["倾斜、根部松土或枝蔓集中一侧时先减轻局部负荷并重新固定。"]},{"title":"检查提醒","items":["增加花盆、移动位置和大风后重新检查；发现松动先卸载再修复。"]}],"cautions":["阳台、屋顶和悬挂设施的承重不能靠目测确认；不明承重时先让专业人员核实。"],"sources":[]}'::jsonb, '{"overview":"Size the support for mature growth, fruit, and wind, not seedlings.","parameters":[],"cycle":null,"sections":[{"title":"Start here","items":["Secure posts and rails before training vines; use soft ties with room for stems to thicken.","Check the product''s loaded-weight rating, fasteners, and anchoring; assemble empty and add wet soil or pots in stages."]},{"title":"Routine care","items":["Spread new growth, loosen constricting ties, and keep harvest access.","After watering, inspect feet, joints, and standing water; repeat photos from one angle to reveal tilt or settlement."]},{"title":"If something changes","items":["For tilt, loose post soil, or one-sided growth, reduce local load and secure the structure."]},{"title":"When to check","items":["Recheck after adding pots, moving, or strong wind; unload a loose structure before repair."]}],"cautions":["Balcony, roof, and hanging loads cannot be judged by appearance; obtain a qualified assessment where capacity is unknown."],"sources":[]}'::jsonb),
  ('insect_fish', 'preset', '绿菊', '{"overview":"细裂叶容易夹碎屑，修剪与水流检查要一起做。","parameters":[{"label":"光照","value":"中光"},{"label":"参考水温范围","value":"水温待确认"},{"label":"生长方式","value":"茎草"},{"label":"难度","value":"容易"}],"cycle":null,"sections":[{"title":"开始前与操作","items":["保留健康茎顶，分根茎定植，让每丛周围能流通水。","保留购买标签或学名；清除运输包装，先把种植位置和入缸状态拍下来。"]},{"title":"日常照护与维护","items":["轻轻移除缠叶杂物，剪下健康顶枝补植，捞清断叶。","每周同角度拍新芽和老叶；修剪后捞净碎叶，记下光照、施肥或换水的单项变化。"]},{"title":"异常先看这里","items":["下部叶片大量脱落时查光是否被挡及根茎是否被压伤。"]},{"title":"检查提醒","items":["刚定植时先检查是否松脱；修剪、移动灯具或换水后，连续观察新叶而不只看旧叶。"]}],"cautions":["俗名可能对应不同物种；不要凭名称套用统一水温。修剪物不要丢进河道或户外水体。"],"sources":[{"title":"Tropica · Planting in the aquarium","url":"https://tropica.com/en/guide/get-the-right-start/planting/"}]}'::jsonb, '{"overview":"Fine divided leaves trap debris; combine pruning with flow checks.","parameters":[{"label":"Light","value":"Medium light"},{"label":"Reference water-temperature range","value":"Range unverified"},{"label":"Growth form","value":"Stem plant"},{"label":"Difficulty","value":"Easy"}],"cycle":null,"sections":[{"title":"Start here","items":["Keep healthy tops and space stems so water can move between them.","Keep the label or scientific name, remove transport packaging, and photograph the planting position and arrival condition."]},{"title":"Routine care","items":["Gently clear caught debris, replant healthy tops, and collect shed leaves.","Photograph new and old leaves weekly; remove pruning debris and log individual changes in light, nutrients, or water."]},{"title":"If something changes","items":["For heavy lower-leaf loss, inspect shading and damaged or compressed stem bases."]},{"title":"When to check","items":["Check for loose plants after planting; following pruning, light changes, or water changes, track new growth as well as old leaves."]}],"cautions":["Trade names can cover different species; do not assume one temperature from a name. Keep trimmings out of natural waterways."],"sources":[{"title":"Tropica · Planting in the aquarium","url":"https://tropica.com/en/guide/get-the-right-start/planting/"}]}'::jsonb),
  ('system', 'preset', '覆盖与秸秆还田', '{"overview":"地表覆盖和翻埋秸秆分开管理。家庭菜地可先用地表覆盖，减少一次翻入大量新鲜秸秆。","parameters":[{"label":"覆盖参考","value":"适宜地块约5–7.5厘米，避开茎基"},{"label":"材料检查","value":"无种籽、污染和疑似除草剂残留"}],"cycle":null,"sections":[{"title":"铺设与还田","items":["先除草，确认土壤湿润但不积水；铺碎秸秆或其他适宜有机覆盖物，给茎基、幼苗和播种行留空。","若要翻入秸秆，先剪碎、少量试验并留分解期；新鲜高碳材料混入土中可能暂时影响氮供应，不据此盲目追肥。"]},{"title":"日常检查","items":["浇水后掀开一角，确认水已到土层；久湿、结毡或茎基发软时减少覆盖并改善通气。","雨后查看蛞蝓、蜗牛与幼苗缺口；按分解和沉降补料，不把覆盖层越堆越高。"]}],"cautions":["持续积水、幼苗密集或茎叶怕潮的地块不直接套用厚度；带病或受除草剂污染的秸秆不用。"],"sources":[{"title":"RHS · Mulches and mulching","url":"https://www.rhs.org.uk/soil-composts-mulches/mulch"},{"title":"RHS · Using organic matter","url":"https://www.rhs.org.uk/soil-composts-mulches/organic-matter-how-to-use-in-garden"}]}'::jsonb, '{"overview":"Manage surface mulch separately from incorporated straw. Start with surface cover rather than burying large amounts of fresh straw at once.","parameters":[{"label":"Mulch reference","value":"About 5–7.5 cm where suitable; keep clear of stems"},{"label":"Material check","value":"No viable weed seed or suspect chemical residues"}],"cycle":null,"sections":[{"title":"Apply and return","items":["Weed first and check soil is moist, not saturated. Spread chopped straw or suitable organic mulch, leaving stems, seedlings, and sowing rows clear.","For incorporation, chop, trial a small amount, and allow decomposition. Fresh carbon-rich material may temporarily affect nitrogen availability; do not fertilize blindly."]},{"title":"Check the bed","items":["Lift a corner after watering to check the soil received water. Reduce matted or persistently wet cover and improve air around softening stems.","After rain, inspect for slugs and seedling damage. Top up for decomposition and settling rather than accumulating ever-deeper layers."]}],"cautions":["Do not apply the reference thickness blindly to waterlogged beds, dense seedlings, or moisture-sensitive crowns. Exclude diseased or herbicide-contaminated straw."],"sources":[{"title":"RHS · Mulches and mulching","url":"https://www.rhs.org.uk/soil-composts-mulches/mulch"},{"title":"RHS · Using organic matter","url":"https://www.rhs.org.uk/soil-composts-mulches/organic-matter-how-to-use-in-garden"}]}'::jsonb),
  ('other', 'preset', '豆瓣酱', '{"overview":"豆料制曲与后续酱醅发酵不能省略关键比例和温度控制。","parameters":[],"cycle":null,"sections":[{"title":"开始前与操作","items":["确定豆、辣椒、盐和菌种的验证配方，原料清理与接种工具分开。","开始前要有适用于该食品的明确菌种和经过验证的完整工艺；记录盐量、温度与容器，不凭口味减盐。"]},{"title":"日常照护与维护","items":["逐项记录投料重量和翻动时间，容器防虫防污染，按工艺管理液面。","每次检查先清洁工具；按原工艺管理液面、通气和温度，不边做边更换配方。"]},{"title":"异常先看这里","items":["用晒太阳、加盐或去霉覆盖过程失控并不可靠；有疑问不作为可食成品。"]},{"title":"检查提醒","items":["关键温度、时间或配比失控就停止作为可食用成品使用；不要把补盐、再煮或挑掉霉点当作补救。"]}],"cautions":["此页用于操作前核查和过程记录，不构成家庭自然发酵配方；缺少可靠工艺时选择有资质来源的成品。"],"sources":[{"title":"NCHFP · Fermentation controls","url":"https://nchfp.uga.edu/how/ferment/general-information-on-fermenting/"},{"title":"Centre for Food Safety · Safe bean-curd preparation","url":"https://www.cfs.gov.hk/english/multimedia/multimedia_pub/multimedia_pub_fsf_239_02.html"}]}'::jsonb, '{"overview":"Bean culturing and mash fermentation require the specified proportions and temperature controls.","parameters":[],"cycle":null,"sections":[{"title":"Start here","items":["Choose a validated bean/chili/salt/culture recipe and separate raw preparation from inoculation tools.","Start only with an identified culture and a validated process for that food; record salt, temperature, and vessel, and do not reduce salt by taste."]},{"title":"Routine care","items":["Log ingredient weights and mixing times, exclude insects/contamination, and manage the surface as specified.","Clean tools before checks and manage liquid level, aeration, and temperature according to the original method rather than changing recipes mid-process."]},{"title":"If something changes","items":["Sun, extra salt, or mold removal cannot validate a failed process; do not treat a questionable batch as edible."]},{"title":"When to check","items":["If critical time, temperature, or proportions fail, stop treating the batch as edible; extra salt, reheating, or removing mold is not a validated rescue."]}],"cautions":["This is a preparation and process-check guide, not a spontaneous-fermentation recipe; choose a reputable finished product if a reliable process is unavailable."],"sources":[{"title":"NCHFP · Fermentation controls","url":"https://nchfp.uga.edu/how/ferment/general-information-on-fermenting/"},{"title":"Centre for Food Safety · Safe bean-curd preparation","url":"https://www.cfs.gov.hk/english/multimedia/multimedia_pub/multimedia_pub_fsf_239_02.html"}]}'::jsonb),
  ('insect_fish', 'preset', '鸽子', '{"overview":"饲养鸽与野外观察分开，重点保证饮水、通风和稳定休息位置。","parameters":[],"cycle":null,"sections":[{"title":"开始前与操作","items":["饲养需确认来源，准备易清洗饮水器、稳定栖位和独立观察区。","确认品种、成年体型和原来的食物；安排安静观察区及可安全活动的空间。"]},{"title":"日常照护与维护","items":["清理粪便，观察每只是否采食与行走正常，不让弱鸟长期抢不到食。","每天清洗饮水器，查看食量、粪便和站姿；清洁时检查栖架、门扣和可误食小件。"]},{"title":"异常先看这里","items":["歪头、站立不稳或呼吸异常及时联系鸟类兽医，不自行把多种药混入饮水。"]},{"title":"检查提醒","items":["换食物逐步进行并称量摄食；持续蓬羽、呼吸困难或突然不进食应尽快联系鸟类兽医。"]}],"cautions":["不要靠抓握或限制饮食纠正行为；避免厨房烟气、开放窗户和宠物接触风险。"],"sources":[{"title":"RSPCA · Caring for exotic pets","url":"https://www.rspca.org.uk/adviceandwelfare/pets/other"}]}'::jsonb, '{"overview":"Separate kept pigeons from wildlife observation and prioritize water, airflow, and stable roosts.","parameters":[],"cycle":null,"sections":[{"title":"Start here","items":["Confirm lawful sourcing and provide cleanable drinkers, stable perches, and separate observation space.","Confirm species, adult size, and previous diet; prepare a quiet observation area and safe activity space."]},{"title":"Routine care","items":["Clear droppings and check each bird''s feeding/gait and access for weaker birds.","Clean drinkers and check intake, droppings, and posture daily; inspect perches, latches, and swallowable parts."]},{"title":"If something changes","items":["Head tilt, imbalance, or abnormal breathing needs avian-vet advice, not multiple drugs mixed into water."]},{"title":"When to check","items":["Change diet gradually while measuring intake; persistent fluffed posture, breathing difficulty, or sudden appetite loss needs prompt avian-vet advice."]}],"cautions":["Do not use force or food deprivation to correct behavior; avoid kitchen fumes, open-window escapes, and unsafe pet contact."],"sources":[{"title":"RSPCA · Caring for exotic pets","url":"https://www.rspca.org.uk/adviceandwelfare/pets/other"}]}'::jsonb),
  ('insect_fish', 'preset', '面包虫', '{"overview":"把幼虫、蛹和成虫阶段分清，控制潮湿与霉变。","parameters":[],"cycle":null,"sections":[{"title":"开始前与操作","items":["使用来源明确的饲养个体和合适干燥基料，准备通风防逃容器。","拍下成体或幼体特征、发现植物和日期，先确认对象及生活阶段。"]},{"title":"日常照护与维护","items":["少量供应所需湿料，及时撤去发霉或变质部分，记录各阶段数量。","用短时观察代替频繁翻动，记录取食、蜕变和所处植物；及时清除饲养容器中的腐败物。"]},{"title":"异常先看这里","items":["大量黑死或螨虫出现先停止扩大饲养，隔离问题容器并检查湿度与食物。"]},{"title":"检查提醒","items":["蜕皮、化蛹或羽化前后减少触碰；变化当天拍照记录，而非按固定天数催促。"]}],"cautions":["不能可靠识别、有毒或有蜇伤风险的种类以远距离观察为主；不跨地区释放饲养个体。"],"sources":[{"title":"RHS · Wildlife in gardens","url":"https://www.rhs.org.uk/wildlife/in-gardens"}]}'::jsonb, '{"overview":"Separate larvae, pupae, and adults in your records and control dampness and mold.","parameters":[],"cycle":null,"sections":[{"title":"Start here","items":["Use traceable stock, appropriate dry medium, and a ventilated secure container.","Photograph identifying features, host plant, and date; establish the organism and life stage first."]},{"title":"Routine care","items":["Provide needed moist food sparingly, remove spoilage, and count life stages.","Use brief observation instead of repeated disturbance; log feeding, molts, and host plants and remove decaying material from kept enclosures."]},{"title":"If something changes","items":["For mass darkening/deaths or mites, stop expansion, isolate the problem container, and inspect moisture and food."]},{"title":"When to check","items":["Minimize handling around molts, pupation, and emergence; record the actual change rather than forcing a calendar."]}],"cautions":["Observe unidentified, venomous, or stinging organisms from a distance; do not release captive individuals in other regions."],"sources":[{"title":"RHS · Wildlife in gardens","url":"https://www.rhs.org.uk/wildlife/in-gardens"}]}'::jsonb),
  ('insect_fish', 'preset', '椒草', '{"overview":"定植后重在保持位置稳定，并观察叶心是否继续长新叶。","parameters":[{"label":"光照","value":"弱至中光"},{"label":"参考水温范围","value":"20–28℃","note":"资料所列范围，并非全程最适温度。"},{"label":"生长方式","value":"扎根"},{"label":"难度","value":"中等"}],"cycle":null,"sections":[{"title":"开始前与操作","items":["把根种入底床，叶心留在表面；同株旧叶状态先拍照留作对比。","保留购买标签或学名；清除运输包装，先把种植位置和入缸状态拍下来。"]},{"title":"日常照护与维护","items":["清除已经软烂的叶片，避免反复拔起检查根系。","每周同角度拍新芽和老叶；修剪后捞净碎叶，记下光照、施肥或换水的单项变化。"]},{"title":"异常先看这里","items":["旧叶消融不等于整株死亡；检查叶心和根，再决定是否移除。"]},{"title":"检查提醒","items":["刚定植时先检查是否松脱；修剪、移动灯具或换水后，连续观察新叶而不只看旧叶。"]}],"cautions":["俗名可能对应不同物种；不要凭名称套用统一水温。修剪物不要丢进河道或户外水体。","水温参考品种：Cryptocoryne wendtii ''Green''，20–28℃。这是资料所列范围，并非整段都是最适温度；同名水草可能不是同一品种，不要据此骤升骤降水温。"],"sources":[{"title":"Tropica · Planting in the aquarium","url":"https://tropica.com/en/guide/get-the-right-start/planting/"},{"title":"Dennerle — Cryptocoryne wendtii ''Green''","url":"https://dennerleplants.com/en/plants/plantdetails/Cryptocoryne-wendtii-%27Green%27-%28411%29/27846"}]}'::jsonb, '{"overview":"Keep Cryptocoryne settled and track new leaves from the crown.","parameters":[{"label":"Light","value":"Low to medium"},{"label":"Reference water-temperature range","value":"20–28°C","note":"Published range, not an optimum throughout."},{"label":"Growth form","value":"Rooted"},{"label":"Difficulty","value":"Moderate"}],"cycle":null,"sections":[{"title":"Start here","items":["Plant roots in the substrate with the crown exposed and photograph old leaves.","Keep the label or scientific name, remove transport packaging, and photograph the planting position and arrival condition."]},{"title":"Routine care","items":["Remove fully decayed leaves without repeatedly uprooting the plant.","Photograph new and old leaves weekly; remove pruning debris and log individual changes in light, nutrients, or water."]},{"title":"If something changes","items":["Old-leaf melt is not proof of whole-plant death; inspect the crown and roots first."]},{"title":"When to check","items":["Check for loose plants after planting; following pruning, light changes, or water changes, track new growth as well as old leaves."]}],"cautions":["Trade names can cover different species; do not assume one temperature from a name. Keep trimmings out of natural waterways.","Temperature reference: Cryptocoryne wendtii ''Green'', 20–28°C. This is a published range, not an ideal setpoint or permission for sudden temperature changes; other species sold under this common name may differ."],"sources":[{"title":"Tropica · Planting in the aquarium","url":"https://tropica.com/en/guide/get-the-right-start/planting/"},{"title":"Dennerle — Cryptocoryne wendtii ''Green''","url":"https://dennerleplants.com/en/plants/plantdetails/Cryptocoryne-wendtii-%27Green%27-%28411%29/27846"}]}'::jsonb),
  ('insect_fish', 'preset', '水晶虾', '{"overview":"先核对具体品系的水质需求，稳定比频繁纠偏更重要。","parameters":[],"cycle":null,"sections":[{"title":"开始前与操作","items":["记录来源水条件，准备匹配的饲养水与检测工具，谨慎安排适应过程。","购买前确认准确种名、淡水或海水及是否需要陆地区；准备可独立观察的空间。"]},{"title":"日常照护与维护","items":["记录每次补水和换水，观察蜕壳及抱卵，不同时更换底床和滤材。","观察活动、摄食和躲藏点，清走剩食；更换水或添加药剂前先核对对该物种是否适用。"]},{"title":"异常先看这里","items":["接连蜕壳失败或死亡时先停新增，核对变化记录并请专业人员判断。"]},{"title":"检查提醒","items":["新入缸、蜕壳或同伴数量变化后增加巡查，记录日期和所做调整。"]}],"cautions":["不要把清洁缸壁或吃残渣理解为不需要喂养，也不要放生或倾倒活体到自然水体。"],"sources":[{"title":"OATA · Freshwater aquarium care","url":"https://ornamentalfish.org/what-we-do/advice-information/care-sheets/caresheets-tropical-freshwater-fish/how-to-set-up-and-look-after-a-freshwater-tank-aquarium/"}]}'::jsonb, '{"overview":"Confirm the strain''s water needs and prioritize stability over repeated corrections.","parameters":[],"cycle":null,"sections":[{"title":"Start here","items":["Record source-water conditions and prepare matching water, tests, and an appropriate acclimation plan.","Confirm the species, freshwater/marine requirements, and any land area before purchase; prepare a separate observation space."]},{"title":"Routine care","items":["Log top-ups/changes and observe molts and eggs; avoid changing substrate and filter media together.","Check activity, feeding, and hiding places and remove leftovers; verify species suitability before water additives or medication."]},{"title":"If something changes","items":["For repeated molt failures or deaths, stop additions, review changes, and seek specialist advice."]},{"title":"When to check","items":["Increase checks after introduction, molts, or changes in companions; record dates and adjustments."]}],"cautions":["Grazing algae or scraps does not mean no feeding is needed; never release animals into natural water."],"sources":[{"title":"OATA · Freshwater aquarium care","url":"https://ornamentalfish.org/what-we-do/advice-information/care-sheets/caresheets-tropical-freshwater-fish/how-to-set-up-and-look-after-a-freshwater-tank-aquarium/"}]}'::jsonb),
  ('system', 'preset', '水循环过滤', '{"overview":"先去除固体杂物，再让生物过滤稳定工作，清洁不等于全部换新。","parameters":[],"cycle":null,"sections":[{"title":"开始前与操作","items":["按设备说明排布过滤材料，标记正常流量和水位，确认进出水不会短路。","画出水源、阀门、过滤、出水和溢流的简图，标出能关闭和清洗的位置。"]},{"title":"日常照护与维护","items":["先清机械拦污层；生物滤材按系统要求维护，避免一次全换并同时大量增鱼。","先用清水试运行，沿途查看漏水、堵塞和回流；记下正常水位或流量作为对照。"]},{"title":"异常先看这里","items":["流量下降查堵塞与泵；氨或亚硝酸盐异常时暂停增养，检查循环并寻求水族专业建议。"]},{"title":"检查提醒","items":["启用、清洗和长时间停用后都试运行；大雨、冰冻、停电后检查溢流和连接。"]}],"cautions":["储水不是饮用水处理；水电作业先断电，水箱和池面需防儿童及动物跌入。"],"sources":[{"title":"RHS · Collecting and storing water","url":"https://www.rhs.org.uk/garden-jobs/water-collecting-storing-and-using"},{"title":"OATA · Freshwater aquarium care","url":"https://ornamentalfish.org/what-we-do/advice-information/care-sheets/caresheets-tropical-freshwater-fish/how-to-set-up-and-look-after-a-freshwater-tank-aquarium/"}]}'::jsonb, '{"overview":"Remove solids first and preserve biological filtration; cleaning is not replacing everything.","parameters":[],"cycle":null,"sections":[{"title":"Start here","items":["Arrange media as specified, mark normal flow/levels, and check that inlet and outlet do not short-circuit.","Sketch the supply, valves, filters, outlets, and overflow; mark accessible shutoffs and cleaning points."]},{"title":"Routine care","items":["Clean mechanical capture first; maintain biological media for the system and avoid replacing all of it while increasing stock.","Test with clean water, check leaks, blockages, and backflow, and record normal level or flow for comparison."]},{"title":"If something changes","items":["For low flow check clogs/pump; abnormal ammonia or nitrite means stop stocking and seek aquatic advice."]},{"title":"When to check","items":["Test after commissioning, cleaning, and long shutdowns; check overflow and connections after rain, frost, or power loss."]}],"cautions":["Storage is not drinking-water treatment; isolate power for wet maintenance and protect tanks/ponds from falls by children and animals."],"sources":[{"title":"RHS · Collecting and storing water","url":"https://www.rhs.org.uk/garden-jobs/water-collecting-storing-and-using"},{"title":"OATA · Freshwater aquarium care","url":"https://ornamentalfish.org/what-we-do/advice-information/care-sheets/caresheets-tropical-freshwater-fish/how-to-set-up-and-look-after-a-freshwater-tank-aquarium/"}]}'::jsonb),
  ('insect_fish', 'preset', '龟', '{"overview":"先分清水龟、半水龟或陆龟；三者不能共用一套温度、水深和食谱。","parameters":[],"cycle":null,"sections":[{"title":"开始前与操作","items":["水龟准备能完全离水的干燥晒背处和安全出水坡；陆龟则先核对陆地基质、躲藏和活动区。","在动物实际停留处测量温度；加热设备用合适的温控和防接触保护，不只读房间温度。"]},{"title":"日常照护与维护","items":["按已确认物种安排UVB与温度梯度；逐项检查晒背、进食、排泄和壳体照片。","每天检查饮水、排泄、活动与设备；换灯或移动晒台后重新测量，不照搬旧距离。"]},{"title":"异常先看这里","items":["歪浮、张口呼吸、眼肿或壳体软烂时及时就医，不用统一盐浴或晒太阳代替治疗。"]},{"title":"检查提醒","items":["保留设备说明、灯具启用日期和体重趋势；换季先复核种类需要，不自行安排冬眠。"]}],"cautions":["先确定物种再选食物、温度和UVB方案；呼吸异常、持续拒食或外伤需异宠兽医，指引不提供用药剂量。"],"sources":[{"title":"RSPCA · Caring for exotic pets","url":"https://www.rspca.org.uk/adviceandwelfare/pets/other"},{"title":"RSPCA · Terrapin care","url":"https://www.rspca.org.uk/adviceandwelfare/pets/other/terrapin"}]}'::jsonb, '{"overview":"Identify aquatic, semi-aquatic, or terrestrial turtles/tortoises; depth, diet, and temperatures differ.","parameters":[],"cycle":null,"sections":[{"title":"Start here","items":["For aquatic turtles provide a fully dry basking site and safe exit; for tortoises review terrestrial substrate, shelter, and space.","Measure where the animal actually rests; use suitable thermostats and contact guards, not room temperature alone."]},{"title":"Routine care","items":["Set UVB and temperature gradients for the identified species and track basking, food, droppings, and shell photos.","Check water, droppings, behavior, and equipment daily; remeasure after moving a basking site or replacing a lamp."]},{"title":"If something changes","items":["Abnormal floating, open-mouth breathing, swollen eyes, or shell decay needs veterinary care, not a universal salt bath or sun remedy."]},{"title":"When to check","items":["Keep equipment instructions, lamp start dates, and weight trends; review species needs seasonally rather than initiating hibernation yourself."]}],"cautions":["Identify the species before choosing food, temperatures, or UVB; breathing problems, persistent refusal to eat, or injuries need an exotics vet. No drug doses are supplied here."],"sources":[{"title":"RSPCA · Caring for exotic pets","url":"https://www.rspca.org.uk/adviceandwelfare/pets/other"},{"title":"RSPCA · Terrapin care","url":"https://www.rspca.org.uk/adviceandwelfare/pets/other/terrapin"}]}'::jsonb),
  ('insect_fish', 'preset', '鸡', '{"overview":"从干燥鸡舍、完整饲料和每日清点开始，兼顾群体内的弱鸡。","parameters":[],"cycle":null,"sections":[{"title":"开始前与操作","items":["按雏鸡或成鸡阶段准备饲料及保温方案，检查每只都能取水。","按年龄选择完整饲料，设置每只都能到达的饮水和进食位置；新来个体先单独观察。"]},{"title":"日常照护与维护","items":["投喂时逐只看精神、鸡冠和行走，及时收蛋并检查啄伤。","每天查水和采食，移走湿垫料；黄昏清点并关好舍门，记录产蛋和异常粪便。"]},{"title":"异常先看这里","items":["某只长期被赶、缩头不动或不采食时先安排单独安全观察并咨询兽医。"]},{"title":"检查提醒","items":["高温、换羽、转群和饲料变更时增加巡查；准备离家期间的照护交接。"]}],"cautions":["呼吸困难、多只同时发病或突然死亡应及时联系兽医；不凭网上配方给整群用药。"],"sources":[{"title":"UMN Extension · Raising chickens","url":"https://extension.umn.edu/agriculture/animals-and-livestock/poultry/raising-chickens-for-eggs"}]}'::jsonb, '{"overview":"Start with dry housing, complete feed, and daily counts, including weaker flock members.","parameters":[],"cycle":null,"sections":[{"title":"Start here","items":["Prepare feed and heating for chicks/adults and verify every bird can reach water.","Use a complete age-appropriate feed, accessible feeding/watering points, and separate observation for newcomers."]},{"title":"Routine care","items":["Inspect alertness, comb, gait, eggs, and peck injuries during routine visits.","Check water and feed daily, remove wet bedding, count and secure birds at dusk, and log eggs and unusual droppings."]},{"title":"If something changes","items":["Persistent exclusion, huddling, or appetite loss needs safe separate observation and veterinary advice."]},{"title":"When to check","items":["Increase checks during heat, molting, flock moves, and feed changes; arrange care before travel."]}],"cautions":["Breathing difficulty, multiple sick birds, or sudden deaths need veterinary help; do not medicate a flock from an unverified recipe."],"sources":[{"title":"UMN Extension · Raising chickens","url":"https://extension.umn.edu/agriculture/animals-and-livestock/poultry/raising-chickens-for-eggs"}]}'::jsonb),
  ('insect_fish', 'preset', '金鱼', '{"overview":"用能容纳成鱼的过滤水体饲养，不把小圆缸当长期空间。","parameters":[],"cycle":null,"sections":[{"title":"开始前与操作","items":["先核对品种成年体型和现有水体，准备宽敞游动区与安全装饰。","入鱼前用检测确认过滤系统能处理氨和亚硝酸盐，不以水清或开机天数代替检测。"]},{"title":"日常照护与维护","items":["按实际摄食分次少量投喂，清走残饵，观察排泄和游姿。","每天先观察呼吸、游姿和摄食再投喂；记下剩饵和换水量，换水时匹配新水条件。"]},{"title":"异常先看这里","items":["浮头、侧游或突然夹鳍时立即测水并检查增氧，不先按外观猜病用药。"]},{"title":"检查提醒","items":["新入鱼、过滤维护或停电后增加水质检查；离家前确认有人能查看设备和动物。"]}],"cautions":["异常先查水质和设备；持续呼吸困难、损伤或不进食应联系水生动物兽医，不混用药物试错。"],"sources":[{"title":"OATA · Freshwater aquarium care","url":"https://ornamentalfish.org/what-we-do/advice-information/care-sheets/caresheets-tropical-freshwater-fish/how-to-set-up-and-look-after-a-freshwater-tank-aquarium/"}]}'::jsonb, '{"overview":"Use a filtered system sized for adult goldfish, not a bowl as a permanent home.","parameters":[],"cycle":null,"sections":[{"title":"Start here","items":["Check adult size and system capacity and provide swimming space and safe decor.","Before stocking, use tests to confirm the filter handles ammonia and nitrite; clear water or elapsed days are not proof."]},{"title":"Routine care","items":["Offer small portions based on intake, remove leftovers, and observe waste and swimming.","Observe breathing, swimming, and appetite before feeding; log leftovers and water changes and match replacement-water conditions."]},{"title":"If something changes","items":["For gasping, sideways swimming, or clamped fins, test water and aeration before guessing a disease."]},{"title":"When to check","items":["Increase water checks after additions, filter work, or power loss; arrange equipment and animal checks before travel."]}],"cautions":["Check water and equipment first; persistent breathing difficulty, injury, or refusal to feed needs aquatic-veterinary advice, not mixed treatments."],"sources":[{"title":"OATA · Freshwater aquarium care","url":"https://ornamentalfish.org/what-we-do/advice-information/care-sheets/caresheets-tropical-freshwater-fish/how-to-set-up-and-look-after-a-freshwater-tank-aquarium/"}]}'::jsonb),
  ('insect_fish', 'preset', '蜥蜴', '{"overview":"树栖、地栖、植食和虫食种差异大，先用准确种名建立照护记录。","parameters":[],"cycle":null,"sections":[{"title":"开始前与操作","items":["按物种安排攀爬或地面空间，确认晒点、躲藏和食谱，不用单一虫料通喂。","在动物实际停留处测量温度；加热设备用合适的温控和防接触保护，不只读房间温度。"]},{"title":"日常照护与维护","items":["核对设备实际运行，观察抓握、步态、尾部和粪便，定期留体重记录。","每天检查饮水、排泄、活动与设备；换灯或移动晒台后重新测量，不照搬旧距离。"]},{"title":"异常先看这里","items":["无力、跛行、持续闭眼或拒食时检查条件并就医，不自行猛补维生素。"]},{"title":"检查提醒","items":["保留设备说明、灯具启用日期和体重趋势；换季先复核种类需要，不自行安排冬眠。"]}],"cautions":["先确定物种再选食物、温度和UVB方案；呼吸异常、持续拒食或外伤需异宠兽医，指引不提供用药剂量。"],"sources":[{"title":"RSPCA · Caring for exotic pets","url":"https://www.rspca.org.uk/adviceandwelfare/pets/other"}]}'::jsonb, '{"overview":"Arboreal, terrestrial, plant-eating, and insect-eating lizards need species-specific care.","parameters":[],"cycle":null,"sections":[{"title":"Start here","items":["Provide suitable climbing/ground space, basking, hides, and diet rather than feeding every species one insect food.","Measure where the animal actually rests; use suitable thermostats and contact guards, not room temperature alone."]},{"title":"Routine care","items":["Verify equipment and observe grip, gait, tail, and droppings with periodic weight records.","Check water, droppings, behavior, and equipment daily; remeasure after moving a basking site or replacing a lamp."]},{"title":"If something changes","items":["Weakness, limping, persistently closed eyes, or refusal to eat needs checks and veterinary advice, not vitamin megadoses."]},{"title":"When to check","items":["Keep equipment instructions, lamp start dates, and weight trends; review species needs seasonally rather than initiating hibernation yourself."]}],"cautions":["Identify the species before choosing food, temperatures, or UVB; breathing problems, persistent refusal to eat, or injuries need an exotics vet. No drug doses are supplied here."],"sources":[{"title":"RSPCA · Caring for exotic pets","url":"https://www.rspca.org.uk/adviceandwelfare/pets/other"}]}'::jsonb),
  ('insect_fish', 'preset', '金鱼藻', '{"overview":"可先漂浮观察，避免把脆弱茎段深压进底床。","parameters":[{"label":"光照","value":"弱至中光"},{"label":"参考水温范围","value":"1–28℃","note":"资料所列范围，并非全程最适温度。"},{"label":"生长方式","value":"漂浮"},{"label":"难度","value":"容易"}],"cycle":null,"sections":[{"title":"开始前与操作","items":["将健康茎段放在可获得光的位置，避免堵住进水口。","保留购买标签或学名；清除运输包装，先把种植位置和入缸状态拍下来。"]},{"title":"日常照护与维护","items":["控制漂浮量，给下层草留光，捞去断落细叶。","每周同角度拍新芽和老叶；修剪后捞净碎叶，记下光照、施肥或换水的单项变化。"]},{"title":"异常先看这里","items":["大量掉叶时回查水体、光照和运输后的变化，先清掉残叶防积污。"]},{"title":"检查提醒","items":["刚定植时先检查是否松脱；修剪、移动灯具或换水后，连续观察新叶而不只看旧叶。"]}],"cautions":["俗名可能对应不同物种；不要凭名称套用统一水温。修剪物不要丢进河道或户外水体。","水温参考品种：Ceratophyllum demersum，1–28℃。这是资料所列范围，并非整段都是最适温度；同名水草可能不是同一品种，不要据此骤升骤降水温。"],"sources":[{"title":"Tropica · Planting in the aquarium","url":"https://tropica.com/en/guide/get-the-right-start/planting/"},{"title":"Dennerle — Ceratophyllum demersum","url":"https://dennerleplants.com/en/plants/plantdetails/Ceratophyllumdemersum(764)/22989"}]}'::jsonb, '{"overview":"Start with floating growth rather than crushing delicate stems deep into substrate.","parameters":[{"label":"Light","value":"Low to medium"},{"label":"Reference water-temperature range","value":"1–28°C","note":"Published range, not an optimum throughout."},{"label":"Growth form","value":"Floating"},{"label":"Difficulty","value":"Easy"}],"cycle":null,"sections":[{"title":"Start here","items":["Place healthy stems in light without blocking intakes.","Keep the label or scientific name, remove transport packaging, and photograph the planting position and arrival condition."]},{"title":"Routine care","items":["Control floating cover to leave light below and remove shed fine leaves.","Photograph new and old leaves weekly; remove pruning debris and log individual changes in light, nutrients, or water."]},{"title":"If something changes","items":["For heavy shedding, review water, light, and transport changes and clear debris first."]},{"title":"When to check","items":["Check for loose plants after planting; following pruning, light changes, or water changes, track new growth as well as old leaves."]}],"cautions":["Trade names can cover different species; do not assume one temperature from a name. Keep trimmings out of natural waterways.","Temperature reference: Ceratophyllum demersum, 1–28°C. This is a published range, not an ideal setpoint or permission for sudden temperature changes; other species sold under this common name may differ."],"sources":[{"title":"Tropica · Planting in the aquarium","url":"https://tropica.com/en/guide/get-the-right-start/planting/"},{"title":"Dennerle — Ceratophyllum demersum","url":"https://dennerleplants.com/en/plants/plantdetails/Ceratophyllumdemersum(764)/22989"}]}'::jsonb),
  ('insect_fish', 'preset', '乌鸫', '{"overview":"落叶层和灌丛是观察翻找食物、停栖的重要位置。","parameters":[],"cycle":null,"sections":[{"title":"开始前与操作","items":["保留一处少打扰的落叶角落，从固定距离观察。","在原处选固定观察点，不抓捕、不搬巢，也不为了照片驱赶动物。"]},{"title":"日常照护与维护","items":["记录翻叶取食与洗浴，清洁水盆，减少地面施药。","记录时间、天气、数量与行为；保持观察距离，减少夜灯、噪声和宠物追逐。"]},{"title":"异常先看这里","items":["看到幼鸟藏在灌丛下先把宠物带离，再观察亲鸟是否回来。"]},{"title":"检查提醒","items":["繁殖或育幼期减少靠近；受伤个体先联系当地野生动物救助机构。"]}],"cautions":["不要把暂时停留或幼鸟离巢当作被遗弃；不强行喂水、喂奶或饲喂人类饭菜。"],"sources":[{"title":"RHS · Wildlife in gardens","url":"https://www.rhs.org.uk/wildlife/in-gardens"},{"title":"Cornell Lab · Window collisions and injured birds","url":"https://www.allaboutbirds.org/news/why-birds-hit-windows-and-how-you-can-help-prevent-it/"}]}'::jsonb, '{"overview":"Leaf litter and shrubs offer useful feeding and resting observations.","parameters":[],"cycle":null,"sections":[{"title":"Start here","items":["Retain a quiet leaf-litter corner and observe from a fixed distance.","Choose a fixed observation point in place; do not capture, move nests, or drive animals for a photo."]},{"title":"Routine care","items":["Log leaf-turning and bathing, clean water dishes, and reduce ground pesticide use.","Log time, weather, number, and behavior; keep distance and reduce night lighting, noise, and pet chasing."]},{"title":"If something changes","items":["For a young bird under shrubs, remove pets and watch for returning parents first."]},{"title":"When to check","items":["Increase distance during nesting or rearing; contact a local wildlife rehabilitator for injured animals."]}],"cautions":["Resting or fledging is not automatically abandonment; do not force water, milk, or human meals."],"sources":[{"title":"RHS · Wildlife in gardens","url":"https://www.rhs.org.uk/wildlife/in-gardens"},{"title":"Cornell Lab · Window collisions and injured birds","url":"https://www.allaboutbirds.org/news/why-birds-hit-windows-and-how-you-can-help-prevent-it/"}]}'::jsonb),
  ('insect_fish', 'preset', '角螺', '{"overview":"重点观察附着、刮食和壳体，进缸前确认实际食物来源。","parameters":[],"cycle":null,"sections":[{"title":"开始前与操作","items":["在已稳定的水族系统中安排可刮食表面，确认物种和防逃缝隙。","购买前确认准确种名、淡水或海水及是否需要陆地区；准备可独立观察的空间。"]},{"title":"日常照护与维护","items":["查看同一时段位置是否变化，检查壳口、玻璃和石面摄食痕。","观察活动、摄食和躲藏点，清走剩食；更换水或添加药剂前先核对对该物种是否适用。"]},{"title":"异常先看这里","items":["久不移动时先判断是否休息并测水，不频繁翻弄或持续往缸里加药。"]},{"title":"检查提醒","items":["新入缸、蜕壳或同伴数量变化后增加巡查，记录日期和所做调整。"]}],"cautions":["不要把清洁缸壁或吃残渣理解为不需要喂养，也不要放生或倾倒活体到自然水体。"],"sources":[{"title":"OATA · Freshwater aquarium care","url":"https://ornamentalfish.org/what-we-do/advice-information/care-sheets/caresheets-tropical-freshwater-fish/how-to-set-up-and-look-after-a-freshwater-tank-aquarium/"}]}'::jsonb, '{"overview":"Observe attachment, grazing, and shell condition and plan a real food supply.","parameters":[],"cycle":null,"sections":[{"title":"Start here","items":["Use an established system with grazing surfaces and check species and escape gaps.","Confirm the species, freshwater/marine requirements, and any land area before purchase; prepare a separate observation space."]},{"title":"Routine care","items":["Compare position at consistent times and inspect the shell opening and grazing tracks.","Check activity, feeding, and hiding places and remove leftovers; verify species suitability before water additives or medication."]},{"title":"If something changes","items":["For long inactivity, consider rest and test water instead of repeated handling or medication."]},{"title":"When to check","items":["Increase checks after introduction, molts, or changes in companions; record dates and adjustments."]}],"cautions":["Grazing algae or scraps does not mean no feeding is needed; never release animals into natural water."],"sources":[{"title":"OATA · Freshwater aquarium care","url":"https://ornamentalfish.org/what-we-do/advice-information/care-sheets/caresheets-tropical-freshwater-fish/how-to-set-up-and-look-after-a-freshwater-tank-aquarium/"}]}'::jsonb),
  ('insect_fish', 'preset', '海水鱼', '{"overview":"先确定鱼的种类及是否珊瑚缸，再安排设备与同伴。","parameters":[],"cycle":null,"sections":[{"title":"开始前与操作","items":["购买前核对成年体型、食性、领域性和跳缸风险，预留隔离观察条件。","用水族海盐配制新水，单独混匀并测盐度、水温；食盐水不能替代海水。"]},{"title":"日常照护与维护","items":["逐条确认摄食，不把无脊椎动物全部视为安全同伴；及时检查争斗。","区分蒸发补水与换水：按实际盐度纠偏，补蒸发水前先核对仪表和水位。"]},{"title":"异常先看这里","items":["盐度突变或多鱼同时异常时先复核检测与补水操作，停止新增生物。"]},{"title":"检查提醒","items":["每天看水位、循环和动物呼吸；换水或增加生物前后复测盐度和氮废物。"]}],"cautions":["珊瑚、鱼和无脊椎动物的兼容性需分别核对；不根据气泡或水色判断水质安全。"],"sources":[{"title":"OATA · Marine aquarium care","url":"https://ornamentalfish.org/what-we-do/advice-information/care-sheets/caresheets-marine-fish/how-to-set-up-and-look-after-a-marine-tank-aquarium/"}]}'::jsonb, '{"overview":"Choose species and fish-only versus reef setup before equipment and companions.","parameters":[],"cycle":null,"sections":[{"title":"Start here","items":["Check adult size, diet, territorial behavior, and jumping risk and plan separate observation.","Prepare replacement water separately with aquarium marine salt, then measure salinity and temperature; table salt is not a substitute."]},{"title":"Routine care","items":["Confirm each fish feeds and do not assume all invertebrates are compatible; inspect aggression.","Distinguish evaporation top-ups from water changes; check the instrument, level, and salinity before correction."]},{"title":"If something changes","items":["For salinity changes or several affected fish, verify tests/top-ups and stop adding livestock."]},{"title":"When to check","items":["Check level, circulation, and breathing daily; retest salinity and nitrogen waste around water changes and stocking."]}],"cautions":["Check compatibility separately for fish, corals, and invertebrates; bubbles or water color do not establish safety."],"sources":[{"title":"OATA · Marine aquarium care","url":"https://ornamentalfish.org/what-we-do/advice-information/care-sheets/caresheets-marine-fish/how-to-set-up-and-look-after-a-marine-tank-aquarium/"}]}'::jsonb),
  ('insect_fish', 'preset', '羊', '{"overview":"先分清绵羊或山羊，日粮、围栏和矿物补充不能直接照搬。","parameters":[],"cycle":null,"sections":[{"title":"开始前与操作","items":["确认种类、年龄与用途，核对草料和适用矿物料，准备干燥休息区。","按年龄、体况和繁殖阶段向当地兽医或饲养顾问确认日粮；新个体设独立观察区。"]},{"title":"日常照护与维护","items":["看反刍、食欲、步态与粪便，分别记录个体体况，不只看群体总采食。","每天实际检查饮水是否流出、食槽余量、粪便和行走；不要只记录已投了多少料。"]},{"title":"异常先看这里","items":["跛行、明显腹胀或持续离群时及时请兽医，不随意共用牛或马的矿物料。"]},{"title":"检查提醒","items":["高温、转栏、换料和临近生产时增加巡查；疫苗、驱虫及用药计划交由当地兽医制定。"]}],"cautions":["倒地、明显腹胀、呼吸困难或持续不采食应及时求助；大型动物操作需有安全退路。"],"sources":[{"title":"Merck Veterinary Manual · Copper sensitivity","url":"https://www.merckvetmanual.com/toxicology/copper-toxicosis/copper-toxicosis-in-animals"}]}'::jsonb, '{"overview":"Distinguish sheep from goats; ration, fencing, and mineral supplements differ.","parameters":[],"cycle":null,"sections":[{"title":"Start here","items":["Confirm species, age, and purpose and check forage/mineral suitability and dry resting space.","Confirm the ration for age, condition, and reproductive stage with a local vet or nutrition adviser; separate newcomers for observation."]},{"title":"Routine care","items":["Observe rumination, appetite, gait, and manure and record individual condition.","Check that water actually flows, inspect feed leftovers, manure, and gait daily, rather than recording only feed offered."]},{"title":"If something changes","items":["For lameness, bloating, or isolation, contact a vet; do not casually share cattle/horse mineral feeds."]},{"title":"When to check","items":["Increase checks during heat, moves, ration changes, and near birth; let a local vet set vaccination, parasite, and medicine plans."]}],"cautions":["Collapse, marked bloating, breathing difficulty, or persistent appetite loss needs prompt help; keep an escape route when handling large animals."],"sources":[{"title":"Merck Veterinary Manual · Copper sensitivity","url":"https://www.merckvetmanual.com/toxicology/copper-toxicosis/copper-toxicosis-in-animals"}]}'::jsonb),
  ('insect_fish', 'preset', '莫斯', '{"overview":"以附着成形和定期薄剪为主，不把整团厚压在底部。","parameters":[{"label":"光照","value":"弱至中光"},{"label":"参考水温范围","value":"22–28℃","note":"资料所列范围，并非全程最适温度。"},{"label":"生长方式","value":"附生"},{"label":"难度","value":"容易"}],"cycle":null,"sections":[{"title":"开始前与操作","items":["拆成薄小片固定在石木表面，检查线头和连接处不妨碍鱼虾。","保留购买标签或学名；清除运输包装，先把种植位置和入缸状态拍下来。"]},{"title":"日常照护与维护","items":["剪去过厚部分并吸走夹住的碎屑，保留能继续长出的绿色部分。","每周同角度拍新芽和老叶；修剪后捞净碎叶，记下光照、施肥或换水的单项变化。"]},{"title":"异常先看这里","items":["内部发黑或积脏先检查铺得过厚和水流死角。"]},{"title":"检查提醒","items":["刚定植时先检查是否松脱；修剪、移动灯具或换水后，连续观察新叶而不只看旧叶。"]}],"cautions":["俗名可能对应不同物种；不要凭名称套用统一水温。修剪物不要丢进河道或户外水体。","水温参考品种：Taxiphyllum barbieri，22–28℃。这是资料所列范围，并非整段都是最适温度；同名水草可能不是同一品种，不要据此骤升骤降水温。"],"sources":[{"title":"Tropica · Planting in the aquarium","url":"https://tropica.com/en/guide/get-the-right-start/planting/"},{"title":"Dennerle — Taxiphyllum barbieri","url":"https://dennerleplants.com/en/plants/plantdetails/Taxiphyllum-barbieri-%2830192%29/23040"}]}'::jsonb, '{"overview":"Grow a thin attached layer and trim instead of packing a thick clump.","parameters":[{"label":"Light","value":"Low to medium"},{"label":"Reference water-temperature range","value":"22–28°C","note":"Published range, not an optimum throughout."},{"label":"Growth form","value":"Epiphyte"},{"label":"Difficulty","value":"Easy"}],"cycle":null,"sections":[{"title":"Start here","items":["Attach small thin portions to hardscape and check ties do not trap animals.","Keep the label or scientific name, remove transport packaging, and photograph the planting position and arrival condition."]},{"title":"Routine care","items":["Thin dense growth and remove trapped debris while retaining healthy green parts.","Photograph new and old leaves weekly; remove pruning debris and log individual changes in light, nutrients, or water."]},{"title":"If something changes","items":["Dark, dirty interiors call for checking excessive thickness and stagnant pockets."]},{"title":"When to check","items":["Check for loose plants after planting; following pruning, light changes, or water changes, track new growth as well as old leaves."]}],"cautions":["Trade names can cover different species; do not assume one temperature from a name. Keep trimmings out of natural waterways.","Temperature reference: Taxiphyllum barbieri, 22–28°C. This is a published range, not an ideal setpoint or permission for sudden temperature changes; other species sold under this common name may differ."],"sources":[{"title":"Tropica · Planting in the aquarium","url":"https://tropica.com/en/guide/get-the-right-start/planting/"},{"title":"Dennerle — Taxiphyllum barbieri","url":"https://dennerleplants.com/en/plants/plantdetails/Taxiphyllum-barbieri-%2830192%29/23040"}]}'::jsonb),
  ('insect_fish', 'preset', '蝾螈', '{"overview":"不同蝾螈的水陆需求差异很大，不能照搬热带鱼缸。","parameters":[],"cycle":null,"sections":[{"title":"开始前与操作","items":["确认准确种名和生活阶段，再定水深、陆地、温度及防逃结构。","先确认生活阶段和物种；分别检查水区、陆区与出水坡道，不能只按“蛙类”设置。"]},{"title":"日常照护与维护","items":["检查进出水、皮肤和剩食，设备吸入口需避免卷入个体。","少接触皮肤，清走残饵；每天从外部观察姿态、体表和水区状态。"]},{"title":"异常先看这里","items":["异常漂浮、皮肤损伤或逃离水区时先复核物种要求与水质。"]},{"title":"检查提醒","items":["变态、季节变化和拒食时复核栖息条件；异常记录照片供专业人员判断。"]}],"cautions":["不抓野生个体回家混养；持续失衡、皮肤病变或明显消瘦应咨询异宠兽医。"],"sources":[{"title":"RSPCA · Caring for exotic pets","url":"https://www.rspca.org.uk/adviceandwelfare/pets/other"}]}'::jsonb, '{"overview":"Salamanders differ greatly in water/land needs; a tropical-fish setup is not universal.","parameters":[],"cycle":null,"sections":[{"title":"Start here","items":["Identify species and life stage before choosing depth, land, temperature, and escape protection.","Identify species and life stage; check water, land, and exit routes rather than using a single frog setup."]},{"title":"Routine care","items":["Inspect water access, skin, and leftovers and guard equipment intakes.","Minimize skin contact and remove leftovers; observe posture, skin, and water conditions from outside each day."]},{"title":"If something changes","items":["For abnormal floating, skin damage, or avoidance of water, review species requirements and water quality."]},{"title":"When to check","items":["Review conditions at metamorphosis, seasonal changes, or appetite loss; photograph abnormalities for professional advice."]}],"cautions":["Do not collect wild animals for mixed housing; persistent imbalance, skin lesions, or weight loss needs an exotics vet."],"sources":[{"title":"RSPCA · Caring for exotic pets","url":"https://www.rspca.org.uk/adviceandwelfare/pets/other"}]}'::jsonb),
  ('insect_fish', 'preset', '螳螂', '{"overview":"留意独居与蜕皮空间，不把多只挤在同一小盒。","parameters":[],"cycle":null,"sections":[{"title":"开始前与操作","items":["辨种后准备稳固攀附和充足悬挂空间，使用防逃通风盖。","拍下成体或幼体特征、发现植物和日期，先确认对象及生活阶段。"]},{"title":"日常照护与维护","items":["看是否正常捕食和攀附，蜕皮前后减少喂食干扰并清走危险残留猎物。","用短时观察代替频繁翻动，记录取食、蜕变和所处植物；及时清除饲养容器中的腐败物。"]},{"title":"异常先看这里","items":["蜕皮时掉落或受伤不要强拉残皮，保持安静并寻求有经验者帮助。"]},{"title":"检查提醒","items":["蜕皮、化蛹或羽化前后减少触碰；变化当天拍照记录，而非按固定天数催促。"]}],"cautions":["不能可靠识别、有毒或有蜇伤风险的种类以远距离观察为主；不跨地区释放饲养个体。"],"sources":[{"title":"RHS · Wildlife in gardens","url":"https://www.rhs.org.uk/wildlife/in-gardens"}]}'::jsonb, '{"overview":"Plan individual space and molting clearance instead of crowding a small box.","parameters":[],"cycle":null,"sections":[{"title":"Start here","items":["After identification, provide stable climbing, hanging clearance, and a ventilated secure lid.","Photograph identifying features, host plant, and date; establish the organism and life stage first."]},{"title":"Routine care","items":["Check hunting and grip, minimize disturbance near molts, and remove leftover prey that could injure it.","Use brief observation instead of repeated disturbance; log feeding, molts, and host plants and remove decaying material from kept enclosures."]},{"title":"If something changes","items":["After a fall or molt injury, do not pull retained skin; keep it quiet and seek experienced advice."]},{"title":"When to check","items":["Minimize handling around molts, pupation, and emergence; record the actual change rather than forcing a calendar."]}],"cautions":["Observe unidentified, venomous, or stinging organisms from a distance; do not release captive individuals in other regions."],"sources":[{"title":"RHS · Wildlife in gardens","url":"https://www.rhs.org.uk/wildlife/in-gardens"}]}'::jsonb),
  ('insect_fish', 'preset', '牛', '{"overview":"用固定巡查记录采食、反刍和行走，日粮随阶段由专业人员核对。","parameters":[],"cycle":null,"sections":[{"title":"开始前与操作","items":["检查饮水、饲槽和防滑通道，保证个体能到达，并留安全操作退路。","按年龄、体况和繁殖阶段向当地兽医或饲养顾问确认日粮；新个体设独立观察区。"]},{"title":"日常照护与维护","items":["逐头观察站卧、反刍和蹄部，记录产奶或体况的明显变化。","每天实际检查饮水是否流出、食槽余量、粪便和行走；不要只记录已投了多少料。"]},{"title":"异常先看这里","items":["明显腹胀、倒地或急性呼吸异常需立即联系兽医，不自行灌药尝试。"]},{"title":"检查提醒","items":["高温、转栏、换料和临近生产时增加巡查；疫苗、驱虫及用药计划交由当地兽医制定。"]}],"cautions":["倒地、明显腹胀、呼吸困难或持续不采食应及时求助；大型动物操作需有安全退路。"],"sources":[]}'::jsonb, '{"overview":"Use consistent intake, rumination, and gait checks with a professionally reviewed stage-specific ration.","parameters":[],"cycle":null,"sections":[{"title":"Start here","items":["Inspect reachable water/feed, non-slip routes, and a safe handling escape route.","Confirm the ration for age, condition, and reproductive stage with a local vet or nutrition adviser; separate newcomers for observation."]},{"title":"Routine care","items":["Observe standing/lying, rumination, and feet individually and note milk/condition changes.","Check that water actually flows, inspect feed leftovers, manure, and gait daily, rather than recording only feed offered."]},{"title":"If something changes","items":["Marked bloat, collapse, or acute breathing problems need immediate veterinary help, not improvised drenching."]},{"title":"When to check","items":["Increase checks during heat, moves, ration changes, and near birth; let a local vet set vaccination, parasite, and medicine plans."]}],"cautions":["Collapse, marked bloating, breathing difficulty, or persistent appetite loss needs prompt help; keep an escape route when handling large animals."],"sources":[]}'::jsonb),
  ('system', 'preset', '遮阳棚', '{"overview":"先观察被晒伤的时段，再决定遮哪里、遮多久。","parameters":[],"cycle":null,"sections":[{"title":"开始前与操作","items":["记录上午与午后日照方向，先遮最强时段；不要同时堵住通风面。","在植物高度放温湿度计，记录晴天午后和夜间读数；留出可操作的通风口。"]},{"title":"日常照护与维护","items":["比较新叶、节间与棚下温度，阴雨或季节转凉时重新评估遮阳。","把开关棚、通风、遮阳的时间与读数一起记下，先试小范围调整。"]},{"title":"异常先看这里","items":["叶色变淡、枝条拉长时查是否遮得过多；不能靠继续施肥补光。"]},{"title":"检查提醒","items":["晴天升温前查通风；寒潮、大风前核对固定件和覆盖层，天气过后复查。"]}],"cautions":["密闭保温可能同时积热、积湿；用电加温遵守设备的防水、间距及防火要求。"],"sources":[{"title":"RHS · Greenhouse ventilation and shading","url":"https://www.rhs.org.uk/garden-features/ventilation-and-shading-greenhouses"}]}'::jsonb, '{"overview":"Observe the damaging exposure period before deciding where and when to shade.","parameters":[],"cycle":null,"sections":[{"title":"Start here","items":["Map morning/afternoon sun and shade the strongest period first without blocking airflow.","Place a thermometer/hygrometer at plant height; record sunny-afternoon and nighttime readings and keep vents accessible."]},{"title":"Routine care","items":["Compare new leaves, internodes, and temperature; review shading in cloudy or cooler weather.","Log venting, covering, and shading alongside readings; try changes on a small area first."]},{"title":"If something changes","items":["For pale, stretched growth, check excessive shade instead of trying to replace light with fertilizer."]},{"title":"When to check","items":["Check ventilation before sunny-day heating; inspect fixings and covers before and after cold or windy weather."]}],"cautions":["A closed cover can trap heat and moisture; electric heating must follow equipment requirements for water protection, clearance, and fire safety."],"sources":[{"title":"RHS · Greenhouse ventilation and shading","url":"https://www.rhs.org.uk/garden-features/ventilation-and-shading-greenhouses"}]}'::jsonb),
  ('insect_fish', 'preset', '河蚌', '{"overview":"河蚌是需要合适食物的滤食动物，不是免维护净水器。","parameters":[],"cycle":null,"sections":[{"title":"开始前与操作","items":["购买前确认物种、成熟水体与食物供应，留能检查的位置，不深埋到无法观察。","购买前确认准确种名、淡水或海水及是否需要陆地区；准备可独立观察的空间。"]},{"title":"日常照护与维护","items":["轻度观察开闭壳和周边沉积，按物种要求管理食物与水流。","观察活动、摄食和躲藏点，清走剩食；更换水或添加药剂前先核对对该物种是否适用。"]},{"title":"异常先看这里","items":["长期张壳无反应或异味需及时检查处理，不能等待它自行把脏水过滤好。"]},{"title":"检查提醒","items":["新入缸、蜕壳或同伴数量变化后增加巡查，记录日期和所做调整。"]}],"cautions":["不要把清洁缸壁或吃残渣理解为不需要喂养，也不要放生或倾倒活体到自然水体。"],"sources":[{"title":"OATA · Freshwater aquarium care","url":"https://ornamentalfish.org/what-we-do/advice-information/care-sheets/caresheets-tropical-freshwater-fish/how-to-set-up-and-look-after-a-freshwater-tank-aquarium/"}]}'::jsonb, '{"overview":"Freshwater mussels need suitable food; they are not maintenance-free filters.","parameters":[],"cycle":null,"sections":[{"title":"Start here","items":["Confirm species, established conditions, and food supply before purchase and retain inspection access.","Confirm the species, freshwater/marine requirements, and any land area before purchase; prepare a separate observation space."]},{"title":"Routine care","items":["Observe opening/closing and deposits without repeated disturbance; manage species-appropriate food and flow.","Check activity, feeding, and hiding places and remove leftovers; verify species suitability before water additives or medication."]},{"title":"If something changes","items":["Persistent unresponsive gaping or odor needs prompt assessment, not waiting for the animal to clean dirty water."]},{"title":"When to check","items":["Increase checks after introduction, molts, or changes in companions; record dates and adjustments."]}],"cautions":["Grazing algae or scraps does not mean no feeding is needed; never release animals into natural water."],"sources":[{"title":"OATA · Freshwater aquarium care","url":"https://ornamentalfish.org/what-we-do/advice-information/care-sheets/caresheets-tropical-freshwater-fish/how-to-set-up-and-look-after-a-freshwater-tank-aquarium/"}]}'::jsonb),
  ('insect_fish', 'preset', '蜗牛', '{"overview":"以观察爬行、取食和壳体状态为主，避免干晒和粗暴揭取。","parameters":[],"cycle":null,"sections":[{"title":"开始前与操作","items":["留阴湿躲藏与通风区，食物来源无农药；不强拉黏附在表面的个体。","先在原处观察，若饲养需确认来源与物种；准备通风、防逃逸且无农药残留的容器。"]},{"title":"日常照护与维护","items":["换走腐败食物，检查壳口和活动，固定角度记录壳体变化。","每天移走变质食物并检查角落积水、霉点和盖子；洗手后再接触用具。"]},{"title":"异常先看这里","items":["壳受伤或长时间缩闭时先查外伤、干燥与环境改变，不随意盐洗。"]},{"title":"检查提醒","items":["高温、干燥或更换基质后查看活动变化；保留湿度差异，不让整个容器积水。"]}],"cautions":["不徒手接触黏液后揉眼或拿食物；野采个体不要混入家庭饲养群。"],"sources":[{"title":"RHS · Wildlife in gardens","url":"https://www.rhs.org.uk/wildlife/in-gardens"}]}'::jsonb, '{"overview":"Observe movement, feeding, and shell condition without sun-drying or forced removal.","parameters":[],"cycle":null,"sections":[{"title":"Start here","items":["Provide shaded moist cover and ventilation; use pesticide-free food and do not pull attached animals.","Prefer observation in place; for kept animals confirm species/source and use a ventilated, escape-resistant, pesticide-free enclosure."]},{"title":"Routine care","items":["Replace spoiled food, inspect the shell opening/activity, and repeat shell photos.","Remove spoiled food and check corners for pooling, mold, and lid gaps daily; wash hands when handling equipment."]},{"title":"If something changes","items":["For shell damage or prolonged withdrawal, inspect injury, dryness, and changes; never salt-wash."]},{"title":"When to check","items":["Watch activity after heat, dry weather, or substrate changes; offer a moisture gradient without flooding the enclosure."]}],"cautions":["Avoid touching eyes or food after contact with mucus; do not mix wild-caught individuals into kept groups."],"sources":[{"title":"RHS · Wildlife in gardens","url":"https://www.rhs.org.uk/wildlife/in-gardens"}]}'::jsonb)
) as seed(category, source, name, content_zh, content_en)
join public.guide_entries as e on e.category = seed.category
  and e.source = seed.source and e.name = seed.name
on conflict (guide_id) do nothing;

